INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bd8b7be0-1544-45d1-821a-2694ceff66b7', 'CWE-5', 'J2EE Misconfiguration: Data Transmission Without Encryption', 'Information sent over a network can be compromised while in transit. An attacker may be able to read or modify the contents if the data are sent in plaintext or are weakly encrypted.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('09abe47e-a4ef-49bc-91c7-70aa5d505493', 'CWE-6', 'J2EE Misconfiguration: Insufficient Session-ID Length', 'The J2EE application is configured to use an insufficient session ID length.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('88d707c0-0868-430c-acc6-0a37d8269d44', 'CWE-7', 'J2EE Misconfiguration: Missing Custom Error Page', 'The default error page of a web application should not display sensitive information about the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0fca9211-a77f-491d-bcec-a8189afb0f3f', 'CWE-8', 'J2EE Misconfiguration: Entity Bean Declared Remote', 'When an application exposes a remote interface for an entity bean, it might also expose methods that get or set the bean''s data. These methods could be leveraged to read sensitive information, or to change data in ways that violate the application''s expectations, potentially leading to other vulnerabilities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cdaab8f3-ee1b-48fa-aeea-741d06ceb40e', 'CWE-9', 'J2EE Misconfiguration: Weak Access Permissions for EJB Methods', 'If elevated access rights are assigned to EJB methods, then an attacker can take advantage of the permissions to exploit the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7a59505c-88de-47fe-adfb-47a103699ee4', 'CWE-11', 'ASP.NET Misconfiguration: Creating Debug Binary', 'Debugging messages help attackers learn about the system and plan a form of attack.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('05d0d048-3e80-4f6b-9b35-e88968ef3755', 'CWE-12', 'ASP.NET Misconfiguration: Missing Custom Error Page', 'An ASP .NET application must enable custom error pages in order to prevent attackers from mining information from the framework''s built-in responses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0f6d22d9-4305-4a22-9e10-1d9736ea76a8', 'CWE-13', 'ASP.NET Misconfiguration: Password in Configuration File', 'Storing a plaintext password in a configuration file allows anyone who can read the file access to the password-protected resource making them an easy target for attackers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d6974a9e-8ca3-407c-8384-726e85773d5e', 'CWE-14', 'Compiler Removal of Code to Clear Buffers', 'Sensitive memory is cleared according to the source code, but compiler optimizations leave the memory untouched when it is not read from again, aka dead store removal.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('89db0cc5-4f2b-4856-b2da-56fb77da278b', 'CWE-15', 'External Control of System or Configuration Setting', 'One or more system settings or configuration elements can be externally controlled by a user.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('109e5062-575b-4d47-8d9b-35d53ec02cbf', 'CWE-20', 'Improper Input Validation', 'The product receives input or data, but it does not validate or incorrectly validates that the input has the properties that are required to process the data safely and correctly.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fa9d9ec0-39b0-45b0-b437-86bd9482fc4a', 'CWE-22', 'Improper Limitation of a Pathname to a Restricted Directory (''Path Traversal'')', 'The product uses external input to construct a pathname that is intended to identify a file or directory that is located underneath a restricted parent directory, but the product does not properly neutralize special elements within the pathname that can cause the pathname to resolve to a location that is outside of the restricted directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8bf8bf9b-3e0d-4eeb-8946-19f9ddb69fb8', 'CWE-23', 'Relative Path Traversal', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize sequences such as .. that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e69573bf-409e-4e31-8b43-6232a021d6b1', 'CWE-24', 'Path Traversal: ''../filedir''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ../ sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b4a73f36-8a1b-408b-9295-ac2e4f7d7921', 'CWE-25', 'Path Traversal: ''/../filedir''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize /../ sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('64aee441-8180-46bb-b6bc-27fa65e3d0af', 'CWE-26', 'Path Traversal: ''/dir/../filename''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize /dir/../filename sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dc66b212-5095-4119-af72-87a587458284', 'CWE-27', 'Path Traversal: ''dir/../../filename''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize multiple internal ../ sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3f3d2c04-e12a-4bb3-978f-28a525c4fc5e', 'CWE-28', 'Path Traversal: ''..filedir''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize .. sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9df76fb7-063f-40da-b2f1-51b2d69b906a', 'CWE-29', 'Path Traversal: ''..filename''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ''..filename'' (leading backslash dot dot) sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('175facae-9123-4001-97db-9195dbe2134e', 'CWE-30', 'Path Traversal: ''dir..filename''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ''dir..filename'' (leading backslash dot dot) sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e17b730f-8059-4b48-94cf-fa7dd97c7a49', 'CWE-31', 'Path Traversal: ''dir....filename''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ''dir....filename'' (multiple internal backslash dot dot) sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8fb6ee8b-449b-49a1-a21c-b23517e7dcf2', 'CWE-32', 'Path Traversal: ''...'' (Triple Dot)', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ''...'' (triple dot) sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('20a0723a-1c1d-4fb2-a21a-2981296a895f', 'CWE-33', 'Path Traversal: ''....'' (Multiple Dot)', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ''....'' (multiple dot) sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f2bd9d69-4ad1-4626-954a-b0aeb57d12af', 'CWE-34', 'Path Traversal: ''....//''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ''....//'' (doubled dot dot slash) sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fdcd674a-4212-4321-aea1-9a9d3007cf23', 'CWE-35', 'Path Traversal: ''.../...//''', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize ''.../...//'' (doubled triple dot slash) sequences that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8bc1b881-3bbb-48fe-9b8e-978cb6848422', 'CWE-36', 'Absolute Path Traversal', 'The product uses external input to construct a pathname that should be within a restricted directory, but it does not properly neutralize absolute path sequences such as /abs/path that can resolve to a location that is outside of that directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('94728273-003f-414f-b82f-127e9315341c', 'CWE-37', 'Path Traversal: ''/absolute/pathname/here''', 'The product accepts input in the form of a slash absolute path (''/absolute/pathname/here'') without appropriate validation, which can allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0bcc6103-775d-42fd-8aa5-c38b77c848f5', 'CWE-38', 'Path Traversal: ''absolutepathnamehere''', 'The product accepts input in the form of a backslash absolute path (''absolutepathnamehere'') without appropriate validation, which can allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9904987e-ea95-4119-b49f-00b902527033', 'CWE-39', 'Path Traversal: ''C:dirname''', 'The product accepts input that contains a drive letter or Windows volume letter (''C:dirname'') that potentially redirects access to an unintended location or arbitrary file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fe9a357e-46a3-48a2-a938-8a6304e326b2', 'CWE-40', 'Path Traversal: ''UNCsharename'' (Windows UNC Share)', 'The product accepts input that identifies a Windows UNC share (''UNCsharename'') that potentially redirects access to an unintended location or arbitrary file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7d379dd9-cea2-4e09-8c45-f8920d199bd6', 'CWE-41', 'Improper Resolution of Path Equivalence', 'The product is vulnerable to file system contents disclosure through path equivalence. Path equivalence involves the use of special characters in file and directory names. The associated manipulations are intended to generate multiple names for the same object.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8401403d-611e-4727-bf01-d69a6c292072', 'CWE-42', 'Path Equivalence: ''filename.'' (Trailing Dot)', 'The product accepts path input in the form of trailing dot (''filedir.'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f12e5f8b-a127-4837-9b5d-20568ccd3c17', 'CWE-43', 'Path Equivalence: ''filename....'' (Multiple Trailing Dot)', 'The product accepts path input in the form of multiple trailing dot (''filedir....'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5e33dbaf-6887-4478-b62f-ed475da45958', 'CWE-44', 'Path Equivalence: ''file.name'' (Internal Dot)', 'The product accepts path input in the form of internal dot (''file.ordir'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('73d16ef9-5497-4659-a11a-ea4c1a5096bd', 'CWE-45', 'Path Equivalence: ''file...name'' (Multiple Internal Dot)', 'The product accepts path input in the form of multiple internal dot (''file...dir'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b288a63a-26be-4261-a88f-29a850779a05', 'CWE-46', 'Path Equivalence: ''filename '' (Trailing Space)', 'The product accepts path input in the form of trailing space (''filedir '') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a8001f25-1ad2-4a99-bd2b-97746093b839', 'CWE-47', 'Path Equivalence: '' filename'' (Leading Space)', 'The product accepts path input in the form of leading space ('' filedir'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5a498d8c-0df2-4db4-82cb-18028bca346d', 'CWE-48', 'Path Equivalence: ''file name'' (Internal Whitespace)', 'The product accepts path input in the form of internal space (''file(SPACE)name'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('87f16dad-0f76-4e3f-a7ec-ee8a4450c3bd', 'CWE-49', 'Path Equivalence: ''filename/'' (Trailing Slash)', 'The product accepts path input in the form of trailing slash (''filedir/'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('73722eda-f3be-4f01-a273-8af5f61e9b86', 'CWE-50', 'Path Equivalence: ''//multiple/leading/slash''', 'The product accepts path input in the form of multiple leading slash (''//multiple/leading/slash'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b0deaee0-0f1d-4e17-991d-7f9d22270a2d', 'CWE-51', 'Path Equivalence: ''/multiple//internal/slash''', 'The product accepts path input in the form of multiple internal slash (''/multiple//internal/slash/'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d131b695-5d62-448f-ae50-d1e83ec9e3e5', 'CWE-52', 'Path Equivalence: ''/multiple/trailing/slash//''', 'The product accepts path input in the form of multiple trailing slash (''/multiple/trailing/slash//'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('05f28170-694b-4d8f-89bd-1d302769327b', 'CWE-53', 'Path Equivalence: ''multipleinternalbackslash''', 'The product accepts path input in the form of multiple internal backslash (''multipletrailingslash'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8a70f6a2-3c9f-4d7c-9da9-4c3c0bfd5405', 'CWE-54', 'Path Equivalence: ''filedir'' (Trailing Backslash)', 'The product accepts path input in the form of trailing backslash (''filedir'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('81ed2011-08b4-44da-8294-3ac31438836e', 'CWE-55', 'Path Equivalence: ''/./'' (Single Dot Directory)', 'The product accepts path input in the form of single dot directory exploit (''/./'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('db462ec3-73c9-4009-9425-70dfa6275a94', 'CWE-56', 'Path Equivalence: ''filedir*'' (Wildcard)', 'The product accepts path input in the form of asterisk wildcard (''filedir*'') without appropriate validation, which can lead to ambiguous path resolution and allow an attacker to traverse the file system to unintended locations or access arbitrary files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8791e855-e2b7-4593-a694-dcb64d61b999', 'CWE-57', 'Path Equivalence: ''fakedir/../realdir/filename''', 'The product contains protection mechanisms to restrict access to ''realdir/filename'', but it constructs pathnames using external input in the form of ''fakedir/../realdir/filename'' that are not handled by those mechanisms. This allows attackers to perform unauthorized actions against the targeted file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8bd91d31-bc9a-41ac-98ed-eff4bf9954c3', 'CWE-58', 'Path Equivalence: Windows 8.3 Filename', 'The product contains a protection mechanism that restricts access to a long filename on a Windows operating system, but it does not properly restrict access to the equivalent short 8.3 filename.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b6bbce31-f306-4f1d-9b00-c4ebed358df9', 'CWE-59', 'Improper Link Resolution Before File Access (''Link Following'')', 'The product attempts to access a file based on the filename, but it does not properly prevent that filename from identifying a link or shortcut that resolves to an unintended resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a2738c2f-4eb7-4901-a652-41e36f54b433', 'CWE-61', 'UNIX Symbolic Link (Symlink) Following', 'The product, when opening a file or directory, does not sufficiently account for when the file is a symbolic link that resolves to a target outside of the intended control sphere. This could allow an attacker to cause the product to operate on unauthorized files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d0d16aed-ef76-41c4-8d2d-f8fcdc9d8156', 'CWE-62', 'UNIX Hard Link', 'The product, when opening a file or directory, does not sufficiently account for when the name is associated with a hard link to a target that is outside of the intended control sphere. This could allow an attacker to cause the product to operate on unauthorized files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a00322c9-83a9-408b-91a2-599e74f14c43', 'CWE-64', 'Windows Shortcut Following (.LNK)', 'The product, when opening a file or directory, does not sufficiently handle when the file is a Windows shortcut (.LNK) whose target is outside of the intended control sphere. This could allow an attacker to cause the product to operate on unauthorized files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a02ee3ad-3573-4294-b718-7b6ce8dfff0f', 'CWE-65', 'Windows Hard Link', 'The product, when opening a file or directory, does not sufficiently handle when the name is associated with a hard link to a target that is outside of the intended control sphere. This could allow an attacker to cause the product to operate on unauthorized files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ed98e507-5054-4976-b833-0e1e6c460f92', 'CWE-66', 'Improper Handling of File Names that Identify Virtual Resources', 'The product does not handle or incorrectly handles a file name that identifies a virtual resource that is not directly specified within the directory that is associated with the file name, causing the product to perform file-based operations on a resource that is not a file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fcc36d14-9c93-4657-9000-301addaa8914', 'CWE-67', 'Improper Handling of Windows Device Names', 'The product constructs pathnames from user input, but it does not handle or incorrectly handles a pathname containing a Windows device name such as AUX or CON. This typically leads to denial of service or an information exposure when the application attempts to process the pathname as a regular file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('11340a41-0eab-4540-9dae-281ef72045fa', 'CWE-69', 'Improper Handling of Windows ::DATA Alternate Data Stream', 'The product does not properly prevent access to, or detect usage of, alternate data streams (ADS).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('562b8f9c-0dcf-4b55-aa39-697c05399500', 'CWE-72', 'Improper Handling of Apple HFS+ Alternate Data Stream Path', 'The product does not properly handle special paths that may identify the data or resource fork of a file on the HFS+ file system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('98b6b488-3dbc-49b9-ac08-e869dd516f7d', 'CWE-73', 'External Control of File Name or Path', 'The product allows user input to control or influence paths or file names that are used in filesystem operations.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('41fe56d5-45a9-4715-81ab-79c19f79e46b', 'CWE-74', 'Improper Neutralization of Special Elements in Output Used by a Downstream Component (''Injection'')', 'The product constructs all or part of a command, data structure, or record using externally-influenced input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could modify how it is parsed or interpreted when it is sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6c5d2b46-c767-480f-9289-ee664c24ce83', 'CWE-75', 'Failure to Sanitize Special Elements into a Different Plane (Special Element Injection)', 'The product does not adequately filter user-controlled input for special elements with control implications.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('500d8a49-3c98-43c7-b605-dfbd6963ed08', 'CWE-76', 'Improper Neutralization of Equivalent Special Elements', 'The product correctly neutralizes certain special elements, but it improperly neutralizes equivalent special elements.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('42e280fe-5d43-4c3d-989c-a4183e13f067', 'CWE-77', 'Improper Neutralization of Special Elements used in a Command (''Command Injection'')', 'The product constructs all or part of a command using externally-influenced input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could modify the intended command when it is sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7b0e295c-2f04-4cbe-a2b2-6f6a63934bf2', 'CWE-78', 'Improper Neutralization of Special Elements used in an OS Command (''OS Command Injection'')', 'The product constructs all or part of an OS command using externally-influenced input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could modify the intended OS command when it is sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e3270fcb-cf99-4f9e-9b6d-851f9ed886f3', 'CWE-79', 'Improper Neutralization of Input During Web Page Generation (''Cross-site Scripting'')', 'The product does not neutralize or incorrectly neutralizes user-controllable input before it is placed in output that is used as a web page that is served to other users.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('63f509ee-bec5-4c52-b7cf-586bfbd321ee', 'CWE-80', 'Improper Neutralization of Script-Related HTML Tags in a Web Page (Basic XSS)', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special characters such as <, >, and & that could be interpreted as web-scripting elements when they are sent to a downstream component that processes web pages.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f9c09c31-f53b-4b7f-8301-f36f26b81387', 'CWE-81', 'Improper Neutralization of Script in an Error Message Web Page', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special characters that could be interpreted as web-scripting elements when they are sent to an error page.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a593ed07-a881-451d-b7d5-32995fdf8ac7', 'CWE-82', 'Improper Neutralization of Script in Attributes of IMG Tags in a Web Page', 'The web application does not neutralize or incorrectly neutralizes scripting elements within attributes of HTML IMG tags, such as the src attribute.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3c00b54b-df2b-40b2-9a8b-ad7ad8c3a391', 'CWE-83', 'Improper Neutralization of Script in Attributes in a Web Page', 'The product does not neutralize or incorrectly neutralizes javascript: or other URIs from dangerous attributes within tags, such as onmouseover, onload, onerror, or style.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f533efc5-f446-4b87-91b9-71a20e0b8d50', 'CWE-84', 'Improper Neutralization of Encoded URI Schemes in a Web Page', 'The web application improperly neutralizes user-controlled input for executable script disguised with URI encodings.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('38ab9ff3-6ee8-420b-a0e0-04385464ac30', 'CWE-85', 'Doubled Character XSS Manipulations', 'The web application does not filter user-controlled input for executable script disguised using doubling of the involved characters.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f9b15225-2f65-4b6f-9095-df01b124c8b2', 'CWE-86', 'Improper Neutralization of Invalid Characters in Identifiers in Web Pages', 'The product does not neutralize or incorrectly neutralizes invalid characters or byte sequences in the middle of tag names, URI schemes, and other identifiers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1a118c8e-1dcc-4ac2-801b-1372bd602eb8', 'CWE-87', 'Improper Neutralization of Alternate XSS Syntax', 'The product does not neutralize or incorrectly neutralizes user-controlled input for alternate script syntax.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8de43461-d431-47ea-8325-c6822187437f', 'CWE-88', 'Improper Neutralization of Argument Delimiters in a Command (''Argument Injection'')', 'The product constructs a string for a command to be executed by a separate component in another control sphere, but it does not properly delimit the intended arguments, options, or switches within that command string.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b30e635d-534c-4c2b-9675-65819c0dd6d5', 'CWE-89', 'Improper Neutralization of Special Elements used in an SQL Command (''SQL Injection'')', 'The product constructs all or part of an SQL command using externally-influenced input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could modify the intended SQL command when it is sent to a downstream component. Without sufficient removal or quoting of SQL syntax in user-controllable inputs, the generated SQL query can cause those inputs to be interpreted as SQL instead of ordinary user data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d2776367-a24e-40a3-a198-57022cc3f794', 'CWE-90', 'Improper Neutralization of Special Elements used in an LDAP Query (''LDAP Injection'')', 'The product constructs all or part of an LDAP query using externally-influenced input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could modify the intended LDAP query when it is sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aaef4613-a475-40e1-8af3-bced7b315ad9', 'CWE-91', 'XML Injection (aka Blind XPath Injection)', 'The product does not properly neutralize special elements that are used in XML, allowing attackers to modify the syntax, content, or commands of the XML before it is processed by an end system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0153fd9f-8369-426c-9b19-2918e962908a', 'CWE-93', 'Improper Neutralization of CRLF Sequences (''CRLF Injection'')', 'The product uses CRLF (carriage return line feeds) as a special element, e.g. to separate lines or records, but it does not neutralize or incorrectly neutralizes CRLF sequences from inputs.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e38fca36-59b0-4692-8d98-04c0801a89a5', 'CWE-94', 'Improper Control of Generation of Code (''Code Injection'')', 'The product constructs all or part of a code segment using externally-influenced input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could modify the syntax or behavior of the intended code segment.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('220e9791-689b-4495-843a-6456f1b2d189', 'CWE-95', 'Improper Neutralization of Directives in Dynamically Evaluated Code (''Eval Injection'')', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes code syntax before using the input in a dynamic evaluation call (e.g. eval).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9706148a-3be4-42a7-b4b6-a2eb42fc5a4f', 'CWE-96', 'Improper Neutralization of Directives in Statically Saved Code (''Static Code Injection'')', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes code syntax before inserting the input into an executable resource, such as a library, configuration file, or template.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9ff55de6-8198-4feb-addf-28a3cbd20488', 'CWE-97', 'Improper Neutralization of Server-Side Includes (SSI) Within a Web Page', 'The product generates a web page, but does not neutralize or incorrectly neutralizes user-controllable input that could be interpreted as a server-side include (SSI) directive.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6873354d-be9f-4a2b-838a-3f3086c1d677', 'CWE-98', 'Improper Control of Filename for Include/Require Statement in PHP Program (''PHP Remote File Inclusion'')', 'The PHP application receives input from an upstream component, but it does not restrict or incorrectly restricts the input before its usage in require, include, or similar functions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('438322d8-2685-421d-b339-73f6d18876f4', 'CWE-99', 'Improper Control of Resource Identifiers (''Resource Injection'')', 'The product receives input from an upstream component, but it does not restrict or incorrectly restricts the input before it is used as an identifier for a resource that may be outside the intended sphere of control.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c24f2192-e172-4daa-9df3-3317f90f3a4c', 'CWE-102', 'Struts: Duplicate Validation Forms', 'The product uses multiple validation forms with the same name, which might cause the Struts Validator to validate a form that the programmer does not expect.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f2b36365-acb8-4901-be61-6ae76b4dba49', 'CWE-103', 'Struts: Incomplete validate() Method Definition', 'The product has a validator form that either does not define a validate() method, or defines a validate() method but does not call super.validate().', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('984c7ad5-21e6-44a5-aabd-4bd7afe302cd', 'CWE-104', 'Struts: Form Bean Does Not Extend Validation Class', 'If a form bean does not extend an ActionForm subclass of the Validator framework, it can expose the application to other weaknesses related to insufficient input validation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1c6b82cd-a60c-41d4-ba7f-21460bc74fa4', 'CWE-105', 'Struts: Form Field Without Validator', 'The product has a form field that is not validated by a corresponding validation form, which can introduce other weaknesses related to insufficient input validation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f13a33bf-ec3a-4029-b736-ea4bcb077c8a', 'CWE-106', 'Struts: Plug-in Framework not in Use', 'When an application does not use an input validation framework such as the Struts Validator, there is a greater risk of introducing weaknesses related to insufficient input validation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e7f4619e-9a73-487f-a156-02955f1c7719', 'CWE-107', 'Struts: Unused Validation Form', 'An unused validation form indicates that validation logic is not up-to-date.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1b802dcf-6817-476f-b34f-095931aad337', 'CWE-108', 'Struts: Unvalidated Action Form', 'Every Action Form must have a corresponding validation form.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e2ef4ac6-0f51-46b1-950d-ea387d026007', 'CWE-109', 'Struts: Validator Turned Off', 'Automatic filtering via a Struts bean has been turned off, which disables the Struts Validator and custom validation logic. This exposes the application to other weaknesses related to insufficient input validation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('35fde9b9-02b6-4e5a-88c9-17aac76c992f', 'CWE-110', 'Struts: Validator Without Form Field', 'Validation fields that do not appear in forms they are associated with indicate that the validation logic is out of date.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7d5874f0-c4c2-40ec-9835-82e4d5854931', 'CWE-111', 'Direct Use of Unsafe JNI', 'When a Java application uses the Java Native Interface (JNI) to call code written in another programming language, it can expose the application to weaknesses in that code, even if those weaknesses cannot occur in Java.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('296de960-96ab-42f1-9a91-fdff2d55ee8b', 'CWE-112', 'Missing XML Validation', 'The product accepts XML from an untrusted source but does not validate the XML against the proper schema.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6841f436-98d0-411c-8811-168087d6c4ac', 'CWE-113', 'Improper Neutralization of CRLF Sequences in HTTP Headers (''HTTP Request/Response Splitting'')', 'The product receives data from an HTTP agent/component (e.g., web server, proxy, browser, etc.), but it does not neutralize or incorrectly neutralizes CR and LF characters before the data is included in outgoing HTTP headers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('20e8c231-c22a-4623-84f0-c3cdcfc618ac', 'CWE-114', 'Process Control', 'Executing commands or loading libraries from an untrusted source or in an untrusted environment can cause an application to execute malicious commands (and payloads) on behalf of an attacker.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4d4f4650-638b-493e-8eca-8518db9af4ae', 'CWE-115', 'Misinterpretation of Input', 'The product misinterprets an input, whether from an attacker or another product, in a security-relevant fashion.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8bc52729-68f5-46b5-9134-418eafe258a2', 'CWE-116', 'Improper Encoding or Escaping of Output', 'The product prepares a structured message for communication with another component, but encoding or escaping of the data is either missing or done incorrectly. As a result, the intended structure of the message is not preserved.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('557e1bce-66a7-408f-837e-e0cd5e4bf434', 'CWE-117', 'Improper Output Neutralization for Logs', 'The product constructs a log message from external input, but it does not neutralize or incorrectly neutralizes special elements when the message is written to a log file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d2ce957b-07bb-436d-bfca-30cb2a820f3c', 'CWE-118', 'Incorrect Access of Indexable Resource (''Range Error'')', 'The product does not restrict or incorrectly restricts operations within the boundaries of a resource that is accessed using an index or pointer, such as memory or files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ff602fe4-abdc-4c73-b0a6-95f1b04dd144', 'CWE-119', 'Improper Restriction of Operations within the Bounds of a Memory Buffer', 'The product performs operations on a memory buffer, but it reads from or writes to a memory location outside the buffer''s intended boundary. This may result in read or write operations on unexpected memory locations that could be linked to other variables, data structures, or internal program data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1759f3e6-4ecb-4982-9990-6233b7e9ca5c', 'CWE-120', 'Buffer Copy without Checking Size of Input (''Classic Buffer Overflow'')', 'The product copies an input buffer to an output buffer without verifying that the size of the input buffer is less than the size of the output buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e37b9ce5-dea5-464e-9229-089a080cb5ee', 'CWE-121', 'Stack-based Buffer Overflow', 'A stack-based buffer overflow condition is a condition where the buffer being overwritten is allocated on the stack (i.e., is a local variable or, rarely, a parameter to a function).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b85619ce-76c9-4f6b-87fd-f05a2c4c2223', 'CWE-122', 'Heap-based Buffer Overflow', 'A heap overflow condition is a buffer overflow, where the buffer that can be overwritten is allocated in the heap portion of memory, generally meaning that the buffer was allocated using a routine such as malloc().', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('06bc3a26-8326-4320-a459-637e62eef896', 'CWE-123', 'Write-what-where Condition', 'Any condition where the attacker has the ability to write an arbitrary value to an arbitrary location, often as the result of a buffer overflow.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b253c9be-e8ed-4fef-a44b-8b88e4730a68', 'CWE-124', 'Buffer Underwrite (''Buffer Underflow'')', 'The product writes to a buffer using an index or pointer that references a memory location prior to the beginning of the buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ca49b5e8-9c30-4a6a-b0ce-dfa9241337f4', 'CWE-125', 'Out-of-bounds Read', 'The product reads data past the end, or before the beginning, of the intended buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('92a3c5e4-4f43-4aeb-b65a-1aa90b5e877d', 'CWE-126', 'Buffer Over-read', 'The product reads from a buffer using buffer access mechanisms such as indexes or pointers that reference memory locations after the targeted buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8ced9ebf-9dd5-4c5d-8b0a-4a979f10fbfd', 'CWE-127', 'Buffer Under-read', 'The product reads from a buffer using buffer access mechanisms such as indexes or pointers that reference memory locations prior to the targeted buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('42c1211b-edf8-423d-bb1c-64db757331a4', 'CWE-128', 'Wrap-around Error', 'Wrap around errors occur whenever a value is incremented past the maximum value for its type and therefore wraps around to a very small, negative, or undefined value.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('92454045-4f73-4bf9-b728-40506293dbae', 'CWE-129', 'Improper Validation of Array Index', 'The product uses untrusted input when calculating or using an array index, but the product does not validate or incorrectly validates the index to ensure the index references a valid position within the array.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6cf0dda3-932e-40b3-ac56-ecebe8c0f3b0', 'CWE-130', 'Improper Handling of Length Parameter Inconsistency', 'The product parses a formatted message or structure, but it does not handle or incorrectly handles a length field that is inconsistent with the actual length of the associated data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e0e17f62-dfe5-428c-b693-4a99b699cc90', 'CWE-131', 'Incorrect Calculation of Buffer Size', 'The product does not correctly calculate the size to be used when allocating a buffer, which could lead to a buffer overflow.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('13970123-c966-4d0a-b427-e07c314a54f4', 'CWE-134', 'Use of Externally-Controlled Format String', 'The product uses a function that accepts a format string as an argument, but the format string originates from an external source.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a815c9aa-3847-42e1-ae65-f3422e3e9bc2', 'CWE-135', 'Incorrect Calculation of Multi-Byte String Length', 'The product does not correctly calculate the length of strings that can contain wide or multi-byte characters.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0ee30816-94fb-42b8-973e-ad6678bef908', 'CWE-138', 'Improper Neutralization of Special Elements', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as control elements or syntactic markers when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('08e68550-269c-46a5-ba1f-6c3b2830459e', 'CWE-140', 'Improper Neutralization of Delimiters', 'The product does not neutralize or incorrectly neutralizes delimiters.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('23a3d196-892b-43e2-a818-eaec82fc6b70', 'CWE-141', 'Improper Neutralization of Parameter/Argument Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as parameter or argument delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8a2c67f5-95ff-42bd-b839-7306676a904c', 'CWE-142', 'Improper Neutralization of Value Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as value delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5d86ebc5-80d4-49a6-b9aa-ec780e7e74a9', 'CWE-143', 'Improper Neutralization of Record Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as record delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ccbadcb7-27be-4e76-b957-3704e2324f89', 'CWE-144', 'Improper Neutralization of Line Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as line delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ebdd0976-935e-46b8-afbb-576129279ad7', 'CWE-145', 'Improper Neutralization of Section Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as section delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2e0dab97-69b7-498b-87a2-d93b8cb1fffc', 'CWE-146', 'Improper Neutralization of Expression/Command Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as expression or command delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d8b577e3-5fd8-49d0-9731-4f495dae6a49', 'CWE-147', 'Improper Neutralization of Input Terminators', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as input terminators when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6a096420-c841-4c51-9bfb-fa6158b4b314', 'CWE-148', 'Improper Neutralization of Input Leaders', 'The product does not properly handle when a leading character or sequence (leader) is missing or malformed, or if multiple leaders are used when only one should be allowed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c54fc104-2e6f-4d6c-8008-f4ec15fcf27f', 'CWE-149', 'Improper Neutralization of Quoting Syntax', 'Quotes injected into a product can be used to compromise a system. As data are parsed, an injected/absent/duplicate/malformed use of quotes may cause the process to take unexpected actions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1c052135-99b0-48d8-8c3c-b9bb2666efdf', 'CWE-150', 'Improper Neutralization of Escape, Meta, or Control Sequences', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as escape, meta, or control character sequences when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('29e9e301-6ee4-471e-b847-8307800cb0fe', 'CWE-151', 'Improper Neutralization of Comment Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as comment delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('94f61696-5469-4a32-bc54-c9b79b22a744', 'CWE-152', 'Improper Neutralization of Macro Symbols', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as macro symbols when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d9b9c40f-14e7-4bb3-b742-ae0f2a31962d', 'CWE-153', 'Improper Neutralization of Substitution Characters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as substitution characters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('09174fd1-4afd-48a3-9b51-980489f22186', 'CWE-154', 'Improper Neutralization of Variable Name Delimiters', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as variable name delimiters when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('905b5dca-011c-4811-8a04-c063d5cc50e8', 'CWE-155', 'Improper Neutralization of Wildcards or Matching Symbols', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as wildcards or matching symbols when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e76fa99e-e9d0-468b-9223-e5f2c46b1743', 'CWE-156', 'Improper Neutralization of Whitespace', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as whitespace when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a1f4fbb9-54b4-4f31-8def-a6e99b8cd2a6', 'CWE-157', 'Failure to Sanitize Paired Delimiters', 'The product does not properly handle the characters that are used to mark the beginning and ending of a group of entities, such as parentheses, brackets, and braces.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('226e865c-0a3d-415b-90bc-de19ddf1f6c0', 'CWE-158', 'Improper Neutralization of Null Byte or NUL Character', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes NUL characters or null bytes when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7d471e48-0bfe-431c-9cd3-a45e63fa4490', 'CWE-159', 'Improper Handling of Invalid Use of Special Elements', 'The product does not properly filter, remove, quote, or otherwise manage the invalid use of special elements in user-controlled input, which could cause adverse effect on its behavior and integrity.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('97798ac5-95c8-42f2-8e0f-5ad038db9c5b', 'CWE-160', 'Improper Neutralization of Leading Special Elements', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes leading special elements that could be interpreted in unexpected ways when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7197dc4a-db9e-47d3-ae31-96b5bfb27408', 'CWE-161', 'Improper Neutralization of Multiple Leading Special Elements', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes multiple leading special elements that could be interpreted in unexpected ways when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6bb65465-6bc9-49c4-a3f7-3a334fe100b2', 'CWE-162', 'Improper Neutralization of Trailing Special Elements', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes trailing special elements that could be interpreted in unexpected ways when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d009a52f-d16c-4f94-9a98-113dc56b81d5', 'CWE-163', 'Improper Neutralization of Multiple Trailing Special Elements', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes multiple trailing special elements that could be interpreted in unexpected ways when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('94d01c58-4eb5-4091-a95b-34e6f6ec49ba', 'CWE-164', 'Improper Neutralization of Internal Special Elements', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes internal special elements that could be interpreted in unexpected ways when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('15ea8cc2-cc96-4671-9ec5-4fbf8ae3853f', 'CWE-165', 'Improper Neutralization of Multiple Internal Special Elements', 'The product receives input from an upstream component, but it does not neutralize or incorrectly neutralizes multiple internal special elements that could be interpreted in unexpected ways when they are sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4dbc4ae5-12e1-4c2b-88c0-da30da2e418f', 'CWE-166', 'Improper Handling of Missing Special Element', 'The product receives input from an upstream component, but it does not handle or incorrectly handles when an expected special element is missing.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6db417d2-3ec6-485b-94f7-52f56f49d015', 'CWE-167', 'Improper Handling of Additional Special Element', 'The product receives input from an upstream component, but it does not handle or incorrectly handles when an additional unexpected special element is provided.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f7f9edb8-e484-4fc3-bbc0-1fd451ec16f6', 'CWE-168', 'Improper Handling of Inconsistent Special Elements', 'The product does not properly handle input in which an inconsistency exists between two or more special characters or reserved words.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8c617b57-7237-4481-84b5-aba1308a1944', 'CWE-170', 'Improper Null Termination', 'The product does not terminate or incorrectly terminates a string or array with a null character or equivalent terminator.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2a73df97-09dc-4496-a58a-4c09f6416814', 'CWE-172', 'Encoding Error', 'The product does not properly encode or decode the data, resulting in unexpected values.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f3e71635-dc59-4a1b-bb24-02a10cdc9ffa', 'CWE-173', 'Improper Handling of Alternate Encoding', 'The product does not properly handle when an input uses an alternate encoding that is valid for the control sphere to which the input is being sent.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('944135db-e30e-46ad-bf13-806200940145', 'CWE-174', 'Double Decoding of the Same Data', 'The product decodes the same input twice, which can limit the effectiveness of any protection mechanism that occurs in between the decoding operations.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a9a18154-2a73-4ccb-b26b-42f3c981cee9', 'CWE-175', 'Improper Handling of Mixed Encoding', 'The product does not properly handle when the same input uses several different (mixed) encodings.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bffbf333-fad5-4c5e-b46a-bd9f2aefa320', 'CWE-176', 'Improper Handling of Unicode Encoding', 'The product does not properly handle when an input contains Unicode encoding.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3447c5f8-4068-4c8c-bebd-6cd3692903d4', 'CWE-177', 'Improper Handling of URL Encoding (Hex Encoding)', 'The product does not properly handle when all or part of an input has been URL encoded.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ac75bcff-3123-41a1-a39c-fd367b73dc0f', 'CWE-178', 'Improper Handling of Case Sensitivity', 'The product does not properly account for differences in case sensitivity when accessing or determining the properties of a resource, leading to inconsistent results.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('faa2ae1e-d801-438d-9551-7956ddaceb92', 'CWE-179', 'Incorrect Behavior Order: Early Validation', 'The product validates input before applying protection mechanisms that modify the input, which could allow an attacker to bypass the validation via dangerous inputs that only arise after the modification.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bc2d9579-e5c6-4ed3-be03-2a29ffbfb1a9', 'CWE-180', 'Incorrect Behavior Order: Validate Before Canonicalize', 'The product validates input before it is canonicalized, which prevents the product from detecting data that becomes invalid after the canonicalization step.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('53922c53-fb48-45e5-9639-1012cb6506c0', 'CWE-181', 'Incorrect Behavior Order: Validate Before Filter', 'The product validates data before it has been filtered, which prevents the product from detecting data that becomes invalid after the filtering step.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9ce81cef-a21d-420d-b1c6-588efee6d41d', 'CWE-182', 'Collapse of Data into Unsafe Value', 'The product filters data in a way that causes it to be reduced or collapsed into an unsafe value that violates an expected security property.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d81d823c-4b7e-4108-ac1e-baab238e0b6e', 'CWE-183', 'Permissive List of Allowed Inputs', 'The product implements a protection mechanism that relies on a list of inputs (or properties of inputs) that are explicitly allowed by policy because the inputs are assumed to be safe, but the list is too permissive - that is, it allows an input that is unsafe, leading to resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('01d4eb9b-9f4a-4328-8726-8e1df331bf16', 'CWE-184', 'Incomplete List of Disallowed Inputs', 'The product implements a protection mechanism that relies on a list of inputs (or properties of inputs) that are not allowed by policy or otherwise require other action to neutralize before additional processing takes place, but the list is incomplete.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('70969c7c-8009-415b-a196-cb21d9972a0e', 'CWE-185', 'Incorrect Regular Expression', 'The product specifies a regular expression in a way that causes data to be improperly matched or compared.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7b37d199-4484-4422-ac64-33512fec882a', 'CWE-186', 'Overly Restrictive Regular Expression', 'A regular expression is overly restrictive, which prevents dangerous values from being detected.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ed1cee0a-5f2e-4738-81f6-573d66338633', 'CWE-187', 'Partial String Comparison', 'The product performs a comparison that only examines a portion of a factor before determining whether there is a match, such as a substring, leading to resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c3d7e67f-a922-4f0f-8d7a-34e876cb22cd', 'CWE-188', 'Reliance on Data/Memory Layout', 'The product makes invalid assumptions about how protocol data or memory is organized at a lower level, resulting in unintended program behavior.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('eb1b93d8-a902-481c-9036-2db5dc1f0525', 'CWE-190', 'Integer Overflow or Wraparound', 'The product performs a calculation that can produce an integer overflow or wraparound when the logic assumes that the resulting value will always be larger than the original value. This occurs when an integer value is incremented to a value that is too large to store in the associated representation. When this occurs, the value may become a very small or negative number.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c1992dcb-cc97-476e-95b1-4139b10beae3', 'CWE-191', 'Integer Underflow (Wrap or Wraparound)', 'The product subtracts one value from another, such that the result is less than the minimum allowable integer value, which produces a value that is not equal to the correct result.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4fbf68a4-703b-4763-89e6-abea77fa5d44', 'CWE-192', 'Integer Coercion Error', 'Integer coercion refers to a set of flaws pertaining to the type casting, extension, or truncation of primitive data types.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('763a59e5-cc7c-4c1e-95f5-cd1591f211d7', 'CWE-193', 'Off-by-one Error', 'A product calculates or uses an incorrect maximum or minimum value that is 1 more, or 1 less, than the correct value.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1602ff0d-4ddc-4166-a600-7e1c289d558a', 'CWE-194', 'Unexpected Sign Extension', 'The product performs an operation on a number that causes it to be sign extended when it is transformed into a larger data type. When the original number is negative, this can produce unexpected values that lead to resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ab979e4b-7559-40d0-9cf9-5bf353b0f10c', 'CWE-195', 'Signed to Unsigned Conversion Error', 'The product uses a signed primitive and performs a cast to an unsigned primitive, which can produce an unexpected value if the value of the signed primitive can not be represented using an unsigned primitive.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fe33ce61-f72d-4020-95b8-bf5f09220b18', 'CWE-196', 'Unsigned to Signed Conversion Error', 'The product uses an unsigned primitive and performs a cast to a signed primitive, which can produce an unexpected value if the value of the unsigned primitive can not be represented using a signed primitive.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bc73a385-dec0-4c01-ab93-0e2925e1fef0', 'CWE-197', 'Numeric Truncation Error', 'Truncation errors occur when a primitive is cast to a primitive of a smaller size and data is lost in the conversion.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('49ebab9d-c67f-4032-8cf0-c38cd96c3f79', 'CWE-198', 'Use of Incorrect Byte Ordering', 'The product receives input from an upstream component, but it does not account for byte ordering (e.g. big-endian and little-endian) when processing the input, causing an incorrect number or value to be used.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('50851509-138c-4a9b-a05f-ff2a4ec6542c', 'CWE-200', 'Exposure of Sensitive Information to an Unauthorized Actor', 'The product exposes sensitive information to an actor that is not explicitly authorized to have access to that information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d29c1751-8f9a-45aa-b1a5-4cd0a5c6dfd0', 'CWE-201', 'Insertion of Sensitive Information Into Sent Data', 'The code transmits data to another actor, but a portion of the data includes sensitive information that should not be accessible to that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('15c73d99-c6f9-4b09-9eeb-feed3aa8ffc3', 'CWE-202', 'Exposure of Sensitive Information Through Data Queries', 'When trying to keep information confidential, an attacker can often infer some of the information by using statistics.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e38cf74f-c106-4618-b899-8099a8c4cc9a', 'CWE-203', 'Observable Discrepancy', 'The product behaves differently or sends different responses under different circumstances in a way that is observable to an unauthorized actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b3c4c816-77c0-47aa-ba06-787c109978a9', 'CWE-204', 'Observable Response Discrepancy', 'The product provides different responses to incoming requests in a way that reveals internal state information to an unauthorized actor outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f48dba52-1d63-465f-83e4-c55abb00c919', 'CWE-205', 'Observable Behavioral Discrepancy', 'The product''s behaviors indicate important differences that may be observed by unauthorized actors in a way that reveals (1) its internal state or decision process, or (2) differences from other products with equivalent functionality.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('31cec0b5-12a6-4a04-8842-1ba68a933caa', 'CWE-206', 'Observable Internal Behavioral Discrepancy', 'The product performs multiple behaviors that are combined to produce a single result, but the individual behaviors are observable separately in a way that allows attackers to reveal internal state or internal decision points.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0db5cef3-0d3c-4f7b-8faf-bb298da174f6', 'CWE-207', 'Observable Behavioral Discrepancy With Equivalent Products', 'The product operates in an environment in which its existence or specific identity should not be known, but it behaves differently than other products with equivalent functionality, in a way that is observable to an attacker.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ff977a4c-bc3b-48c9-ac28-5e1be4f71b8f', 'CWE-208', 'Observable Timing Discrepancy', 'Two separate operations in a product require different amounts of time to complete, in a way that is observable to an actor and reveals security-relevant information about the state of the product, such as whether a particular operation was successful or not.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('99524b24-a408-4619-8546-3b6f471f1e2c', 'CWE-209', 'Generation of Error Message Containing Sensitive Information', 'The product generates an error message that includes sensitive information about its environment, users, or associated data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('69b3df66-2ee5-45b1-a5e1-4a4519ef55ce', 'CWE-210', 'Self-generated Error Message Containing Sensitive Information', 'The product identifies an error condition and creates its own diagnostic or error messages that contain sensitive information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0c13e296-df2f-4cb8-888a-3e23b28c6c32', 'CWE-211', 'Externally-Generated Error Message Containing Sensitive Information', 'The product performs an operation that triggers an external diagnostic or error message that is not directly generated or controlled by the product, such as an error generated by the programming language interpreter that a software application uses. The error can contain sensitive system information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f28c16e4-a0bf-4de6-9c8d-118878b93eb6', 'CWE-212', 'Improper Removal of Sensitive Information Before Storage or Transfer', 'The product stores, transfers, or shares a resource that contains sensitive information, but it does not properly remove that information before the product makes the resource available to unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d0f124b6-1c6b-4022-bc02-05c165fe6380', 'CWE-213', 'Exposure of Sensitive Information Due to Incompatible Policies', 'The product''s intended functionality exposes information to certain actors in accordance with the developer''s security policy, but this information is regarded as sensitive according to the intended security policies of other stakeholders such as the product''s administrator, users, or others whose information is being processed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('06d336e4-4b4a-473c-902d-edff085a5671', 'CWE-214', 'Invocation of Process Using Visible Sensitive Information', 'A process is invoked with sensitive command-line arguments, environment variables, or other elements that can be seen by other processes on the operating system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('07f2bc27-9e10-4230-b89d-993975abb5e9', 'CWE-215', 'Insertion of Sensitive Information Into Debugging Code', 'The product inserts sensitive information into debugging code, which could expose this information if the debugging code is not disabled in production.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('42eef5c3-06f0-42c4-a6a6-a804264f7d06', 'CWE-219', 'Storage of File with Sensitive Data Under Web Root', 'The product stores sensitive data under the web document root with insufficient access control, which might make it accessible to untrusted parties.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fd6f30cc-d990-40b9-bc50-d8af41e8c19e', 'CWE-220', 'Storage of File With Sensitive Data Under FTP Root', 'The product stores sensitive data under the FTP server root with insufficient access control, which might make it accessible to untrusted parties.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f7ef66db-b21c-4e0f-b3f1-fca159ba8470', 'CWE-221', 'Information Loss or Omission', 'The product does not record, or improperly records, security-relevant information that leads to an incorrect decision or hampers later analysis.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3f4a886c-321c-4606-b6f3-492c07578365', 'CWE-222', 'Truncation of Security-relevant Information', 'The product truncates the display, recording, or processing of security-relevant information in a way that can obscure the source or nature of an attack.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d53b808e-f3d6-4985-b4b7-25f2a394f8ee', 'CWE-223', 'Omission of Security-relevant Information', 'The product does not record or display information that would be important for identifying the source or nature of an attack, or determining if an action is safe.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ad48355b-090a-4d77-be69-fdf45d4d31dd', 'CWE-224', 'Obscured Security-relevant Information by Alternate Name', 'The product records security-relevant information according to an alternate name of the affected entity, instead of the canonical name.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('24599722-978c-4bf9-9a33-eeb1a6304974', 'CWE-226', 'Sensitive Information in Resource Not Removed Before Reuse', 'The product releases a resource such as memory or a file so that it can be made available for reuse, but it does not clear or zeroize the information contained in the resource before the product performs a critical state transition or makes the resource available for reuse by other entities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('452754f7-2e0d-44f9-86ba-8060fe52bc5e', 'CWE-228', 'Improper Handling of Syntactically Invalid Structure', 'The product does not handle or incorrectly handles input that is not syntactically well-formed with respect to the associated specification.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3a664a90-a45d-411b-8540-eed31d9ed732', 'CWE-229', 'Improper Handling of Values', 'The product does not properly handle when the expected number of values for parameters, fields, or arguments is not provided in input, or if those values are undefined.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('76d82fe7-4f21-4a8b-bf0c-06164d4504e5', 'CWE-230', 'Improper Handling of Missing Values', 'The product does not handle or incorrectly handles when a parameter, field, or argument name is specified, but the associated value is missing, i.e. it is empty, blank, or null.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d50bb485-1723-4576-8670-fd72f6602802', 'CWE-231', 'Improper Handling of Extra Values', 'The product does not handle or incorrectly handles when more values are provided than expected.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('de9658f8-3331-4c65-abf0-90c853a4e0fd', 'CWE-232', 'Improper Handling of Undefined Values', 'The product does not handle or incorrectly handles when a value is not defined or supported for the associated parameter, field, or argument name.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a41ddb2b-0ff1-4330-b9aa-9d81dfcce8c9', 'CWE-233', 'Improper Handling of Parameters', 'The product does not properly handle when the expected number of parameters, fields, or arguments is not provided in input, or if those parameters are undefined.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('81e40f5a-c96f-44fd-bc7a-358230fbb4a9', 'CWE-234', 'Failure to Handle Missing Parameter', 'If too few arguments are sent to a function, the function will still pop the expected number of arguments from the stack. Potentially, a variable number of arguments could be exhausted in a function as well.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d8e495dd-9560-4607-a334-d5eef9809c67', 'CWE-235', 'Improper Handling of Extra Parameters', 'The product does not handle or incorrectly handles when the number of parameters, fields, or arguments with the same name exceeds the expected amount.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1934f2ae-e554-4c86-9277-5e15360bd948', 'CWE-236', 'Improper Handling of Undefined Parameters', 'The product does not handle or incorrectly handles when a particular parameter, field, or argument name is not defined or supported by the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('259ee427-50c4-4e14-98b2-73714d8da30c', 'CWE-237', 'Improper Handling of Structural Elements', 'The product does not handle or incorrectly handles inputs that are related to complex structures.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5480372c-45eb-4819-a2c9-dcb010e95061', 'CWE-238', 'Improper Handling of Incomplete Structural Elements', 'The product does not handle or incorrectly handles when a particular structural element is not completely specified.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bdb45481-97a5-42ea-b8c9-6a4f3a67fcb6', 'CWE-239', 'Failure to Handle Incomplete Element', 'The product does not properly handle when a particular element is not completely specified.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('601ca33e-0dcb-45d6-b97f-04200f9ddd51', 'CWE-240', 'Improper Handling of Inconsistent Structural Elements', 'The product does not handle or incorrectly handles when two or more structural elements should be consistent, but are not.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('302bf37a-2649-46ff-a7b3-e90b20ab76fe', 'CWE-241', 'Improper Handling of Unexpected Data Type', 'The product does not handle or incorrectly handles when a particular element is not the expected type, e.g. it expects a digit (0-9) but is provided with a letter (A-Z).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fafd5b10-0285-4133-9319-14b3c699858c', 'CWE-242', 'Use of Inherently Dangerous Function', 'The product calls a function that can never be guaranteed to work safely.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3b95cc26-a3a2-4ba6-8233-ca72de05eaf1', 'CWE-243', 'Creation of chroot Jail Without Changing Working Directory', 'The product uses the chroot() system call to create a jail, but does not change the working directory afterward. This does not prevent access to files outside of the jail.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6e60dd0b-1e96-4074-bf51-e8c0b5edfac5', 'CWE-244', 'Improper Clearing of Heap Memory Before Release (''Heap Inspection'')', 'Using realloc() to resize buffers that store sensitive information can leave the sensitive information exposed to attack, because it is not removed from memory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aa6bf9c1-68a7-4f7f-b4a7-054d0a885b32', 'CWE-245', 'J2EE Bad Practices: Direct Management of Connections', 'The J2EE application directly manages connections, instead of using the container''s connection management facilities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('32b4aa78-aeb5-4bdf-af95-b71770a66b66', 'CWE-246', 'J2EE Bad Practices: Direct Use of Sockets', 'The J2EE application directly uses sockets instead of using framework method calls.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d9ebf949-562b-4442-8557-90dca290ce9b', 'CWE-248', 'Uncaught Exception', 'An exception is thrown from a function, but it is not caught.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('588da7e3-99ed-4a68-be5a-2f73c19188e9', 'CWE-250', 'Execution with Unnecessary Privileges', 'The product performs an operation at a privilege level that is higher than the minimum level required, which creates new weaknesses or amplifies the consequences of other weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ec54e322-a31f-4256-b866-2b2857630300', 'CWE-252', 'Unchecked Return Value', 'The product does not check the return value from a method or function, which can prevent it from detecting unexpected states and conditions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('49160e5d-6e8f-4c68-b997-b16af575e54e', 'CWE-253', 'Incorrect Check of Function Return Value', 'The product incorrectly checks a return value from a function, which prevents it from detecting errors or exceptional conditions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4aa68df3-6d2c-437f-97b0-11aab962a257', 'CWE-256', 'Plaintext Storage of a Password', 'The product stores a password in plaintext within resources such as memory or files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('917df729-b87e-484d-afd9-f2593d34fc9c', 'CWE-257', 'Storing Passwords in a Recoverable Format', 'The storage of passwords in a recoverable format makes them subject to password reuse attacks by malicious users. In fact, it should be noted that recoverable encrypted passwords provide no significant benefit over plaintext passwords since they are subject not only to reuse by malicious attackers but also by malicious insiders. If a system administrator can recover a password directly, or use a brute force search on the available information, the administrator can use the password on other accounts.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b8047653-2ed8-4f73-9750-65f1d93c19a9', 'CWE-258', 'Empty Password in Configuration File', 'Using an empty string as a password is insecure.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cf690c7d-a40b-457d-be12-6bbf952faeac', 'CWE-259', 'Use of Hard-coded Password', 'The product contains a hard-coded password, which it uses for its own inbound authentication or for outbound communication to external components.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ef2746cd-308a-4115-bf8c-74b6e95c2fe2', 'CWE-260', 'Password in Configuration File', 'The product stores a password in a configuration file that might be accessible to actors who do not know the password.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a513b9ad-bfbc-4c79-82e5-64b2ecb89d8a', 'CWE-261', 'Weak Encoding for Password', 'Obscuring a password with a trivial encoding does not protect the password.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('30c96c68-a41c-4d06-b41e-8b679d4fe3cb', 'CWE-262', 'Not Using Password Aging', 'The product does not have a mechanism in place for managing password aging.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('69200cc8-89ee-4f1c-9130-b75fee21ce41', 'CWE-263', 'Password Aging with Long Expiration', 'The product supports password aging, but the expiration period is too long.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6e3b0025-836a-4dc5-b6f3-00d632a9e8f2', 'CWE-266', 'Incorrect Privilege Assignment', 'A product incorrectly assigns a privilege to a particular actor, creating an unintended sphere of control for that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f30c774a-363c-49ae-b97d-c899dda15458', 'CWE-267', 'Privilege Defined With Unsafe Actions', 'A particular privilege, role, capability, or right can be used to perform unsafe actions that were not intended, even when it is assigned to the correct entity.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('41a8674c-0f69-4b18-974e-24a3fbc82122', 'CWE-268', 'Privilege Chaining', 'Two distinct privileges, roles, capabilities, or rights can be combined in a way that allows an entity to perform unsafe actions that would not be allowed without that combination.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('42a17519-b4f8-480c-ad22-f125f7e5a2b2', 'CWE-269', 'Improper Privilege Management', 'The product does not properly assign, modify, track, or check privileges for an actor, creating an unintended sphere of control for that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('616dcd30-f2a9-49df-a838-f6069f861143', 'CWE-270', 'Privilege Context Switching Error', 'The product does not properly manage privileges while it is switching between different contexts that have different privileges or spheres of control.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8dee68b3-4930-4f1a-b277-f3d9de55eb7f', 'CWE-271', 'Privilege Dropping / Lowering Errors', 'The product does not drop privileges before passing control of a resource to an actor that does not have those privileges.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e05a8ddf-bf29-4665-8669-5d479224af18', 'CWE-272', 'Least Privilege Violation', 'The elevated privilege level required to perform operations such as chroot() should be dropped immediately after the operation is performed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b8dbce7c-0446-4646-903c-7448669ce2c1', 'CWE-273', 'Improper Check for Dropped Privileges', 'The product attempts to drop privileges but does not check or incorrectly checks to see if the drop succeeded.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('791ec393-d761-4310-af44-4c96b0e98784', 'CWE-274', 'Improper Handling of Insufficient Privileges', 'The product does not handle or incorrectly handles when it has insufficient privileges to perform an operation, leading to resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7052adf5-3e85-4572-9342-44161b24df4c', 'CWE-276', 'Incorrect Default Permissions', 'During installation, installed file permissions are set to allow anyone to modify those files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c2f9ddc5-5518-4c6f-9b4e-884d7a46db25', 'CWE-277', 'Insecure Inherited Permissions', 'A product defines a set of insecure permissions that are inherited by objects that are created by the program.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('65281052-2200-4f54-90b1-cf79e072a39d', 'CWE-278', 'Insecure Preserved Inherited Permissions', 'A product inherits a set of insecure permissions for an object, e.g. when copying from an archive file, without user awareness or involvement.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c2b94e19-e9cc-4bca-b5eb-45841d12bb03', 'CWE-279', 'Incorrect Execution-Assigned Permissions', 'While it is executing, the product sets the permissions of an object in a way that violates the intended permissions that have been specified by the user.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('05f30ee1-b312-4e7f-b389-3b6169bdd9f5', 'CWE-280', 'Improper Handling of Insufficient Permissions or Privileges', 'The product does not handle or incorrectly handles when it has insufficient privileges to access resources or functionality as specified by their permissions. This may cause it to follow unexpected code paths that may leave the product in an invalid state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4fc025a9-47b3-4811-ad08-dc13c8af0f10', 'CWE-281', 'Improper Preservation of Permissions', 'The product does not preserve permissions or incorrectly preserves permissions when copying, restoring, or sharing objects, which can cause them to have less restrictive permissions than intended.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b862d4ab-cb9f-4838-b74e-1c7129de4ce8', 'CWE-282', 'Improper Ownership Management', 'The product assigns the wrong ownership, or does not properly verify the ownership, of an object or resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('912c9533-a0ee-44dc-9904-66c17be3c57b', 'CWE-283', 'Unverified Ownership', 'The product does not properly verify that a critical resource is owned by the proper entity.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c559dbc8-08de-4e66-bf72-8e5248e8c292', 'CWE-284', 'Improper Access Control', 'The product does not restrict or incorrectly restricts access to a resource from an unauthorized actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a35dad0e-d879-4e8a-b0ed-fde2aa0dc8db', 'CWE-285', 'Improper Authorization', 'The product does not perform or incorrectly performs an authorization check when an actor attempts to access a resource or perform an action.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a110c9cf-8382-401c-9cbd-7c3277a24138', 'CWE-286', 'Incorrect User Management', 'The product does not properly manage a user within its environment.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e23319a6-8fec-42d7-bb65-28bb4dd4b456', 'CWE-287', 'Improper Authentication', 'When an actor claims to have a given identity, the product does not prove or insufficiently proves that the claim is correct.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('27b724f5-dadb-4feb-98c4-de5e0e53db77', 'CWE-288', 'Authentication Bypass Using an Alternate Path or Channel', 'The product requires authentication, but the product has an alternate path or channel that does not require authentication.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('739b8710-d139-4af1-81bd-2a78c361a2e2', 'CWE-289', 'Authentication Bypass by Alternate Name', 'The product performs authentication based on the name of a resource being accessed, or the name of the actor performing the access, but it does not properly check all possible names for that resource or actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c8a734df-4084-4446-8799-18809d9a5d83', 'CWE-290', 'Authentication Bypass by Spoofing', 'This attack-focused weakness is caused by incorrectly implemented authentication schemes that are subject to spoofing attacks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0fe62b86-c35c-480d-a552-441682b80a24', 'CWE-291', 'Reliance on IP Address for Authentication', 'The product uses an IP address for authentication.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3b05ead5-0a50-46b5-b356-53b40887dfb6', 'CWE-293', 'Using Referer Field for Authentication', 'The referer field in HTTP requests can be easily modified and, as such, is not a valid means of message integrity checking.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7397967d-db6d-47fc-b93f-74dd7a2866b7', 'CWE-294', 'Authentication Bypass by Capture-replay', 'A capture-replay flaw exists when the design of the product makes it possible for a malicious user to sniff network traffic and bypass authentication by replaying it to the server in question to the same effect as the original message (or with minor changes).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9d765db8-a86a-40c4-a5f2-a742e242f6a0', 'CWE-295', 'Improper Certificate Validation', 'The product does not validate, or incorrectly validates, a certificate.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4f86441f-ba39-4715-85ab-ac828d5719ee', 'CWE-296', 'Improper Following of a Certificate''s Chain of Trust', 'The product does not follow, or incorrectly follows, the chain of trust for a certificate back to a trusted root certificate.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b50d78d7-ad62-4287-946f-43e0f8074fdc', 'CWE-297', 'Improper Validation of Certificate with Host Mismatch', 'The product communicates with a host that provides a certificate, but the product does not properly ensure that the certificate is actually associated with that host.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('107805b7-a3aa-492f-bcd2-46ee76968651', 'CWE-298', 'Improper Validation of Certificate Expiration', 'A certificate expiration is not validated or is incorrectly validated.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e0a19391-eaa6-4637-8e94-e5657a8a6776', 'CWE-299', 'Improper Check for Certificate Revocation', 'The product does not check or incorrectly checks the revocation status of a certificate, which may cause it to use a certificate that has been compromised.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a449b662-7c3a-428f-879c-08ebb7d33351', 'CWE-300', 'Channel Accessible by Non-Endpoint', 'The product does not adequately verify the identity of actors at both ends of a communication channel, or does not adequately ensure the integrity of the channel, in a way that allows the channel to be accessed or influenced by an actor that is not an endpoint.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('66818cbd-1e72-4904-84db-e7f546098171', 'CWE-301', 'Reflection Attack in an Authentication Protocol', 'Simple authentication protocols are subject to reflection attacks if a malicious user can use the target machine to impersonate a trusted user.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('abd29c35-2a04-4c71-928b-cc02d2532eab', 'CWE-302', 'Authentication Bypass by Assumed-Immutable Data', 'The authentication scheme or implementation uses key data elements that are assumed to be immutable, but can be controlled or modified by the attacker.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('262e1c93-56ac-479e-9159-de0acef7f3fb', 'CWE-303', 'Incorrect Implementation of Authentication Algorithm', 'The requirements for the product dictate the use of an established authentication algorithm, but the implementation of the algorithm is incorrect.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a5001629-4543-43bb-8ae1-296a2cd8210b', 'CWE-304', 'Missing Critical Step in Authentication', 'The product implements an authentication technique, but it skips a step that weakens the technique.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('59f7d6cb-7c47-4bb8-b817-cf791506952d', 'CWE-305', 'Authentication Bypass by Primary Weakness', 'The authentication algorithm is sound, but the implemented mechanism can be bypassed as the result of a separate weakness that is primary to the authentication error.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('589bc027-1467-4676-a60e-cf9229a5380c', 'CWE-306', 'Missing Authentication for Critical Function', 'The product does not perform any authentication for functionality that requires a provable user identity or consumes a significant amount of resources.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5e1b2ef9-8cea-4f52-950f-8c3c554d7bfc', 'CWE-307', 'Improper Restriction of Excessive Authentication Attempts', 'The product does not implement sufficient measures to prevent multiple failed authentication attempts within a short time frame.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4d0fb167-cb0f-4435-8279-3b8ec0e6c4ea', 'CWE-308', 'Use of Single-factor Authentication', 'The product uses an authentication algorithm that uses a single factor (e.g., a password) in a security context that should require more than one factor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b8220a9e-6413-4662-8f1f-416864b807e9', 'CWE-309', 'Use of Password System for Primary Authentication', 'The use of password systems as the primary means of authentication may be subject to several flaws or shortcomings, each reducing the effectiveness of the mechanism.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3326044d-1a86-47a5-90e2-775830a033b7', 'CWE-311', 'Missing Encryption of Sensitive Data', 'The product does not encrypt sensitive or critical information before storage or transmission.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b63299da-c53a-43b1-a545-85287f937b5c', 'CWE-312', 'Cleartext Storage of Sensitive Information', 'The product stores sensitive information in cleartext within a resource that might be accessible to another control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('47584967-4fbf-477d-bc1d-a126c3f06d56', 'CWE-313', 'Cleartext Storage in a File or on Disk', 'The product stores sensitive information in cleartext in a file, or on disk.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aa3aba1b-077d-4823-abfc-0e18b368df65', 'CWE-314', 'Cleartext Storage in the Registry', 'The product stores sensitive information in cleartext in the registry.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b6c6abfd-3f1a-4134-bcb2-ee912a1943dc', 'CWE-315', 'Cleartext Storage of Sensitive Information in a Cookie', 'The product stores sensitive information in cleartext in a cookie.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b0a41721-4767-4fde-9a8e-570899367292', 'CWE-316', 'Cleartext Storage of Sensitive Information in Memory', 'The product stores sensitive information in cleartext in memory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('443a5f18-a662-401f-8814-f4d8b9a11a38', 'CWE-317', 'Cleartext Storage of Sensitive Information in GUI', 'The product stores sensitive information in cleartext within the GUI.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e1052703-3b50-4dd5-a7bd-8911043c6419', 'CWE-318', 'Cleartext Storage of Sensitive Information in Executable', 'The product stores sensitive information in cleartext in an executable.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('01d9340a-1ccd-4961-8ea6-395253b83f83', 'CWE-319', 'Cleartext Transmission of Sensitive Information', 'The product transmits sensitive or security-critical data in cleartext in a communication channel that can be sniffed by unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('89d339d3-379e-4ecf-a861-1356c03e80bf', 'CWE-321', 'Use of Hard-coded Cryptographic Key', 'The product uses a hard-coded, unchangeable cryptographic key.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9d65456a-a7e7-44da-82dd-0e0117074ac2', 'CWE-322', 'Key Exchange without Entity Authentication', 'The product performs a key exchange with an actor without verifying the identity of that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('833600e4-c443-4584-9c60-0d65ccf4af42', 'CWE-323', 'Reusing a Nonce, Key Pair in Encryption', 'Nonces should be used for the present occasion and only once.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9626c4fd-8bad-42fd-b3e2-f37b15472165', 'CWE-324', 'Use of a Key Past its Expiration Date', 'The product uses a cryptographic key or password past its expiration date, which diminishes its safety significantly by increasing the timing window for cracking attacks against that key.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('df1dfbf8-a507-4871-8044-11fae571e2c4', 'CWE-325', 'Missing Cryptographic Step', 'The product does not implement a required step in a cryptographic algorithm, resulting in weaker encryption than advertised by the algorithm.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f1dfbab6-f17e-4c0a-b7d5-473e5c0371ed', 'CWE-326', 'Inadequate Encryption Strength', 'The product stores or transmits sensitive data using an encryption scheme that is theoretically sound, but is not strong enough for the level of protection required.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d7566339-f911-44ef-9dd4-ee6172850161', 'CWE-327', 'Use of a Broken or Risky Cryptographic Algorithm', 'The product uses a broken or risky cryptographic algorithm or protocol.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('50c52dc0-6e34-4d49-bf66-9a97034c3100', 'CWE-328', 'Use of Weak Hash', 'The product uses an algorithm that produces a digest (output value) that does not meet security expectations for a hash function that allows an adversary to reasonably determine the original input (preimage attack), find another input that can produce the same hash (2nd preimage attack), or find multiple inputs that evaluate to the same hash (birthday attack).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('85d136ec-cf6a-4ffd-a34b-7a3a5989f9cb', 'CWE-329', 'Generation of Predictable IV with CBC Mode', 'The product generates and uses a predictable initialization Vector (IV) with Cipher Block Chaining (CBC) Mode, which causes algorithms to be susceptible to dictionary attacks when they are encrypted under the same key.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('33f52272-726d-4c4e-aa20-0ea6885ab271', 'CWE-330', 'Use of Insufficiently Random Values', 'The product uses insufficiently random numbers or values in a security context that depends on unpredictable numbers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ab822993-080d-40ac-87b1-af4fa69bd303', 'CWE-331', 'Insufficient Entropy', 'The product uses an algorithm or scheme that produces insufficient entropy, leaving patterns or clusters of values that are more likely to occur than others.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f36a917a-5958-46ab-b15d-578c120af5e1', 'CWE-332', 'Insufficient Entropy in PRNG', 'The lack of entropy available for, or used by, a Pseudo-Random Number Generator (PRNG) can be a stability and security threat.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f3d7590f-59a9-4f7f-bb46-3a2a30605054', 'CWE-333', 'Improper Handling of Insufficient Entropy in TRNG', 'True random number generators (TRNG) generally have a limited source of entropy and therefore can fail or block.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a95bfe98-d848-4dfe-885c-e77232c855d5', 'CWE-334', 'Small Space of Random Values', 'The number of possible random values is smaller than needed by the product, making it more susceptible to brute force attacks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('364f3c94-345a-4f69-8240-6aea4077c5f7', 'CWE-335', 'Incorrect Usage of Seeds in Pseudo-Random Number Generator (PRNG)', 'The product uses a Pseudo-Random Number Generator (PRNG) but does not correctly manage seeds.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('522ef922-5562-4d13-b13a-5878171bdca8', 'CWE-336', 'Same Seed in Pseudo-Random Number Generator (PRNG)', 'A Pseudo-Random Number Generator (PRNG) uses the same seed each time the product is initialized.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c2348b34-ab73-4490-a939-323497747c1f', 'CWE-337', 'Predictable Seed in Pseudo-Random Number Generator (PRNG)', 'A Pseudo-Random Number Generator (PRNG) is initialized from a predictable seed, such as the process ID or system time.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('84fb473b-4ad5-4fa4-a1af-b448ff7a851b', 'CWE-338', 'Use of Cryptographically Weak Pseudo-Random Number Generator (PRNG)', 'The product uses a Pseudo-Random Number Generator (PRNG) in a security context, but the PRNG''s algorithm is not cryptographically strong.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('78184ebf-ce2b-4e84-920b-35897f2ab62f', 'CWE-339', 'Small Seed Space in PRNG', 'A Pseudo-Random Number Generator (PRNG) uses a relatively small seed space, which makes it more susceptible to brute force attacks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('df0b3573-1e44-41a6-ad4e-64a32f004764', 'CWE-340', 'Generation of Predictable Numbers or Identifiers', 'The product uses a scheme that generates numbers or identifiers that are more predictable than required.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fb32a180-0c19-4f01-92a7-831dacf07e97', 'CWE-341', 'Predictable from Observable State', 'A number or object is predictable based on observations that the attacker can make about the state of the system or network, such as time, process ID, etc.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0210131a-4cc8-4d1e-8fe9-120193b33709', 'CWE-342', 'Predictable Exact Value from Previous Values', 'An exact value or random number can be precisely predicted by observing previous values.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('05e801fc-a1f2-49e8-844a-d77da63f43f1', 'CWE-343', 'Predictable Value Range from Previous Values', 'The product''s random number generator produces a series of values which, when observed, can be used to infer a relatively small range of possibilities for the next value that could be generated.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9281194b-1810-40e4-a2f2-2fbb3e84e5ff', 'CWE-344', 'Use of Invariant Value in Dynamically Changing Context', 'The product uses a constant value, name, or reference, but this value can (or should) vary across different environments.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('01419b58-0c40-4add-9d37-f66659403a0f', 'CWE-345', 'Insufficient Verification of Data Authenticity', 'The product does not sufficiently verify the origin or authenticity of data, in a way that causes it to accept invalid data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2a05db6f-a430-498b-b06b-162c4b35c7c9', 'CWE-346', 'Origin Validation Error', 'The product does not properly verify that the source of data or communication is valid.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9dcc1aa1-5727-4245-859f-89ac0323417e', 'CWE-347', 'Improper Verification of Cryptographic Signature', 'The product does not verify, or incorrectly verifies, the cryptographic signature for data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1af53c14-672d-4232-823b-bcb000b66393', 'CWE-348', 'Use of Less Trusted Source', 'The product has two different sources of the same data or information, but it uses the source that has less support for verification, is less trusted, or is less resistant to attack.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('45c98a88-ac2c-4649-8597-e912eea96cce', 'CWE-349', 'Acceptance of Extraneous Untrusted Data With Trusted Data', 'The product, when processing trusted data, accepts any untrusted data that is also included with the trusted data, treating the untrusted data as if it were trusted.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('18010633-a647-4eed-b8dc-d3f20381da0d', 'CWE-350', 'Reliance on Reverse DNS Resolution for a Security-Critical Action', 'The product performs reverse DNS resolution on an IP address to obtain the hostname and make a security decision, but it does not properly ensure that the IP address is truly associated with the hostname.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0e7a78f2-d26b-4844-a2ed-e381a9f7ff90', 'CWE-351', 'Insufficient Type Distinction', 'The product does not properly distinguish between different types of elements in a way that leads to insecure behavior.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fdddaa4b-3b5d-45f2-8bec-6bd0607bc1d7', 'CWE-352', 'Cross-Site Request Forgery (CSRF)', 'The web application does not, or cannot, sufficiently verify whether a request was intentionally provided by the user who sent the request, which could have originated from an unauthorized actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3016ff9f-597f-4e0e-8727-c95dd75e5126', 'CWE-353', 'Missing Support for Integrity Check', 'The product uses a transmission protocol that does not include a mechanism for verifying the integrity of the data during transmission, such as a checksum.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9b03e130-ca2f-4c4b-bb6c-b7b98f873811', 'CWE-354', 'Improper Validation of Integrity Check Value', 'The product does not validate or incorrectly validates the integrity check values or checksums of a message. This may prevent it from detecting if the data has been modified or corrupted in transmission.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('db912bfc-c432-4469-a447-3ad01de4ff15', 'CWE-356', 'Product UI does not Warn User of Unsafe Actions', 'The product''s user interface does not warn the user before undertaking an unsafe action on behalf of that user. This makes it easier for attackers to trick users into inflicting damage to their system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('26eb523c-b369-4b2e-b4e6-271dfb8ee239', 'CWE-357', 'Insufficient UI Warning of Dangerous Operations', 'The user interface provides a warning to a user regarding dangerous or sensitive operations, but the warning is not noticeable enough to warrant attention.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dd541184-f13a-421f-b11e-7ee4546af3ad', 'CWE-358', 'Improperly Implemented Security Check for Standard', 'The product does not implement or incorrectly implements one or more security-relevant checks as specified by the design of a standardized algorithm, protocol, or technique.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('720d1742-a749-48e4-8dac-ab22cfec3489', 'CWE-359', 'Exposure of Private Personal Information to an Unauthorized Actor', 'The product does not properly prevent a person''s private, personal information from being accessed by actors who either (1) are not explicitly authorized to access the information or (2) do not have the implicit consent of the person about whom the information is collected.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('46636b40-36fc-4bc4-a05d-730b1f2686fc', 'CWE-360', 'Trust of System Event Data', 'Security based on event locations are insecure and can be spoofed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5485b55b-6aa8-48c7-a10e-1c36bd902b71', 'CWE-362', 'Concurrent Execution using Shared Resource with Improper Synchronization (''Race Condition'')', 'The product contains a concurrent code sequence that requires temporary, exclusive access to a shared resource, but a timing window exists in which the shared resource can be modified by another code sequence operating concurrently.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b53c3773-4471-41e1-a668-b28fc243f75a', 'CWE-363', 'Race Condition Enabling Link Following', 'The product checks the status of a file or directory before accessing it, which produces a race condition in which the file can be replaced with a link before the access is performed, causing the product to access the wrong file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('58d26e33-ca66-4f7b-bbdc-15933e30213c', 'CWE-364', 'Signal Handler Race Condition', 'The product uses a signal handler that introduces a race condition.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9980059f-e7c2-4cfb-af62-555ebf921eb6', 'CWE-366', 'Race Condition within a Thread', 'If two threads of execution use a resource simultaneously, there exists the possibility that resources may be used while invalid, in turn making the state of execution undefined.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('16eaf082-2a35-49aa-8fe4-473b965a7bdd', 'CWE-367', 'Time-of-check Time-of-use (TOCTOU) Race Condition', 'The product checks the state of a resource before using that resource, but the resource''s state can change between the check and the use in a way that invalidates the results of the check.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ef1922f2-5557-470d-80d6-6290389173a2', 'CWE-368', 'Context Switching Race Condition', 'A product performs a series of non-atomic actions to switch between contexts that cross privilege or other security boundaries, but a race condition allows an attacker to modify or misrepresent the product''s behavior during the switch.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a6c542c7-a1ba-4c83-aa0f-ecf9de0b0060', 'CWE-369', 'Divide By Zero', 'The product divides a value by zero.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cf7a0879-4348-4ece-9acf-94c5a3bb58a5', 'CWE-370', 'Missing Check for Certificate Revocation after Initial Check', 'The product does not check the revocation status of a certificate after its initial revocation check, which can cause the product to perform privileged actions even after the certificate is revoked at a later time.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('72fce755-ccd6-4f5f-aced-2dfe31d2499d', 'CWE-372', 'Incomplete Internal State Distinction', 'The product does not properly determine which state it is in, causing it to assume it is in state X when in fact it is in state Y, causing it to perform incorrect operations in a security-relevant manner.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4526aad9-090c-45bd-af81-1a0c9eb59e52', 'CWE-374', 'Passing Mutable Objects to an Untrusted Method', 'The product sends non-cloned mutable data as an argument to a method or function.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('77cd5ea4-57eb-4cde-9be2-18f4ef5ffa83', 'CWE-375', 'Returning a Mutable Object to an Untrusted Caller', 'Sending non-cloned mutable data as a return value may result in that data being altered or deleted by the calling function.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7c1a86cb-84c3-4dad-b935-e8d9263615d5', 'CWE-377', 'Insecure Temporary File', 'Creating and using insecure temporary files can leave application and system data vulnerable to attack.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b097c692-e2b0-46cf-930c-4ade5d8bef0b', 'CWE-378', 'Creation of Temporary File With Insecure Permissions', 'Opening temporary files without appropriate measures or controls can leave the file, its contents and any function that it impacts vulnerable to attack.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('09d1b2ad-63c5-4b36-8b4e-a2b3fdbf5f12', 'CWE-379', 'Creation of Temporary File in Directory with Insecure Permissions', 'The product creates a temporary file in a directory whose permissions allow unintended actors to determine the file''s existence or otherwise access that file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('61e0a8c1-7fcb-4139-8e2d-328f4f997ed7', 'CWE-382', 'J2EE Bad Practices: Use of System.exit()', 'A J2EE application uses System.exit(), which also shuts down its container.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('24ba0be4-8e4b-45a8-afcf-559535478dd0', 'CWE-383', 'J2EE Bad Practices: Direct Use of Threads', 'Thread management in a Web application is forbidden in some circumstances and is always highly error prone.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7b83c162-7ceb-4faa-9de7-58482ed70650', 'CWE-384', 'Session Fixation', 'Authenticating a user, or otherwise establishing a new user session, without invalidating any existing session identifier gives an attacker the opportunity to steal authenticated sessions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('785e0568-2e4f-4624-aae9-e87b7a3ff436', 'CWE-385', 'Covert Timing Channel', 'Covert timing channels convey information by modulating some aspect of system behavior over time, so that the program receiving the information can observe system behavior and infer protected information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('eb3e55fb-c717-4732-8039-1c5a94f30d72', 'CWE-386', 'Symbolic Name not Mapping to Correct Object', 'A constant symbolic reference to an object is used, even though the reference can resolve to a different object over time.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('11758760-e999-4f1b-aff5-ecd61e5b3759', 'CWE-390', 'Detection of Error Condition Without Action', 'The product detects a specific error, but takes no actions to handle the error.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bb91c5b2-241a-48da-8fb3-4cfb6c41e819', 'CWE-391', 'Unchecked Error Condition', '[PLANNED FOR DEPRECATION. SEE MAINTENANCE NOTES AND CONSIDER CWE-252, CWE-248, OR CWE-1069.] Ignoring exceptions and other error conditions may allow an attacker to induce unexpected behavior unnoticed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4d54b2b3-a8af-43c9-b0ce-d5305d1fe9c1', 'CWE-392', 'Missing Report of Error Condition', 'The product encounters an error but does not provide a status code or return value to indicate that an error has occurred.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('58882a35-e174-4bd7-bc7a-39b06b4a179c', 'CWE-393', 'Return of Wrong Status Code', 'A function or operation returns an incorrect return value or status code that does not indicate the true result of execution, causing the product to modify its behavior based on the incorrect result.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c141ec4a-24b5-4100-86d7-d7f8aad87f75', 'CWE-394', 'Unexpected Status Code or Return Value', 'The product does not properly check when a function or operation returns a value that is legitimate for the function, but is not expected by the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1550d4a5-d330-4c57-9556-30db59cba091', 'CWE-395', 'Use of NullPointerException Catch to Detect NULL Pointer Dereference', 'Catching NullPointerException should not be used as an alternative to programmatic checks to prevent dereferencing a null pointer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e0560f1a-92b4-48eb-87b2-e0db5f24537a', 'CWE-396', 'Declaration of Catch for Generic Exception', 'Catching overly broad exceptions promotes complex error handling code that is more likely to contain security vulnerabilities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('13a96a52-c301-4531-8f77-3cf5dd5d5225', 'CWE-397', 'Declaration of Throws for Generic Exception', 'The product throws or raises an overly broad exceptions that can hide important details and produce inappropriate responses to certain conditions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bffe8850-d48b-4b36-b7c3-c5f1ea78edef', 'CWE-400', 'Uncontrolled Resource Consumption', 'The product does not properly control the allocation and maintenance of a limited resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f611fa66-e7f3-46ab-9183-a757db74f7af', 'CWE-401', 'Missing Release of Memory after Effective Lifetime', 'The product does not sufficiently track and release allocated memory after it has been used, making the memory unavailable for reallocation and reuse.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bb006171-17d4-4242-b559-2f29759add9e', 'CWE-402', 'Transmission of Private Resources into a New Sphere (''Resource Leak'')', 'The product makes resources available to untrusted parties when those resources are only intended to be accessed by the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6ee48602-36b3-46e1-b744-5cce9a0e079b', 'CWE-403', 'Exposure of File Descriptor to Unintended Control Sphere (''File Descriptor Leak'')', 'A process does not close sensitive file descriptors before invoking a child process, which allows the child to perform unauthorized I/O operations using those descriptors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('30c64408-426f-4624-834f-9ad6373d2891', 'CWE-404', 'Improper Resource Shutdown or Release', 'The product does not release or incorrectly releases a resource before it is made available for re-use.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4ba0b364-dc57-43da-bf56-a016031f0566', 'CWE-405', 'Asymmetric Resource Consumption (Amplification)', 'The product does not properly control situations in which an adversary can cause the product to consume or produce excessive resources without requiring the adversary to invest equivalent work or otherwise prove authorization, i.e., the adversary''s influence is asymmetric.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3117f4c3-5c57-4046-8935-19a8407fa939', 'CWE-406', 'Insufficient Control of Network Message Volume (Network Amplification)', 'The product does not sufficiently monitor or control transmitted network traffic volume, so that an actor can cause the product to transmit more traffic than should be allowed for that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bfed485d-d744-4fb7-8afa-945b439fa102', 'CWE-407', 'Inefficient Algorithmic Complexity', 'An algorithm in a product has an inefficient worst-case computational complexity that may be detrimental to system performance and can be triggered by an attacker, typically using crafted manipulations that ensure that the worst case is being reached.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('181d7546-753a-4cab-b466-85dd2368e9a6', 'CWE-408', 'Incorrect Behavior Order: Early Amplification', 'The product allows an entity to perform a legitimate but expensive operation before authentication or authorization has taken place.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('befd183a-3edb-4307-b021-d9d7f823a4f2', 'CWE-409', 'Improper Handling of Highly Compressed Data (Data Amplification)', 'The product does not handle or incorrectly handles a compressed input with a very high compression ratio that produces a large output.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d7294e70-00a4-44ae-bd72-836d515a8644', 'CWE-410', 'Insufficient Resource Pool', 'The product''s resource pool is not large enough to handle peak demand, which allows an attacker to prevent others from accessing the resource by using a (relatively) large number of requests for resources.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d2989e0c-bc31-4c04-99ef-cd85cbc25305', 'CWE-412', 'Unrestricted Externally Accessible Lock', 'The product properly checks for the existence of a lock, but the lock can be externally controlled or influenced by an actor that is outside of the intended sphere of control.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aaf06ff9-4365-4323-b496-f404927ad1a6', 'CWE-413', 'Improper Resource Locking', 'The product does not lock or does not correctly lock a resource when the product must have exclusive access to the resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5992e354-3d7a-43ca-ac43-e4bd386fe02d', 'CWE-414', 'Missing Lock Check', 'A product does not check to see if a lock is present before performing sensitive operations on a resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('df520308-c440-40cc-b8f9-4cb8ac1f69eb', 'CWE-415', 'Double Free', 'The product calls free() twice on the same memory address.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3d5ef045-c92b-42e6-9146-b6c9a1e77008', 'CWE-416', 'Use After Free', 'The product reuses or references memory after it has been freed. At some point afterward, the memory may be allocated again and saved in another pointer, while the original pointer references a location somewhere within the new allocation. Any operations using the original pointer are no longer valid because the memory belongs to the code that operates on the new pointer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('207e106d-1c7c-437b-9ecc-91d081cb3288', 'CWE-419', 'Unprotected Primary Channel', 'The product uses a primary channel for administration or restricted functionality, but it does not properly protect the channel.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('43c5f357-2f34-480a-82b8-e48592720a59', 'CWE-420', 'Unprotected Alternate Channel', 'The product protects a primary channel, but it does not use the same level of protection for an alternate channel.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0b156057-e96a-444f-9e20-5096c2a4545c', 'CWE-421', 'Race Condition During Access to Alternate Channel', 'The product opens an alternate channel to communicate with an authorized user, but the channel is accessible to other actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('06f9622f-a264-418e-86ee-3122c4c319d2', 'CWE-422', 'Unprotected Windows Messaging Channel (''Shatter'')', 'The product does not properly verify the source of a message in the Windows Messaging System while running at elevated privileges, creating an alternate channel through which an attacker can directly send a message to the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3d7c757b-e067-4eb9-9d1e-fa224b410307', 'CWE-424', 'Improper Protection of Alternate Path', 'The product does not sufficiently protect all possible paths that a user can take to access restricted functionality or resources.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('93b0d63b-82a7-4227-b0c3-9d06299704b4', 'CWE-425', 'Direct Request (''Forced Browsing'')', 'The web application does not adequately enforce appropriate authorization on all restricted URLs, scripts, or files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('71ceb013-2b60-4798-a95a-0a610196cd44', 'CWE-426', 'Untrusted Search Path', 'The product searches for critical resources using an externally-supplied search path that can point to resources that are not under the product''s direct control.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7900defa-1c71-460c-ae96-ca97dd5df072', 'CWE-427', 'Uncontrolled Search Path Element', 'The product uses a fixed or controlled search path to find resources, but one or more locations in that path can be under the control of unintended actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4447e0e4-ee8a-4241-a960-052eedbfaf62', 'CWE-428', 'Unquoted Search Path or Element', 'The product uses a search path that contains an unquoted element, in which the element contains whitespace or other separators. This can cause the product to access resources in a parent path.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('05f64edb-3ac0-40fe-b6f5-52fe328b6204', 'CWE-430', 'Deployment of Wrong Handler', 'The wrong handler is assigned to process an object.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('36a4c940-e0c6-4194-903b-4702d51f23be', 'CWE-431', 'Missing Handler', 'A handler is not available or implemented.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('93bfc132-07ab-47f3-ad0f-280c7c7b5980', 'CWE-432', 'Dangerous Signal Handler not Disabled During Sensitive Operations', 'The product uses a signal handler that shares state with other signal handlers, but it does not properly mask or prevent those signal handlers from being invoked while the original signal handler is still running.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('96f03614-b225-48bb-98d6-089fa1f6d011', 'CWE-433', 'Unparsed Raw Web Content Delivery', 'The product stores raw content or supporting code under the web document root with an extension that is not specifically handled by the server.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3e1a4d5a-514b-40cd-9ec9-411bfa30fe20', 'CWE-434', 'Unrestricted Upload of File with Dangerous Type', 'The product allows the upload or transfer of dangerous file types that are automatically processed within its environment.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ffe39f49-ee5f-4909-8cd3-d98cf27a332e', 'CWE-435', 'Improper Interaction Between Multiple Correctly-Behaving Entities', 'An interaction error occurs when two entities have correct behavior when running independently of each other, but when they are integrated as components in a larger system or process, they introduce incorrect behaviors that may cause resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5fc49754-53c1-4555-a76f-6574fa490590', 'CWE-436', 'Interpretation Conflict', 'Product A handles inputs or steps differently than Product B, which causes A to perform incorrect actions based on its perception of B''s state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c04fb3fd-9bc5-46e9-b5dc-d545837d7ed2', 'CWE-437', 'Incomplete Model of Endpoint Features', 'A product acts as an intermediary or monitor between two or more endpoints, but it does not have a complete model of an endpoint''s features, behaviors, or state, potentially causing the product to perform incorrect actions based on this incomplete model.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('abcdb275-c6d0-4237-b6eb-f533a461e633', 'CWE-439', 'Behavioral Change in New Version or Environment', 'A''s behavior or functionality changes with a new version of A, or a new environment, which is not known (or manageable) by B.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f1f0d5c3-7597-45d5-b062-a636410ce9f1', 'CWE-440', 'Expected Behavior Violation', 'A feature, API, or function does not perform according to its specification.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('83a14e47-683f-43de-a26a-b28bb9a99c83', 'CWE-441', 'Unintended Proxy or Intermediary (''Confused Deputy'')', 'The product receives a request, message, or directive from an upstream component, but the product does not sufficiently preserve the original source of the request before forwarding the request to an external actor that is outside of the product''s control sphere. This causes the product to appear to be the source of the request, leading it to act as a proxy or other intermediary between the upstream component and the external actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('80260a51-7174-4d80-a230-f1a31d4fbe33', 'CWE-444', 'Inconsistent Interpretation of HTTP Requests (''HTTP Request/Response Smuggling'')', 'The product acts as an intermediary HTTP agent (such as a proxy or firewall) in the data flow between two entities such as a client and server, but it does not interpret malformed HTTP requests or responses in ways that are consistent with how the messages will be processed by those entities that are at the ultimate destination.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8488dd7b-a65c-4283-831f-2273a736c24e', 'CWE-446', 'UI Discrepancy for Security Feature', 'The user interface does not correctly enable or configure a security feature, but the interface provides feedback that causes the user to believe that the feature is in a secure state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b56e88b8-08ab-44f7-b877-c4a1846598b1', 'CWE-447', 'Unimplemented or Unsupported Feature in UI', 'A UI function for a security feature appears to be supported and gives feedback to the user that suggests that it is supported, but the underlying functionality is not implemented.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('161fc111-4936-4f70-aa28-b00b7a27184b', 'CWE-448', 'Obsolete Feature in UI', 'A UI function is obsolete and the product does not warn the user.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ec5bccc4-f459-4c37-8d1a-812dc837ffc3', 'CWE-449', 'The UI Performs the Wrong Action', 'The UI performs the wrong action with respect to the user''s request.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d5fbbece-8a7c-46e1-ac9d-4debdea349fa', 'CWE-450', 'Multiple Interpretations of UI Input', 'The UI has multiple interpretations of user input but does not prompt the user when it selects the less secure interpretation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f650cc6d-7ea3-43d1-b87c-e0eeb4f2dca6', 'CWE-451', 'User Interface (UI) Misrepresentation of Critical Information', 'The user interface (UI) does not properly represent critical information to the user, allowing the information - or its source - to be obscured or spoofed. This is often a component in phishing attacks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('79638fd1-cb5d-4280-ab8c-3b3300daca9c', 'CWE-453', 'Insecure Default Variable Initialization', 'The product, by default, initializes an internal variable with an insecure or less secure value than is possible.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('29a87db2-2431-47a5-9b45-3f519de4d9ef', 'CWE-454', 'External Initialization of Trusted Variables or Data Stores', 'The product initializes critical internal variables or data stores using inputs that can be modified by untrusted actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f1c2d782-5891-4955-a108-d18c7aea66ee', 'CWE-455', 'Non-exit on Failed Initialization', 'The product does not exit or otherwise modify its operation when security-relevant errors occur during initialization, such as when a configuration file has a format error or a hardware security module (HSM) cannot be activated, which can cause the product to execute in a less secure fashion than intended by the administrator.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('286359c6-7574-4dd5-9e6e-1e3a884b5060', 'CWE-456', 'Missing Initialization of a Variable', 'The product does not initialize critical variables, which causes the execution environment to use unexpected values.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1ca3d4f3-7b86-49dd-be4c-e8c49fc22d19', 'CWE-457', 'Use of Uninitialized Variable', 'The code uses a variable that has not been initialized, leading to unpredictable or unintended results.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('774b75a9-9125-404d-a009-c7ffd66d354b', 'CWE-459', 'Incomplete Cleanup', 'The product does not properly clean up and remove temporary or supporting resources after they have been used.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('49ff9e81-40fb-4e66-937a-9849918a2a13', 'CWE-460', 'Improper Cleanup on Thrown Exception', 'The product does not clean up its state or incorrectly cleans up its state when an exception is thrown, leading to unexpected state or control flow.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d6370b73-3c75-44ae-9834-1f9aab5a459b', 'CWE-462', 'Duplicate Key in Associative List (Alist)', 'Duplicate keys in associative lists can lead to non-unique keys being mistaken for an error.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e300792f-ddbb-4a78-93c2-aaa8248df219', 'CWE-463', 'Deletion of Data Structure Sentinel', 'The accidental deletion of a data-structure sentinel can cause serious programming logic problems.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('72c2a61c-cb7c-4e08-b14f-d3e1321e6fcb', 'CWE-464', 'Addition of Data Structure Sentinel', 'The accidental addition of a data-structure sentinel can cause serious programming logic problems.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cfd5c12f-f2d7-408f-96a1-88064963efac', 'CWE-466', 'Return of Pointer Value Outside of Expected Range', 'A function can return a pointer to memory that is outside of the buffer that the pointer is expected to reference.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b681bc52-4177-46a1-8cf6-86772f799e62', 'CWE-467', 'Use of sizeof() on a Pointer Type', 'The code calls sizeof() on a pointer type, which can be an incorrect calculation if the programmer intended to determine the size of the data that is being pointed to.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5c3c0832-2696-4bf9-a694-ddb8a0674fef', 'CWE-468', 'Incorrect Pointer Scaling', 'In C and C++, one may often accidentally refer to the wrong memory due to the semantics of when math operations are implicitly scaled.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fc539889-11cd-4cf9-984a-8dae784c3e84', 'CWE-469', 'Use of Pointer Subtraction to Determine Size', 'The product subtracts one pointer from another in order to determine size, but this calculation can be incorrect if the pointers do not exist in the same memory chunk.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9f750aac-a997-4dda-bb9b-b3ec5d998418', 'CWE-470', 'Use of Externally-Controlled Input to Select Classes or Code (''Unsafe Reflection'')', 'The product uses external input with reflection to select which classes or code to use, but it does not sufficiently prevent the input from selecting improper classes or code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('485c024a-1f35-45d5-a3d2-a18c896ffb25', 'CWE-471', 'Modification of Assumed-Immutable Data (MAID)', 'The product does not properly protect an assumed-immutable element from being modified by an attacker.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e5b39842-2832-4f79-9ff2-f65243e1a474', 'CWE-472', 'External Control of Assumed-Immutable Web Parameter', 'The web application does not sufficiently verify inputs that are assumed to be immutable but are actually externally controllable, such as hidden form fields.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d412f302-8077-48c3-822d-1a8f4e91a9e5', 'CWE-473', 'PHP External Variable Modification', 'A PHP application does not properly protect against the modification of variables from external sources, such as query parameters or cookies. This can expose the application to numerous weaknesses that would not exist otherwise.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e3bdc1b2-d936-4465-a13a-1bd880116310', 'CWE-474', 'Use of Function with Inconsistent Implementations', 'The code uses a function that has inconsistent implementations across operating systems and versions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('62c29efa-91a4-4591-9d24-f1c9223d8f30', 'CWE-475', 'Undefined Behavior for Input to API', 'The behavior of this function is undefined unless its control parameter is set to a specific value.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('28f52501-3a6c-4ac7-b2d4-f4cf075808d4', 'CWE-476', 'NULL Pointer Dereference', 'The product dereferences a pointer that it expects to be valid but is NULL.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c3ca2e21-e70e-4990-9f5f-82c0939f3596', 'CWE-477', 'Use of Obsolete Function', 'The code uses deprecated or obsolete functions, which suggests that the code has not been actively reviewed or maintained.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1645d4ad-c7ac-42db-96c0-46d2e01e8f57', 'CWE-478', 'Missing Default Case in Multiple Condition Expression', 'The code does not have a default case in an expression with multiple conditions, such as a switch statement.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('678c0a10-1d9c-40cc-8c63-1d760c5b44a0', 'CWE-479', 'Signal Handler Use of a Non-reentrant Function', 'The product defines a signal handler that calls a non-reentrant function.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('88b081ad-e9fe-4903-8617-e8c524eff92d', 'CWE-480', 'Use of Incorrect Operator', 'The product accidentally uses the wrong operator, which changes the logic in security-relevant ways.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('174e9014-54d6-4ef5-bce8-dcb47dfbbb31', 'CWE-481', 'Assigning instead of Comparing', 'The code uses an operator for assignment when the intention was to perform a comparison.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('14afe50b-3a14-45ff-ad22-8ca3f65e12a0', 'CWE-482', 'Comparing instead of Assigning', 'The code uses an operator for comparison when the intention was to perform an assignment.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('89a296a9-57af-4125-9906-1a3882754128', 'CWE-483', 'Incorrect Block Delimitation', 'The code does not explicitly delimit a block that is intended to contain 2 or more statements, creating a logic error.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2ac89189-9214-4f82-a413-0b8d18c8d420', 'CWE-484', 'Omitted Break Statement in Switch', 'The product omits a break statement within a switch or similar construct, causing code associated with multiple conditions to execute. This can cause problems when the programmer only intended to execute code associated with one condition.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a5f8136c-76cd-4fb0-8e49-8fa4998f7518', 'CWE-486', 'Comparison of Classes by Name', 'The product compares classes by name, which can cause it to use the wrong class when multiple classes can have the same name.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c7d60bae-0b64-4ca0-b301-79f22f6504b3', 'CWE-487', 'Reliance on Package-level Scope', 'Java packages are not inherently closed; therefore, relying on them for code security is not a good practice.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('924f1585-4bde-4ece-a453-6c5b5c368ae9', 'CWE-488', 'Exposure of Data Element to Wrong Session', 'The product does not sufficiently enforce boundaries between the states of different sessions, causing data to be provided to, or used by, the wrong session.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4485a03b-91ec-46c6-8969-fbf77de2ed60', 'CWE-489', 'Active Debug Code', 'The product is released with debugging code still enabled or active.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('46086761-c3d0-43d4-83f9-701a69782b8d', 'CWE-491', 'Public cloneable() Method Without Final (''Object Hijack'')', 'A class has a cloneable() method that is not declared final, which allows an object to be created without calling the constructor. This can cause the object to be in an unexpected state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4bfb503d-dafd-4c74-b20d-ae53ec49eca6', 'CWE-492', 'Use of Inner Class Containing Sensitive Data', 'Inner classes are translated into classes that are accessible at package scope and may expose code that the programmer intended to keep private to attackers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('331bfa19-294b-4bdf-93c3-e8af93c09c4c', 'CWE-493', 'Critical Public Variable Without Final Modifier', 'The product has a critical public variable that is not final, which allows the variable to be modified to contain unexpected values.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('80279763-f10a-4730-afb9-b2f6fa5d4bb7', 'CWE-494', 'Download of Code Without Integrity Check', 'The product downloads source code or an executable from a remote location and executes the code without sufficiently verifying the origin and integrity of the code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0c460847-80b6-4302-b89b-dd969fde6f2d', 'CWE-495', 'Private Data Structure Returned From A Public Method', 'The product has a method that is declared public, but returns a reference to a private data structure, which could then be modified in unexpected ways.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b3e40a5c-9db6-486d-8ceb-a742fe893d03', 'CWE-496', 'Public Data Assigned to Private Array-Typed Field', 'Assigning public data to a private array is equivalent to giving public access to the array.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('06eb37fe-521d-4798-9341-30c38d9964b5', 'CWE-497', 'Exposure of Sensitive System Information to an Unauthorized Control Sphere', 'The product does not properly prevent sensitive system-level information from being accessed by unauthorized actors who do not have the same level of access to the underlying system as the product does.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d134c905-693f-4d4d-b614-6ba07f3b19ba', 'CWE-498', 'Cloneable Class Containing Sensitive Information', 'The code contains a class with sensitive data, but the class is cloneable. The data can then be accessed by cloning the class.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('35601a77-2826-429a-8268-d10c34fcea8b', 'CWE-499', 'Serializable Class Containing Sensitive Data', 'The code contains a class with sensitive data, but the class does not explicitly deny serialization. The data can be accessed by serializing the class through another class.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('683c0923-d38f-4090-bb17-7493fba2f435', 'CWE-500', 'Public Static Field Not Marked Final', 'An object contains a public static field that is not marked final, which might allow it to be modified in unexpected ways.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0f7e5cc7-858e-4603-b94e-822614ef16e7', 'CWE-501', 'Trust Boundary Violation', 'The product mixes trusted and untrusted data in the same data structure or structured message.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('00939a43-7e43-43c1-ac14-81400692c8ab', 'CWE-502', 'Deserialization of Untrusted Data', 'The product deserializes untrusted data without sufficiently ensuring that the resulting data will be valid.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a75f8516-bb1d-49bc-87f6-f310ea800f32', 'CWE-506', 'Embedded Malicious Code', 'The product contains code that appears to be malicious in nature.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6dfc514c-f4a0-4bfc-a51c-8cb45713449c', 'CWE-507', 'Trojan Horse', 'The product appears to contain benign or useful functionality, but it also contains code that is hidden from normal operation that violates the intended security policy of the user or the system administrator.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2fe728f8-fe6e-45fc-909a-d728050f7158', 'CWE-508', 'Non-Replicating Malicious Code', 'Non-replicating malicious code only resides on the target system or product that is attacked; it does not attempt to spread to other systems.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fb0a3652-b8d2-400a-a160-676619361019', 'CWE-509', 'Replicating Malicious Code (Virus or Worm)', 'Replicating malicious code, including viruses and worms, will attempt to attack other systems once it has successfully compromised the target system or the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3951b87d-ea99-4d8d-8ff1-a84fd4ab237b', 'CWE-510', 'Trapdoor', 'A trapdoor is a hidden piece of code that responds to a special input, allowing its user access to resources without passing through the normal security enforcement mechanism.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1329db24-b97d-42c8-91d2-1bb560b36b81', 'CWE-511', 'Logic/Time Bomb', 'The product contains code that is designed to disrupt the legitimate operation of the product (or its environment) when a certain time passes, or when a certain logical condition is met.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9d82fc22-defb-4062-8d3c-bcf7bd9f242a', 'CWE-512', 'Spyware', 'The product collects personally identifiable information about a human user or the user''s activities, but the product accesses this information using other resources besides itself, and it does not require that user''s explicit approval or direct input into the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9657ff39-a3c1-4c52-bb81-01b3a40b1b39', 'CWE-514', 'Covert Channel', 'A covert channel is a path that can be used to transfer information in a way not intended by the system''s designers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('83313fa8-6adc-4c71-830a-87d86387ec04', 'CWE-515', 'Covert Storage Channel', 'A covert storage channel transfers information through the setting of bits by one program and the reading of those bits by another. What distinguishes this case from that of ordinary operation is that the bits are used to convey encoded information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('52167429-a1eb-4d21-a40f-4942d6433620', 'CWE-520', '.NET Misconfiguration: Use of Impersonation', 'Allowing a .NET application to run at potentially escalated levels of access to the underlying operating and file systems can be dangerous and result in various forms of attacks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('50f9f4b7-9020-471a-84c0-2c6d1fdef905', 'CWE-521', 'Weak Password Requirements', 'The product does not require that users should have strong passwords.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0d28f901-7f40-41ae-ae88-0e4a9782d562', 'CWE-522', 'Insufficiently Protected Credentials', 'The product transmits or stores authentication credentials, but it uses an insecure method that is susceptible to unauthorized interception and/or retrieval.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('07c045b6-4635-4ac7-9963-ddf385d79095', 'CWE-523', 'Unprotected Transport of Credentials', 'Login pages do not use adequate measures to protect the user name and password while they are in transit from the client to the server.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d66797a4-6cd0-4740-ae92-73dc8fb8c9b6', 'CWE-524', 'Use of Cache Containing Sensitive Information', 'The code uses a cache that contains sensitive information, but the cache can be read by an actor outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ed5e9897-94ed-48a7-85a8-2257592ad0ee', 'CWE-525', 'Use of Web Browser Cache Containing Sensitive Information', 'The web application does not use an appropriate caching policy that specifies the extent to which each web page and associated form fields should be cached.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e3147506-2ec3-4bf2-928f-cfffd4522f8a', 'CWE-526', 'Cleartext Storage of Sensitive Information in an Environment Variable', 'The product uses an environment variable to store unencrypted sensitive information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bf199f8f-fc80-49e6-8198-9a28eda7b865', 'CWE-527', 'Exposure of Version-Control Repository to an Unauthorized Control Sphere', 'The product stores a CVS, git, or other repository in a directory, archive, or other resource that is stored, transferred, or otherwise made accessible to unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1e819e54-cc64-44c0-abab-d1fc3c87cbc8', 'CWE-528', 'Exposure of Core Dump File to an Unauthorized Control Sphere', 'The product generates a core dump file in a directory, archive, or other resource that is stored, transferred, or otherwise made accessible to unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1c8b137d-9304-4e70-8866-010c6b06e190', 'CWE-529', 'Exposure of Access Control List Files to an Unauthorized Control Sphere', 'The product stores access control list files in a directory or other container that is accessible to actors outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9d80c6cf-67da-494d-b86e-d55e8ab576c5', 'CWE-530', 'Exposure of Backup File to an Unauthorized Control Sphere', 'A backup file is stored in a directory or archive that is made accessible to unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4a721f01-0678-43ad-8f08-028a294f4c03', 'CWE-531', 'Inclusion of Sensitive Information in Test Code', 'Accessible test applications can pose a variety of security risks. Since developers or administrators rarely consider that someone besides themselves would even know about the existence of these applications, it is common for them to contain sensitive information or functions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4eddb25d-e967-4d44-954f-691224aaaf99', 'CWE-532', 'Insertion of Sensitive Information into Log File', 'The product writes sensitive information to a log file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b8f89242-5dda-4514-bb54-b4c1157b8cb4', 'CWE-535', 'Exposure of Information Through Shell Error Message', 'A command shell error message indicates that there exists an unhandled exception in the web application code. In many cases, an attacker can leverage the conditions that cause these errors in order to gain unauthorized access to the system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d7576bd0-00af-4d8a-a142-374cfe01948d', 'CWE-536', 'Servlet Runtime Error Message Containing Sensitive Information', 'A servlet error message indicates that there exists an unhandled exception in the web application code and may provide useful information to an attacker.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('44b08dd8-361f-42e3-9a7b-ed6eceff2602', 'CWE-537', 'Java Runtime Error Message Containing Sensitive Information', 'In many cases, an attacker can leverage the conditions that cause unhandled exception errors in order to gain unauthorized access to the system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d031e931-ac30-4c1b-bcad-e4583ec321b1', 'CWE-538', 'Insertion of Sensitive Information into Externally-Accessible File or Directory', 'The product places sensitive information into files or directories that are accessible to actors who are allowed to have access to the files, but not to the sensitive information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dbaed798-19e4-4413-a299-ea4ee68f49db', 'CWE-539', 'Use of Persistent Cookies Containing Sensitive Information', 'The web application uses persistent cookies, but the cookies contain sensitive information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('527b38fe-69bb-44b0-9415-82a864cce3c3', 'CWE-540', 'Inclusion of Sensitive Information in Source Code', 'Source code on a web server or repository often contains sensitive information and should generally not be accessible to users.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cf0eec36-1866-4276-9ccb-2c16511eea43', 'CWE-541', 'Inclusion of Sensitive Information in an Include File', 'If an include file source is accessible, the file can contain usernames and passwords, as well as sensitive information pertaining to the application and system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('373aa54e-40e4-4cf4-9625-f3c0f17a9c4f', 'CWE-543', 'Use of Singleton Pattern Without Synchronization in a Multithreaded Context', 'The product uses the singleton pattern when creating a resource within a multithreaded environment.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4d98a87a-af26-4560-a4a2-6e8ca9fcb601', 'CWE-544', 'Missing Standardized Error Handling Mechanism', 'The product does not use a standardized method for handling errors throughout the code, which might introduce inconsistent error handling and resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('98f0a1f5-5cb3-4b6d-b7ca-058171361225', 'CWE-546', 'Suspicious Comment', 'The code contains comments that suggest the presence of bugs, incomplete functionality, or weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a67034d0-fcd7-4911-b1d2-5d6ad2303e29', 'CWE-547', 'Use of Hard-coded, Security-relevant Constants', 'The product uses hard-coded constants instead of symbolic names for security-critical values, which increases the likelihood of mistakes during code maintenance or security policy change.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4efdbee5-a3f8-49e6-b23a-559e7ebb4367', 'CWE-548', 'Exposure of Information Through Directory Listing', 'The product inappropriately exposes a directory listing with an index of all the resources located inside of the directory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e2c31b0a-d4aa-4309-94e8-766a619186c1', 'CWE-549', 'Missing Password Field Masking', 'The product does not mask passwords during entry, increasing the potential for attackers to observe and capture passwords.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a97250f3-ed4e-4ed8-b598-9171a500af86', 'CWE-550', 'Server-generated Error Message Containing Sensitive Information', 'Certain conditions, such as network failure, will cause a server error message to be displayed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aaa6f184-d2af-4053-8082-14cc647ab28b', 'CWE-551', 'Incorrect Behavior Order: Authorization Before Parsing and Canonicalization', 'If a web server does not fully parse requested URLs before it examines them for authorization, it may be possible for an attacker to bypass authorization protection.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a644c56f-3240-4319-9d58-44304b684b9a', 'CWE-552', 'Files or Directories Accessible to External Parties', 'The product makes files or directories accessible to unauthorized actors, even though they should not be.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('01a538ed-1abf-46db-88bf-0938c62ef0d2', 'CWE-553', 'Command Shell in Externally Accessible Directory', 'A possible shell file exists in /cgi-bin/ or other accessible directories. This is extremely dangerous and can be used by an attacker to execute commands on the web server.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('50b8166f-280e-477b-9f6e-b2516e3b217d', 'CWE-554', 'ASP.NET Misconfiguration: Not Using Input Validation Framework', 'The ASP.NET application does not use an input validation framework.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aee75fa4-e394-4efe-9c92-0769298d1383', 'CWE-555', 'J2EE Misconfiguration: Plaintext Password in Configuration File', 'The J2EE application stores a plaintext password in a configuration file.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('130337bf-16a2-4480-8bf7-e95b9ff9fd3e', 'CWE-556', 'ASP.NET Misconfiguration: Use of Identity Impersonation', 'Configuring an ASP.NET application to run with impersonated credentials may give the application unnecessary privileges.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e9cb401b-11d5-412c-9ad5-3f762c4dc8b1', 'CWE-558', 'Use of getlogin() in Multithreaded Application', 'The product uses the getlogin() function in a multithreaded context, potentially causing it to return incorrect values.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8eb69672-4632-4d18-a527-88ca12f79685', 'CWE-560', 'Use of umask() with chmod-style Argument', 'The product calls umask() with an incorrect argument that is specified as if it is an argument to chmod().', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8d2a4324-6fac-4711-b25f-c7ad7381ba0b', 'CWE-561', 'Dead Code', 'The product contains dead code, which can never be executed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('86e75980-2636-4b1b-a857-68ec72bff6db', 'CWE-562', 'Return of Stack Variable Address', 'A function returns the address of a stack variable, which will cause unintended program behavior, typically in the form of a crash.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ff6e64b5-d5d0-42b4-8abc-af7bc4131e1f', 'CWE-563', 'Assignment to Variable without Use', 'The variable''s value is assigned but never used, making it a dead store.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('58164aff-ef30-4bcb-bb7f-219d03ab625d', 'CWE-564', 'SQL Injection: Hibernate', 'Using Hibernate to execute a dynamic SQL statement built with user-controlled input can allow an attacker to modify the statement''s meaning or to execute arbitrary SQL commands.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c701047e-1a26-48ce-9b4e-61bd58555342', 'CWE-565', 'Reliance on Cookies without Validation and Integrity Checking', 'The product relies on the existence or values of cookies when performing security-critical operations, but it does not properly ensure that the setting is valid for the associated user.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('53583adf-1195-441f-afee-1336d39e1a33', 'CWE-566', 'Authorization Bypass Through User-Controlled SQL Primary Key', 'The product uses a database table that includes records that should not be accessible to an actor, but it executes a SQL statement with a primary key that can be controlled by that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7dd28400-99c2-415c-a769-4f7a88bb1977', 'CWE-567', 'Unsynchronized Access to Shared Data in a Multithreaded Context', 'The product does not properly synchronize shared data, such as static variables across threads, which can lead to undefined behavior and unpredictable data changes.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9dd5181d-5912-4eb0-88f0-582f047c1e5d', 'CWE-568', 'finalize() Method Without super.finalize()', 'The product contains a finalize() method that does not call super.finalize().', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('07068d96-acf4-4a5e-a278-006067736830', 'CWE-570', 'Expression is Always False', 'The product contains an expression that will always evaluate to false.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2ef06b18-1014-4aeb-9d88-1b5d022ccd9e', 'CWE-571', 'Expression is Always True', 'The product contains an expression that will always evaluate to true.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('584d6db5-cbba-4ca3-beef-144aea5e536c', 'CWE-572', 'Call to Thread run() instead of start()', 'The product calls a thread''s run() method instead of calling start(), which causes the code to run in the thread of the caller instead of the callee.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('568652f2-9073-4880-b14d-f05e21e7e5ce', 'CWE-573', 'Improper Following of Specification by Caller', 'The product does not follow or incorrectly follows the specifications as required by the implementation language, environment, framework, protocol, or platform.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ba1300f5-41eb-4f81-ba19-1a692dbd9d15', 'CWE-574', 'EJB Bad Practices: Use of Synchronization Primitives', 'The product violates the Enterprise JavaBeans (EJB) specification by using thread synchronization primitives.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('31b58104-6cc3-41de-88d2-6a31f03e9a68', 'CWE-575', 'EJB Bad Practices: Use of AWT Swing', 'The product violates the Enterprise JavaBeans (EJB) specification by using AWT/Swing.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c39ca3d2-2f50-4a9b-97f2-1bd46291ecc0', 'CWE-576', 'EJB Bad Practices: Use of Java I/O', 'The product violates the Enterprise JavaBeans (EJB) specification by using the java.io package.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ab3a941e-26c3-4b96-9f59-cd2113df48bc', 'CWE-577', 'EJB Bad Practices: Use of Sockets', 'The product violates the Enterprise JavaBeans (EJB) specification by using sockets.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('48ade54a-774a-49e3-8efe-dfa6f1381ceb', 'CWE-578', 'EJB Bad Practices: Use of Class Loader', 'The product violates the Enterprise JavaBeans (EJB) specification by using the class loader.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b1c57593-2806-46a2-ba79-173937802801', 'CWE-579', 'J2EE Bad Practices: Non-serializable Object Stored in Session', 'The product stores a non-serializable object as an HttpSession attribute, which can hurt reliability.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d0cfd7ca-3ded-47bf-9563-a8f04c4118d0', 'CWE-580', 'clone() Method Without super.clone()', 'The product contains a clone() method that does not call super.clone() to obtain the new object.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9e140281-b322-456b-a8d1-f4deb45efa97', 'CWE-581', 'Object Model Violation: Just One of Equals and Hashcode Defined', 'The product does not maintain equal hashcodes for equal objects.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('69c19219-0ca1-4263-bd0e-7bb0f9d28896', 'CWE-582', 'Array Declared Public, Final, and Static', 'The product declares an array public, final, and static, which is not sufficient to prevent the array''s contents from being modified.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fd78daff-d25c-4fd1-8380-c6bbda6b3223', 'CWE-583', 'finalize() Method Declared Public', 'The product violates secure coding principles for mobile code by declaring a finalize() method public.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3ad2fdf8-5ec1-407e-979d-60a682930cea', 'CWE-584', 'Return Inside Finally Block', 'The code has a return statement inside a finally block, which will cause any thrown exception in the try block to be discarded.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('147ff581-788a-43e9-bfa2-879b89af966b', 'CWE-585', 'Empty Synchronized Block', 'The product contains an empty synchronized block.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b25bbf4e-23a4-453a-9cca-d9b72b2ae721', 'CWE-586', 'Explicit Call to Finalize()', 'The product makes an explicit call to the finalize() method from outside the finalizer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('032a0c99-10f4-4a22-924b-76baaa30e64e', 'CWE-587', 'Assignment of a Fixed Address to a Pointer', 'The product sets a pointer to a specific address other than NULL or 0.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bc26b2ae-dec7-4671-ac35-dbfb788a7a2d', 'CWE-588', 'Attempt to Access Child of a Non-structure Pointer', 'Casting a non-structure type to a structure type and accessing a field can lead to memory access errors or data corruption.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1e6eeb97-077a-4152-9874-f93fba162406', 'CWE-589', 'Call to Non-ubiquitous API', 'The product uses an API function that does not exist on all versions of the target platform. This could cause portability problems or inconsistencies that allow denial of service or other consequences.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0ac7b532-1f66-4fd7-b96c-0b53fb118521', 'CWE-590', 'Free of Memory not on the Heap', 'The product calls free() on a pointer to memory that was not allocated using associated heap allocation functions such as malloc(), calloc(), or realloc().', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('73da6dc3-7c68-41cc-a3c0-6feb2bf13851', 'CWE-591', 'Sensitive Data Storage in Improperly Locked Memory', 'The product stores sensitive data in memory that is not locked, or that has been incorrectly locked, which might cause the memory to be written to swap files on disk by the virtual memory manager. This can make the data more accessible to external actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('822fe23e-bfc8-411a-9436-4ca29895312b', 'CWE-593', 'Authentication Bypass: OpenSSL CTX Object Modified after SSL Objects are Created', 'The product modifies the SSL context after connection creation has begun.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8b42e4f6-7ed5-402c-8baf-ee6304a7b0c4', 'CWE-594', 'J2EE Framework: Saving Unserializable Objects to Disk', 'When the J2EE container attempts to write unserializable objects to disk there is no guarantee that the process will complete successfully.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6ca36cc6-d14f-401a-aacb-ab1c3f9ad787', 'CWE-595', 'Comparison of Object References Instead of Object Contents', 'The product compares object references instead of the contents of the objects themselves, preventing it from detecting equivalent objects.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('10695d9a-1e42-4278-82e5-aa0e6e981549', 'CWE-597', 'Use of Wrong Operator in String Comparison', 'The product uses the wrong operator when comparing a string, such as using == when the .equals() method should be used instead.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ccd819ab-529a-4049-a606-6f5decb6ca90', 'CWE-598', 'Use of HTTP Request With Sensitive Query String', 'The web application uses an HTTP method to process a request, but the request includes sensitive information in the query string.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('43811c1f-0a22-4225-b322-b27ee3cad4a3', 'CWE-599', 'Missing Validation of OpenSSL Certificate', 'The product uses OpenSSL and trusts or uses a certificate without using the SSL_get_verify_result() function to ensure that the certificate satisfies all necessary security requirements.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('06e7e9b0-fc62-4c12-8e9a-ed948efa44c7', 'CWE-600', 'Uncaught Exception in Servlet', 'The Servlet does not catch all exceptions, which may reveal sensitive debugging information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('92606a9f-7971-47ac-abfc-8bc28023cf33', 'CWE-601', 'URL Redirection to Untrusted Site (''Open Redirect'')', 'The web application accepts a user-controlled input that specifies a link to an external site, and uses that link in a redirect.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('baf49022-0edd-4a51-a9ba-b019e38256c0', 'CWE-602', 'Client-Side Enforcement of Server-Side Security', 'The product is composed of a server that relies on the client to implement a mechanism that is intended to protect the server.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f37a2796-b985-4c9b-b357-507943c2857d', 'CWE-603', 'Use of Client-Side Authentication', 'A client/server product performs authentication within client code but not in server code, allowing server-side authentication to be bypassed via a modified client that omits the authentication check.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d0f00733-65c1-4247-87c4-4d14619ea76f', 'CWE-605', 'Multiple Binds to the Same Port', 'When multiple sockets are allowed to bind to the same port, other services on that port may be stolen or spoofed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d6608479-3838-40b0-a669-58d683155968', 'CWE-606', 'Unchecked Input for Loop Condition', 'The product does not properly check inputs that are used for loop conditions, potentially leading to a denial of service or other consequences because of excessive looping.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8884ad3c-0903-4a30-9759-8d39df783806', 'CWE-607', 'Public Static Final Field References Mutable Object', 'A public or protected static final field references a mutable object, which allows the object to be changed by malicious code, or accidentally from another package.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c3b21e7e-7872-4d55-af0e-4bb98a748197', 'CWE-608', 'Struts: Non-private Field in ActionForm Class', 'An ActionForm class contains a field that has not been declared private, which can be accessed without using a setter or getter.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('07b5ebd2-91e7-46a8-a381-29324388c9ce', 'CWE-609', 'Double-Checked Locking', 'The product uses double-checked locking to access a resource without the overhead of explicit synchronization, but the locking is insufficient.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6622d5f2-c73a-419f-986d-34269a007137', 'CWE-610', 'Externally Controlled Reference to a Resource in Another Sphere', 'The product uses an externally controlled name or reference that resolves to a resource that is outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0816917a-9423-4d26-94f3-f79bee5d1a02', 'CWE-611', 'Improper Restriction of XML External Entity Reference', 'The product processes an XML document that can contain XML entities with URIs that resolve to documents outside of the intended sphere of control, causing the product to embed incorrect documents into its output.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3ddd6b75-7476-4f3b-8c0d-3ff42986cdde', 'CWE-612', 'Improper Authorization of Index Containing Sensitive Information', 'The product creates a search index of private or sensitive documents, but it does not properly limit index access to actors who are authorized to see the original information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('013ec9ab-797b-42dc-9537-ee3e4f0338c1', 'CWE-613', 'Insufficient Session Expiration', 'According to WASC, Insufficient Session Expiration is when a web site permits an attacker to reuse old session credentials or session IDs for authorization.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('54f2d4e1-af59-4313-8d76-7d0584c3ba9b', 'CWE-614', 'Sensitive Cookie in HTTPS Session Without ''Secure'' Attribute', 'The Secure attribute for sensitive cookies in HTTPS sessions is not set.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7b2649c9-52c1-4e51-84cc-d790ac6cb610', 'CWE-615', 'Inclusion of Sensitive Information in Source Code Comments', 'While adding general comments is very useful, some programmers tend to leave important data, such as: filenames related to the web application, old links or links which were not meant to be browsed by users, old code fragments, etc.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d6fd120a-8ffc-4727-873f-dbbdc528a9a1', 'CWE-616', 'Incomplete Identification of Uploaded File Variables (PHP)', 'The PHP application uses an old method for processing uploaded files by referencing the four global variables that are set for each file (e.g. $varname, $varname_size, $varname_name, $varname_type). These variables could be overwritten by attackers, causing the application to process unauthorized files.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9d899d0c-daf5-47c0-b156-ef3e024fa970', 'CWE-617', 'Reachable Assertion', 'The product contains an assert() or similar statement that can be triggered by an attacker, which leads to an application exit or other behavior that is more severe than necessary.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c357bcd8-5e57-4e7f-817c-2b1d8fa4af2c', 'CWE-618', 'Exposed Unsafe ActiveX Method', 'An ActiveX control is intended for use in a web browser, but it exposes dangerous methods that perform actions that are outside of the browser''s security model (e.g. the zone or domain).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0798f2c2-79a9-471e-acc0-66f4e511096f', 'CWE-619', 'Dangling Database Cursor (''Cursor Injection'')', 'If a database cursor is not closed properly, then it could become accessible to other users while retaining the same privileges that were originally assigned, leaving the cursor dangling.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c627bafa-4e76-4cba-9d38-e2e8e1b6ffa8', 'CWE-620', 'Unverified Password Change', 'When setting a new password for a user, the product does not require knowledge of the original password, or using another form of authentication.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('30596e7d-130d-4737-b078-37a447e69062', 'CWE-621', 'Variable Extraction Error', 'The product uses external input to determine the names of variables into which information is extracted, without verifying that the names of the specified variables are valid. This could cause the program to overwrite unintended variables.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('febf8bcd-c25b-4087-919b-2fbcc37d732a', 'CWE-622', 'Improper Validation of Function Hook Arguments', 'The product adds hooks to user-accessible API functions, but it does not properly validate the arguments. This could lead to resultant vulnerabilities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c00d32bb-2b33-425d-b30c-de7e92ff52ca', 'CWE-623', 'Unsafe ActiveX Control Marked Safe For Scripting', 'An ActiveX control is intended for restricted use, but it has been marked as safe-for-scripting.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('413cb657-fde7-4313-bca7-e5b0884ea7ac', 'CWE-624', 'Executable Regular Expression Error', 'The product uses a regular expression that either (1) contains an executable component with user-controlled inputs, or (2) allows a user to enable execution by inserting pattern modifiers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('30cb45ab-5a51-4653-8ae7-e57dcb26a89b', 'CWE-625', 'Permissive Regular Expression', 'The product uses a regular expression that does not sufficiently restrict the set of allowed values.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a2e46ca2-4559-4fbd-9eb9-09554e591ed5', 'CWE-626', 'Null Byte Interaction Error (Poison Null Byte)', 'The product does not properly handle null bytes or NUL characters when passing data between different representations or components.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9c1b1cf7-9b32-4d1b-a4fd-8fef41cd5f58', 'CWE-627', 'Dynamic Variable Evaluation', 'In a language where the user can influence the name of a variable at runtime, if the variable names are not controlled, an attacker can read or write to arbitrary variables, or access arbitrary functions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('55e46e8d-b084-461f-9dd1-df878d8f058c', 'CWE-628', 'Function Call with Incorrectly Specified Arguments', 'The product calls a function, procedure, or routine with arguments that are not correctly specified, leading to always-incorrect behavior and resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e164b10e-bcf3-4972-875a-f69fff16432d', 'CWE-636', 'Not Failing Securely (''Failing Open'')', 'When the product encounters an error condition or failure, its design requires it to fall back to a state that is less secure than other options that are available, such as selecting the weakest encryption algorithm or using the most permissive access control restrictions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('39747ee3-7ac2-4ef8-a1a1-96228a65126f', 'CWE-637', 'Unnecessary Complexity in Protection Mechanism (Not Using ''Economy of Mechanism'')', 'The product uses a more complex mechanism than necessary, which could lead to resultant weaknesses when the mechanism is not correctly understood, modeled, configured, implemented, or used.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1b74ba12-743a-4bd8-8658-0ac37ba86105', 'CWE-638', 'Not Using Complete Mediation', 'The product does not perform access checks on a resource every time the resource is accessed by an entity, which can create resultant weaknesses if that entity''s rights or privileges change over time.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bb35d34c-4bf7-4e12-8d80-13547a6c4da8', 'CWE-639', 'Authorization Bypass Through User-Controlled Key', 'The system''s authorization functionality does not prevent one user from gaining access to another user''s data or record by modifying the key value identifying the data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('184c5d7b-c2ee-4d95-b997-d2baf82275ba', 'CWE-640', 'Weak Password Recovery Mechanism for Forgotten Password', 'The product contains a mechanism for users to recover or change their passwords without knowing the original password, but the mechanism is weak.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7df5326f-a5c1-4c41-8791-78de27f109d8', 'CWE-641', 'Improper Restriction of Names for Files and Other Resources', 'The product constructs the name of a file or other resource using input from an upstream component, but it does not restrict or incorrectly restricts the resulting name.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b17f7f07-cfec-4796-8f9d-cc06ec998a02', 'CWE-642', 'External Control of Critical State Data', 'The product stores security-critical state information about its users, or the product itself, in a location that is accessible to unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f93b567d-f88f-40b0-90a6-30cce4d84421', 'CWE-643', 'Improper Neutralization of Data within XPath Expressions (''XPath Injection'')', 'The product uses external input to dynamically construct an XPath expression used to retrieve data from an XML database, but it does not neutralize or incorrectly neutralizes that input. This allows an attacker to control the structure of the query.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('76796f24-18e5-433f-9328-222559448f51', 'CWE-644', 'Improper Neutralization of HTTP Headers for Scripting Syntax', 'The product does not neutralize or incorrectly neutralizes web scripting syntax in HTTP headers that can be used by web browser components that can process raw headers, such as Flash.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dae9864f-45c3-438e-beb6-9fcc9982c846', 'CWE-645', 'Overly Restrictive Account Lockout Mechanism', 'The product contains an account lockout protection mechanism, but the mechanism is too restrictive and can be triggered too easily, which allows attackers to deny service to legitimate users by causing their accounts to be locked out.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cf0020d8-d107-4f17-bea6-f7192b8850a9', 'CWE-646', 'Reliance on File Name or Extension of Externally-Supplied File', 'The product allows a file to be uploaded, but it relies on the file name or extension of the file to determine the appropriate behaviors. This could be used by attackers to cause the file to be misclassified and processed in a dangerous fashion.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a2ab5403-6cd7-4813-b9fd-a8f89d582dec', 'CWE-647', 'Use of Non-Canonical URL Paths for Authorization Decisions', 'The product defines policy namespaces and makes authorization decisions based on the assumption that a URL is canonical. This can allow a non-canonical URL to bypass the authorization.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6385e48f-64a0-4321-b607-6b28e1fa48d8', 'CWE-648', 'Incorrect Use of Privileged APIs', 'The product does not conform to the API requirements for a function call that requires extra privileges. This could allow attackers to gain privileges by causing the function to be called incorrectly.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('704ffb54-0276-4e03-8bc7-305b5065e16d', 'CWE-649', 'Reliance on Obfuscation or Encryption of Security-Relevant Inputs without Integrity Checking', 'The product uses obfuscation or encryption of inputs that should not be mutable by an external actor, but the product does not use integrity checks to detect if those inputs have been modified.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1d4a4c18-b200-4b89-90f3-5c52bec8c4fc', 'CWE-650', 'Trusting HTTP Permission Methods on the Server Side', 'The server contains a protection mechanism that assumes that any URI that is accessed using HTTP GET will not cause a state change to the associated resource. This might allow attackers to bypass intended access restrictions and conduct resource modification and deletion attacks, since some applications allow GET to modify state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bc714cdc-7a96-4a3e-b5fc-4420e0ec6798', 'CWE-651', 'Exposure of WSDL File Containing Sensitive Information', 'The Web services architecture may require exposing a Web Service Definition Language (WSDL) file that contains information on the publicly accessible services and how callers of these services should interact with them (e.g. what parameters they expect and what types they return).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('98f91df7-a7f5-4328-8ac9-d1c3b8aa4e8b', 'CWE-652', 'Improper Neutralization of Data within XQuery Expressions (''XQuery Injection'')', 'The product uses external input to dynamically construct an XQuery expression used to retrieve data from an XML database, but it does not neutralize or incorrectly neutralizes that input. This allows an attacker to control the structure of the query.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('df381aed-8764-4e62-a26d-95bc32e4abb5', 'CWE-653', 'Improper Isolation or Compartmentalization', 'The product does not properly compartmentalize or isolate functionality, processes, or resources that require different privilege levels, rights, or permissions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('43ed0a88-96c8-4111-871e-a1207058bcc4', 'CWE-654', 'Reliance on a Single Factor in a Security Decision', 'A protection mechanism relies exclusively, or to a large extent, on the evaluation of a single condition or the integrity of a single object or entity in order to make a decision about granting access to restricted resources or functionality.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b36b1ac4-70bf-4e8e-bd7a-c1696645a09d', 'CWE-655', 'Insufficient Psychological Acceptability', 'The product has a protection mechanism that is too difficult or inconvenient to use, encouraging non-malicious users to disable or bypass the mechanism, whether by accident or on purpose.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a6544a78-1438-4e63-ba72-b06c99efac34', 'CWE-656', 'Reliance on Security Through Obscurity', 'The product uses a protection mechanism whose strength depends heavily on its obscurity, such that knowledge of its algorithms or key data is sufficient to defeat the mechanism.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('602dd39e-5bdc-45e8-a2ea-d435b3485154', 'CWE-657', 'Violation of Secure Design Principles', 'The product violates well-established principles for secure design.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c7f096c9-4c42-4b31-88b1-02bb486c9e93', 'CWE-662', 'Improper Synchronization', 'The product utilizes multiple threads, processes, components, or systems to allow temporary access to a shared resource that can only be exclusive to one process at a time, but it does not properly synchronize these actions, which might cause simultaneous accesses of this resource by multiple threads or processes.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4cde9104-6e6b-4175-81b8-d2d734577b9a', 'CWE-663', 'Use of a Non-reentrant Function in a Concurrent Context', 'The product calls a non-reentrant function in a concurrent context in which a competing code sequence (e.g. thread or signal handler) may have an opportunity to call the same function or otherwise influence its state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6b8a23ee-e737-4181-86d5-becffe31bd96', 'CWE-664', 'Improper Control of a Resource Through its Lifetime', 'The product does not maintain or incorrectly maintains control over a resource throughout its lifetime of creation, use, and release.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8aaa295d-f8a9-4be8-b2cb-da1769a0cba5', 'CWE-665', 'Improper Initialization', 'The product does not initialize or incorrectly initializes a resource, which might leave the resource in an unexpected state when it is accessed or used.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('442896e3-2002-4532-8128-b9be1b3d9f60', 'CWE-666', 'Operation on Resource in Wrong Phase of Lifetime', 'The product performs an operation on a resource at the wrong phase of the resource''s lifecycle, which can lead to unexpected behaviors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3f232b19-6f6a-40dd-87ba-d1bd2a48b590', 'CWE-667', 'Improper Locking', 'The product does not properly acquire or release a lock on a resource, leading to unexpected resource state changes and behaviors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a9c09958-380f-4402-ac33-b91b1f3dcf72', 'CWE-668', 'Exposure of Resource to Wrong Sphere', 'The product exposes a resource to the wrong control sphere, providing unintended actors with inappropriate access to the resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0c870f78-9106-4af3-ab96-862c5fd40194', 'CWE-669', 'Incorrect Resource Transfer Between Spheres', 'The product does not properly transfer a resource/behavior to another sphere, or improperly imports a resource/behavior from another sphere, in a manner that provides unintended control over that resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('200564af-16ea-465c-9165-c3c6a4870261', 'CWE-670', 'Always-Incorrect Control Flow Implementation', 'The code contains a control flow path that does not reflect the algorithm that the path is intended to implement, leading to incorrect behavior any time this path is navigated.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3e8d300e-1101-454f-9462-98de33d90040', 'CWE-671', 'Lack of Administrator Control over Security', 'The product uses security features in a way that prevents the product''s administrator from tailoring security settings to reflect the environment in which the product is being used. This introduces resultant weaknesses or prevents it from operating at a level of security that is desired by the administrator.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b39536f7-b096-491b-bc08-1d5416b805f4', 'CWE-672', 'Operation on a Resource after Expiration or Release', 'The product uses, accesses, or otherwise operates on a resource after that resource has been expired, released, or revoked.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5f40cadb-7484-453a-a5b9-0048559c0df2', 'CWE-673', 'External Influence of Sphere Definition', 'The product does not prevent the definition of control spheres from external actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('101b97de-76af-44e9-9ba0-3a1d859b56b3', 'CWE-674', 'Uncontrolled Recursion', 'The product does not properly control the amount of recursion that takes place, consuming excessive resources, such as allocated memory or the program stack.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('30239ac7-55f5-407f-b076-edf69ab5fd06', 'CWE-675', 'Multiple Operations on Resource in Single-Operation Context', 'The product performs the same operation on a resource two or more times, when the operation should only be applied once.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8cf4b553-4bd0-45da-a99b-2aef9052d6dd', 'CWE-676', 'Use of Potentially Dangerous Function', 'The product invokes a potentially dangerous function that could introduce a vulnerability if it is used incorrectly, but the function can also be used safely.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('03cb74c4-4f36-4977-be68-774d8ca4617f', 'CWE-680', 'Integer Overflow to Buffer Overflow', 'The product performs a calculation to determine how much memory to allocate, but an integer overflow can occur that causes less memory to be allocated than expected, leading to a buffer overflow.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('531f7415-822a-4416-946d-efd8a1cfa4f1', 'CWE-681', 'Incorrect Conversion between Numeric Types', 'When converting from one data type to another, such as long to integer, data can be omitted or translated in a way that produces unexpected values. If the resulting values are used in a sensitive context, then dangerous behaviors may occur.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2b055602-1322-4de1-ba7d-bd4d6cc0589e', 'CWE-682', 'Incorrect Calculation', 'The product performs a calculation that generates incorrect or unintended results that are later used in security-critical decisions or resource management.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('647d524c-1f96-429a-88a1-fcf5195667a8', 'CWE-683', 'Function Call With Incorrect Order of Arguments', 'The product calls a function, procedure, or routine, but the caller specifies the arguments in an incorrect order, leading to resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('24f44e66-e4a1-4fc8-bd2e-dd0d3c6acf84', 'CWE-684', 'Incorrect Provision of Specified Functionality', 'The code does not function according to its published specifications, potentially leading to incorrect usage.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d2652465-4e30-4ce7-99f0-f6b3eb4c9990', 'CWE-685', 'Function Call With Incorrect Number of Arguments', 'The product calls a function, procedure, or routine, but the caller specifies too many arguments, or too few arguments, which may lead to undefined behavior and resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('363b1fb0-719d-417f-b75b-efa7054455e4', 'CWE-686', 'Function Call With Incorrect Argument Type', 'The product calls a function, procedure, or routine, but the caller specifies an argument that is the wrong data type, which may lead to resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cb836ea3-0181-49da-8a83-46b473bd84ea', 'CWE-687', 'Function Call With Incorrectly Specified Argument Value', 'The product calls a function, procedure, or routine, but the caller specifies an argument that contains the wrong value, which may lead to resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('671b870a-4827-459a-af2e-b2197ada74e9', 'CWE-688', 'Function Call With Incorrect Variable or Reference as Argument', 'The product calls a function, procedure, or routine, but the caller specifies the wrong variable or reference as one of the arguments, which may lead to undefined behavior and resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('354bb1f2-cdeb-49ba-9eb6-6d4c919d76ad', 'CWE-689', 'Permission Race Condition During Resource Copy', 'The product, while copying or cloning a resource, does not set the resource''s permissions or access control until the copy is complete, leaving the resource exposed to other spheres while the copy is taking place.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ec55b48d-f107-42fc-88b1-7124ae98d0b8', 'CWE-690', 'Unchecked Return Value to NULL Pointer Dereference', 'The product does not check for an error after calling a function that can return with a NULL pointer if the function fails, which leads to a resultant NULL pointer dereference.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9c3eef8e-0191-4969-9fc8-b8459d408c4c', 'CWE-691', 'Insufficient Control Flow Management', 'The code does not sufficiently manage its control flow during execution, creating conditions in which the control flow can be modified in unexpected ways.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e3860b0b-0b1e-4e3e-ad43-3afaa5fe79f7', 'CWE-692', 'Incomplete Denylist to Cross-Site Scripting', 'The product uses a denylist-based protection mechanism to defend against XSS attacks, but the denylist is incomplete, allowing XSS variants to succeed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('96f96255-6d97-449e-93f6-a29375fec438', 'CWE-693', 'Protection Mechanism Failure', 'The product does not use or incorrectly uses a protection mechanism that provides sufficient defense against directed attacks against the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('44a86c2a-846b-4ad0-824a-fed37fa6ad8c', 'CWE-694', 'Use of Multiple Resources with Duplicate Identifier', 'The product uses multiple resources that can have the same identifier, in a context in which unique identifiers are required.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c3f8dedc-0524-4d72-a1d1-fc6f8c5af212', 'CWE-695', 'Use of Low-Level Functionality', 'The product uses low-level functionality that is explicitly prohibited by the framework or specification under which the product is supposed to operate.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4b264f16-1018-445d-9aa6-33882f307012', 'CWE-696', 'Incorrect Behavior Order', 'The product performs multiple related behaviors, but the behaviors are performed in the wrong order in ways that may produce resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3ca94fbf-1d4a-43b5-b4b8-214b5a527860', 'CWE-697', 'Incorrect Comparison', 'The product compares two entities in a security-relevant context, but the comparison is incorrect.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d01fac1f-9107-4f00-abe5-76d09ba26842', 'CWE-698', 'Execution After Redirect (EAR)', 'The web application sends a redirect to another location, but instead of exiting, it executes additional code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('145a60eb-dbaf-4094-9ae2-2c215d798300', 'CWE-703', 'Improper Check or Handling of Exceptional Conditions', 'The product does not properly anticipate or handle exceptional conditions that rarely occur during normal operation of the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('25874e5d-6a79-447f-8221-70bccf873e6e', 'CWE-704', 'Incorrect Type Conversion or Cast', 'The product does not correctly convert an object, resource, or structure from one type to a different type.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7c74bd49-67ce-447e-a14b-22a3e556f1b1', 'CWE-705', 'Incorrect Control Flow Scoping', 'The product does not properly return control flow to the proper location after it has completed a task or detected an unusual condition.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7671d5d1-cf44-4c68-a817-66a90ea8e863', 'CWE-706', 'Use of Incorrectly-Resolved Name or Reference', 'The product uses a name or reference to access a resource, but the name/reference resolves to a resource that is outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1ad0afc3-9ecd-4553-b513-5bcfd6392e7c', 'CWE-707', 'Improper Neutralization', 'The product does not ensure or incorrectly ensures that structured messages or data are well-formed and that certain security properties are met before being read from an upstream component or sent to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f0eb5ce8-c076-4fb2-b355-c888ba4476a2', 'CWE-708', 'Incorrect Ownership Assignment', 'The product assigns an owner to a resource, but the owner is outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fe87aa0a-b60c-4525-a261-ca716d67d344', 'CWE-710', 'Improper Adherence to Coding Standards', 'The product does not follow certain coding rules for development, which can lead to resultant weaknesses or increase the severity of the associated vulnerabilities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('eb98f8b4-623e-4979-a997-f0820da65de2', 'CWE-732', 'Incorrect Permission Assignment for Critical Resource', 'The product specifies permissions for a security-critical resource in a way that allows that resource to be read or modified by unintended actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b1185ab6-5f17-4c3c-a2aa-d388ffde32a9', 'CWE-733', 'Compiler Optimization Removal or Modification of Security-critical Code', 'The developer builds a security-critical protection mechanism into the software, but the compiler optimizes the program such that the mechanism is removed or modified.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f822cfe0-ba26-4ba7-af67-3f7b2bea5dd9', 'CWE-749', 'Exposed Dangerous Method or Function', 'The product provides an Applications Programming Interface (API) or similar interface for interaction with external actors, but the interface includes a dangerous method or function that is not properly restricted.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0ea7778f-66af-471d-94bc-ac3ce23f5053', 'CWE-754', 'Improper Check for Unusual or Exceptional Conditions', 'The product does not check or incorrectly checks for unusual or exceptional conditions that are not expected to occur frequently during day to day operation of the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4521a978-3528-4b82-9f40-99af2d545d18', 'CWE-755', 'Improper Handling of Exceptional Conditions', 'The product does not handle or incorrectly handles an exceptional condition.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('406fef1e-251a-4c5b-a4ac-865b9195bd59', 'CWE-756', 'Missing Custom Error Page', 'The product does not return custom error pages to the user, possibly exposing sensitive information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('115ffa37-2e39-4ffa-a074-a52a41063d1f', 'CWE-757', 'Selection of Less-Secure Algorithm During Negotiation (''Algorithm Downgrade'')', 'A protocol or its implementation supports interaction between multiple actors and allows those actors to negotiate which algorithm should be used as a protection mechanism such as encryption or authentication, but it does not select the strongest algorithm that is available to both parties.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c9100bc7-28f3-4457-af4a-225f6b609da2', 'CWE-758', 'Reliance on Undefined, Unspecified, or Implementation-Defined Behavior', 'The product uses an API function, data structure, or other entity in a way that relies on properties that are not always guaranteed to hold for that entity.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8847271b-8846-4619-bbd7-22e844a7b7c4', 'CWE-759', 'Use of a One-Way Hash without a Salt', 'The product uses a one-way cryptographic hash against an input that should not be reversible, such as a password, but the product does not also use a salt as part of the input.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9a2fd1fd-0184-4e13-b091-efb476fa866b', 'CWE-760', 'Use of a One-Way Hash with a Predictable Salt', 'The product uses a one-way cryptographic hash against an input that should not be reversible, such as a password, but the product uses a predictable salt as part of the input.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f1ed689b-174b-4a8a-8946-14219b4a3c57', 'CWE-761', 'Free of Pointer not at Start of Buffer', 'The product calls free() on a pointer to a memory resource that was allocated on the heap, but the pointer is not at the start of the buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('917bbf8b-1401-4295-adf4-60d7f604f4dc', 'CWE-762', 'Mismatched Memory Management Routines', 'The product attempts to return a memory resource to the system, but it calls a release function that is not compatible with the function that was originally used to allocate that resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('53dc0ad4-2813-4d0b-ae66-244ca886c8a1', 'CWE-763', 'Release of Invalid Pointer or Reference', 'The product attempts to return a memory resource to the system, but it calls the wrong release function or calls the appropriate release function incorrectly.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7205da4a-f291-439e-b1fd-401f01f44dbe', 'CWE-764', 'Multiple Locks of a Critical Resource', 'The product locks a critical resource more times than intended, leading to an unexpected state in the system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a9e2637f-0fc6-4949-af60-2b62b32e1272', 'CWE-765', 'Multiple Unlocks of a Critical Resource', 'The product unlocks a critical resource more times than intended, leading to an unexpected state in the system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8fd7347d-37e2-4f15-86c7-ffc80b250fa5', 'CWE-766', 'Critical Data Element Declared Public', 'The product declares a critical variable, field, or member to be public when intended security policy requires it to be private.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0ec9acb7-7173-4798-a16e-bce42cd3c9a3', 'CWE-767', 'Access to Critical Private Variable via Public Method', 'The product defines a public method that reads or modifies a private variable.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('96745f22-7971-49fc-b8ec-d77632172869', 'CWE-768', 'Incorrect Short Circuit Evaluation', 'The product contains a conditional statement with multiple logical expressions in which one of the non-leading expressions may produce side effects. This may lead to an unexpected state in the program after the execution of the conditional, because short-circuiting logic may prevent the side effects from occurring.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8ae4771d-9955-42af-837c-b63ea951f4f2', 'CWE-770', 'Allocation of Resources Without Limits or Throttling', 'The product allocates a reusable resource or group of resources on behalf of an actor without imposing any intended restrictions on the size or number of resources that can be allocated.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('88042edf-e835-4889-97b1-68f956d459f0', 'CWE-771', 'Missing Reference to Active Allocated Resource', 'The product does not properly maintain a reference to a resource that has been allocated, which prevents the resource from being reclaimed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('377c16a0-832d-4cba-8efb-eab7c1788ba7', 'CWE-772', 'Missing Release of Resource after Effective Lifetime', 'The product does not release a resource after its effective lifetime has ended, i.e., after the resource is no longer needed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ad2cbc0a-354f-4df7-9877-e2f819fcc513', 'CWE-773', 'Missing Reference to Active File Descriptor or Handle', 'The product does not properly maintain references to a file descriptor or handle, which prevents that file descriptor/handle from being reclaimed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ac4bf93b-8cf5-4da1-98f3-3ef7a9bb0198', 'CWE-774', 'Allocation of File Descriptors or Handles Without Limits or Throttling', 'The product allocates file descriptors or handles on behalf of an actor without imposing any restrictions on how many descriptors can be allocated, in violation of the intended security policy for that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('08b46815-8031-446e-8def-0400454effb5', 'CWE-775', 'Missing Release of File Descriptor or Handle after Effective Lifetime', 'The product does not release a file descriptor or handle after its effective lifetime has ended, i.e., after the file descriptor/handle is no longer needed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0a027644-fd46-4b6f-bc0f-44fcec320068', 'CWE-776', 'Improper Restriction of Recursive Entity References in DTDs (''XML Entity Expansion'')', 'The product uses XML documents and allows their structure to be defined with a Document Type Definition (DTD), but it does not properly control the number of recursive definitions of entities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dbdc7c1f-d61e-4387-a841-85a47394565a', 'CWE-777', 'Regular Expression without Anchors', 'The product uses a regular expression to perform neutralization, but the regular expression is not anchored and may allow malicious or malformed data to slip through.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('110471e2-7638-4471-b06c-2a1a8b5aab8a', 'CWE-778', 'Insufficient Logging', 'When a security-critical event occurs, the product either does not record the event or omits important details about the event when logging it.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c8f80ed8-63f0-465b-b67a-613bdcbe2ce0', 'CWE-779', 'Logging of Excessive Data', 'The product logs too much information, making log files hard to process and possibly hindering recovery efforts or forensic analysis after an attack.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d24728e4-a5db-48cf-b362-0bfe4d0c2fad', 'CWE-780', 'Use of RSA Algorithm without OAEP', 'The product uses the RSA algorithm but does not incorporate Optimal Asymmetric Encryption Padding (OAEP), which might weaken the encryption.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cea69559-cc34-4883-a323-b9b1e7f99c91', 'CWE-781', 'Improper Address Validation in IOCTL with METHOD_NEITHER I/O Control Code', 'The product defines an IOCTL that uses METHOD_NEITHER for I/O, but it does not validate or incorrectly validates the addresses that are provided.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('026f79e1-dba1-4ec0-a3a6-bcea27a3e18b', 'CWE-782', 'Exposed IOCTL with Insufficient Access Control', 'The product implements an IOCTL with functionality that should be restricted, but it does not properly enforce access control for the IOCTL.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c6fe72a8-05b5-47b7-8897-ae12f0869963', 'CWE-783', 'Operator Precedence Logic Error', 'The product uses an expression in which operator precedence causes incorrect logic to be used.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5465fd96-be0b-49e1-9ff5-028061afd7c9', 'CWE-784', 'Reliance on Cookies without Validation and Integrity Checking in a Security Decision', 'The product uses a protection mechanism that relies on the existence or values of a cookie, but it does not properly ensure that the cookie is valid for the associated user.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c0e9a241-af87-4542-ab6a-f00d8cae7a68', 'CWE-785', 'Use of Path Manipulation Function without Maximum-sized Buffer', 'The product invokes a function for normalizing paths or file names, but it provides an output buffer that is smaller than the maximum possible size, such as PATH_MAX.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1447713f-0567-4597-a84c-6a0e8b2a9e35', 'CWE-786', 'Access of Memory Location Before Start of Buffer', 'The product reads or writes to a buffer using an index or pointer that references a memory location prior to the beginning of the buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f966576f-1169-4f96-bb01-70e46e98086f', 'CWE-787', 'Out-of-bounds Write', 'The product writes data past the end, or before the beginning, of the intended buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5ff70a7e-add9-4711-9a6f-03877fb5d693', 'CWE-788', 'Access of Memory Location After End of Buffer', 'The product reads or writes to a buffer using an index or pointer that references a memory location after the end of the buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9c848d2b-d12c-4e9e-9353-c36ad1d0ef69', 'CWE-789', 'Memory Allocation with Excessive Size Value', 'The product allocates memory based on an untrusted, large size value, but it does not ensure that the size is within expected limits, allowing arbitrary amounts of memory to be allocated.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('da2f18d5-716d-4567-a9ce-56d7e425ff06', 'CWE-790', 'Improper Filtering of Special Elements', 'The product receives data from an upstream component, but does not filter or incorrectly filters special elements before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4f5df411-2746-4b90-906d-b1ef65cab3aa', 'CWE-791', 'Incomplete Filtering of Special Elements', 'The product receives data from an upstream component, but does not completely filter special elements before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8fff9063-7b7e-46a5-8324-45c99df34e7d', 'CWE-792', 'Incomplete Filtering of One or More Instances of Special Elements', 'The product receives data from an upstream component, but does not completely filter one or more instances of special elements before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3e7e12eb-2de9-4e57-a917-ff4b465f01f6', 'CWE-793', 'Only Filtering One Instance of a Special Element', 'The product receives data from an upstream component, but only filters a single instance of a special element before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2e1c0411-9149-4cfe-90f3-bd61d3b4ce9e', 'CWE-794', 'Incomplete Filtering of Multiple Instances of Special Elements', 'The product receives data from an upstream component, but does not filter all instances of a special element before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2ce9724c-52d4-4f6d-9f7c-9bc010cfabc1', 'CWE-795', 'Only Filtering Special Elements at a Specified Location', 'The product receives data from an upstream component, but only accounts for special elements at a specified location, thereby missing remaining special elements that may exist before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('00aa8616-d642-4a63-a335-c702d1fbbd26', 'CWE-796', 'Only Filtering Special Elements Relative to a Marker', 'The product receives data from an upstream component, but only accounts for special elements positioned relative to a marker (e.g. at the beginning/end of a string; the second argument), thereby missing remaining special elements that may exist before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5fd78dfe-8fcc-4beb-a8a1-86fed6ecad52', 'CWE-797', 'Only Filtering Special Elements at an Absolute Position', 'The product receives data from an upstream component, but only accounts for special elements at an absolute position (e.g. byte number 10), thereby missing remaining special elements that may exist before sending it to a downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bc090f22-687f-4f2e-893e-6b5966d41045', 'CWE-798', 'Use of Hard-coded Credentials', 'The product contains hard-coded credentials, such as a password or cryptographic key.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('047b5937-c52e-4f8f-be29-afd96f6b7973', 'CWE-799', 'Improper Control of Interaction Frequency', 'The product does not properly limit the number or frequency of interactions that it has with an actor, such as the number of incoming requests.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c33d0a20-3a8f-4dbb-845c-0bbeef0e554d', 'CWE-804', 'Guessable CAPTCHA', 'The product uses a CAPTCHA challenge, but the challenge can be guessed or automatically recognized by a non-human actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f8ca12b3-29a9-4ec6-94bc-4b54fa87322b', 'CWE-805', 'Buffer Access with Incorrect Length Value', 'The product uses a sequential operation to read or write a buffer, but it uses an incorrect length value that causes it to access memory that is outside of the bounds of the buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a496c30f-0dc1-431f-94b0-71cafa9a7cdb', 'CWE-806', 'Buffer Access Using Size of Source Buffer', 'The product uses the size of a source buffer when reading from or writing to a destination buffer, which may cause it to access memory that is outside of the bounds of the buffer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7ff96e32-231e-4e78-9b71-8a2d2599193e', 'CWE-807', 'Reliance on Untrusted Inputs in a Security Decision', 'The product uses a protection mechanism that relies on the existence or values of an input, but the input can be modified by an untrusted actor in a way that bypasses the protection mechanism.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('154ea80f-9918-4bc9-8224-d5f2a4393487', 'CWE-820', 'Missing Synchronization', 'The product utilizes a shared resource in a concurrent manner but does not attempt to synchronize access to the resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e54a444d-c14a-49bf-bb3f-75afab60790f', 'CWE-821', 'Incorrect Synchronization', 'The product utilizes a shared resource in a concurrent manner, but it does not correctly synchronize access to the resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bd4ac19d-3ac6-4518-bf08-f03349237172', 'CWE-822', 'Untrusted Pointer Dereference', 'The product obtains a value from an untrusted source, converts this value to a pointer, and dereferences the resulting pointer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('894f1ee6-8430-42ac-a76f-586893a7c715', 'CWE-823', 'Use of Out-of-range Pointer Offset', 'The product performs pointer arithmetic on a valid pointer, but it uses an offset that can point outside of the intended range of valid memory locations for the resulting pointer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('60cd6863-abea-449e-846e-c836632fe6ff', 'CWE-824', 'Access of Uninitialized Pointer', 'The product accesses or uses a pointer that has not been initialized.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7d6f091c-60bc-4dfb-ba39-7f410fa180a0', 'CWE-825', 'Expired Pointer Dereference', 'The product dereferences a pointer that contains a location for memory that was previously valid, but is no longer valid.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f9f5d929-07af-4069-873a-469fab78e6bd', 'CWE-826', 'Premature Release of Resource During Expected Lifetime', 'The product releases a resource that is still intended to be used by itself or another actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6ae9cd71-b7df-4452-95a2-5cfbf5067bcc', 'CWE-827', 'Improper Control of Document Type Definition', 'The product does not restrict a reference to a Document Type Definition (DTD) to the intended control sphere. This might allow attackers to reference arbitrary DTDs, possibly causing the product to expose files, consume excessive system resources, or execute arbitrary http requests on behalf of the attacker.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('684a6598-8a38-415d-8a5d-aa36bc259108', 'CWE-828', 'Signal Handler with Functionality that is not Asynchronous-Safe', 'The product defines a signal handler that contains code sequences that are not asynchronous-safe, i.e., the functionality is not reentrant, or it can be interrupted.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d1c7f789-5367-487e-9c65-68b8c7718fd7', 'CWE-829', 'Inclusion of Functionality from Untrusted Control Sphere', 'The product imports, requires, or includes executable functionality (such as a library) from a source that is outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('96a09c6e-c2f2-4e7a-8093-2f90c65eed97', 'CWE-830', 'Inclusion of Web Functionality from an Untrusted Source', 'The product includes web functionality (such as a web widget) from another domain, which causes it to operate within the domain of the product, potentially granting total access and control of the product to the untrusted source.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('36d84696-417c-4278-9a2e-cee1febfec7b', 'CWE-831', 'Signal Handler Function Associated with Multiple Signals', 'The product defines a function that is used as a handler for more than one signal.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('53f34062-588e-43d4-ae81-0a777e37876c', 'CWE-832', 'Unlock of a Resource that is not Locked', 'The product attempts to unlock a resource that is not locked.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7631d5d5-5b6f-4205-b56c-85bac7f205be', 'CWE-833', 'Deadlock', 'The product contains multiple threads or executable segments that are waiting for each other to release a necessary lock, resulting in deadlock.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3d9d04eb-90f8-474e-88da-f69f6332c889', 'CWE-834', 'Excessive Iteration', 'The product performs an iteration or loop without sufficiently limiting the number of times that the loop is executed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b559e21d-b70d-47eb-9298-340e5ca9dd58', 'CWE-835', 'Loop with Unreachable Exit Condition (''Infinite Loop'')', 'The product contains an iteration or loop with an exit condition that cannot be reached, i.e., an infinite loop.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('60076bb8-8c1b-44bd-895e-17b0b2ce641f', 'CWE-836', 'Use of Password Hash Instead of Password for Authentication', 'The product records password hashes in a data store, receives a hash of a password from a client, and compares the supplied hash to the hash obtained from the data store.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2e20758e-f054-4d14-807b-51a81dbfd833', 'CWE-837', 'Improper Enforcement of a Single, Unique Action', 'The product requires that an actor should only be able to perform an action once, or to have only one unique action, but the product does not enforce or improperly enforces this restriction.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('da90f3d0-0fd7-4835-a77d-b6dcf99f25f3', 'CWE-838', 'Inappropriate Encoding for Output Context', 'The product uses or specifies an encoding when generating output to a downstream component, but the specified encoding is not the same as the encoding that is expected by the downstream component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c51c4d9e-f766-49f0-8647-0f8bc02ac0a6', 'CWE-839', 'Numeric Range Comparison Without Minimum Check', 'The product checks a value to ensure that it is less than or equal to a maximum, but it does not also verify that the value is greater than or equal to the minimum.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5b72df24-3b94-4144-8a76-f14f4a03ef3f', 'CWE-841', 'Improper Enforcement of Behavioral Workflow', 'The product supports a session in which more than one behavior must be performed by an actor, but it does not properly ensure that the actor performs the behaviors in the required sequence.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f527ed6c-1dc9-4005-a49d-7f15b125c7e3', 'CWE-842', 'Placement of User into Incorrect Group', 'The product or the administrator places a user into an incorrect group.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e25e27ce-af01-4a86-9e84-5fb8c628151a', 'CWE-843', 'Access of Resource Using Incompatible Type (''Type Confusion'')', 'The product allocates or initializes a resource such as a pointer, object, or variable using one type, but it later accesses that resource using a type that is incompatible with the original type.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3630fd01-e630-41af-94c5-78df3d021018', 'CWE-862', 'Missing Authorization', 'The product does not perform an authorization check when an actor attempts to access a resource or perform an action.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('11b5e37d-595d-4363-a223-182bf8e2a2b6', 'CWE-863', 'Incorrect Authorization', 'The product performs an authorization check when an actor attempts to access a resource or perform an action, but it does not correctly perform the check.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7bb4a53c-2fab-4c8a-ad2c-45684492bc35', 'CWE-908', 'Use of Uninitialized Resource', 'The product uses or accesses a resource that has not been initialized.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d27d514e-604b-486d-8917-13a2dd3d7c88', 'CWE-909', 'Missing Initialization of Resource', 'The product does not initialize a critical resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('259c95c8-d07d-484f-a42c-976d09f36db3', 'CWE-910', 'Use of Expired File Descriptor', 'The product uses or accesses a file descriptor after it has been closed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c1789fbe-5075-42e9-a758-fc96667346b5', 'CWE-911', 'Improper Update of Reference Count', 'The product uses a reference count to manage a resource, but it does not update or incorrectly updates the reference count.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d049b19d-4cba-48cc-8dc8-af28d733374f', 'CWE-912', 'Hidden Functionality', 'The product contains functionality that is not documented, not part of the specification, and not accessible through an interface or command sequence that is obvious to the product''s users or administrators.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fe80764f-d84c-4772-b16d-35ca1c73af92', 'CWE-913', 'Improper Control of Dynamically-Managed Code Resources', 'The product does not properly restrict reading from or writing to dynamically-managed code resources such as variables, objects, classes, attributes, functions, or executable instructions or statements.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('105e8c15-5c83-48a8-a3b2-f41672465331', 'CWE-914', 'Improper Control of Dynamically-Identified Variables', 'The product does not properly restrict reading from or writing to dynamically-identified variables.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b0de7dac-31d2-4d3a-914b-b6ded45b7076', 'CWE-915', 'Improperly Controlled Modification of Dynamically-Determined Object Attributes', 'The product receives input from an upstream component that specifies multiple attributes, properties, or fields that are to be initialized or updated in an object, but it does not properly control which attributes can be modified.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('814bc3bf-f5b2-4e0a-aa11-1529f6828b90', 'CWE-916', 'Use of Password Hash With Insufficient Computational Effort', 'The product generates a hash for a password, but it uses a scheme that does not provide a sufficient level of computational effort that would make password cracking attacks infeasible or expensive.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d4cf147d-8c10-48bf-b54f-55d40e7ac43f', 'CWE-917', 'Improper Neutralization of Special Elements used in an Expression Language Statement (''Expression Language Injection'')', 'The product constructs all or part of an expression language (EL) statement in a framework such as a Java Server Page (JSP) using externally-influenced input from an upstream component, but it does not neutralize or incorrectly neutralizes special elements that could modify the intended EL statement before it is executed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b1c696d0-39bc-4145-8f72-2c0c8004843b', 'CWE-918', 'Server-Side Request Forgery (SSRF)', 'The web server receives a URL or similar request from an upstream component and retrieves the contents of this URL, but it does not sufficiently ensure that the request is being sent to the expected destination.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('40ece951-74ab-4786-a338-9ba82aad9c32', 'CWE-920', 'Improper Restriction of Power Consumption', 'The product operates in an environment in which power is a limited resource that cannot be automatically replenished, but the product does not properly restrict the amount of power that its operation consumes.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d89bc7fa-10fc-4c50-92ca-71e8e827e085', 'CWE-921', 'Storage of Sensitive Data in a Mechanism without Access Control', 'The product stores sensitive information in a file system or device that does not have built-in access control.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('99c18596-805f-43ba-b63d-e77c25a50f96', 'CWE-922', 'Insecure Storage of Sensitive Information', 'The product stores sensitive information without properly limiting read or write access by unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8c59813f-44c5-4d50-a0d0-c1fa3c103fcd', 'CWE-923', 'Improper Restriction of Communication Channel to Intended Endpoints', 'The product establishes a communication channel to (or from) an endpoint for privileged or protected operations, but it does not properly ensure that it is communicating with the correct endpoint.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1c3ca54e-fccb-4a21-a5e4-450d3587fa12', 'CWE-924', 'Improper Enforcement of Message Integrity During Transmission in a Communication Channel', 'The product establishes a communication channel with an endpoint and receives a message from that endpoint, but it does not sufficiently ensure that the message was not modified during transmission.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9b657be3-5d94-4568-9b75-bdb309591ace', 'CWE-925', 'Improper Verification of Intent by Broadcast Receiver', 'The Android application uses a Broadcast Receiver that receives an Intent but does not properly verify that the Intent came from an authorized source.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('204a2048-eaa4-4a78-b7bd-0f80c2bf4254', 'CWE-926', 'Improper Export of Android Application Components', 'The Android application exports a component for use by other applications, but does not properly restrict which applications can launch the component or access the data it contains.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d750f252-6b41-44b7-80f5-387996b7e336', 'CWE-927', 'Use of Implicit Intent for Sensitive Communication', 'The Android application uses an implicit intent for transmitting sensitive data to other applications.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b0238888-3ae9-4319-a86b-9b6b60a85b75', 'CWE-939', 'Improper Authorization in Handler for Custom URL Scheme', 'The product uses a handler for a custom URL scheme, but it does not properly restrict which actors can invoke the handler using the scheme.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('21fc0b63-187e-494d-b809-b5d797c9726e', 'CWE-940', 'Improper Verification of Source of a Communication Channel', 'The product establishes a communication channel to handle an incoming request that has been initiated by an actor, but it does not properly verify that the request is coming from the expected origin.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3da976d6-a2c4-461e-b7f8-12590ab04038', 'CWE-941', 'Incorrectly Specified Destination in a Communication Channel', 'The product creates a communication channel to initiate an outgoing request to an actor, but it does not correctly specify the intended destination for that actor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('620d5499-4274-4512-8425-ba0088d73f28', 'CWE-942', 'Permissive Cross-domain Security Policy with Untrusted Domains', 'The product uses a web-client protection mechanism such as a Content Security Policy (CSP) or cross-domain policy file, but the policy includes untrusted domains with which the web client is allowed to communicate.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('928eff79-d725-4b59-821a-98558f916641', 'CWE-943', 'Improper Neutralization of Special Elements in Data Query Logic', 'The product generates a query intended to access or manipulate data in a data store such as a database, but it does not neutralize or incorrectly neutralizes special elements that can modify the intended logic of the query.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f624dfff-b166-449c-9d15-6aabc9ba0109', 'CWE-1004', 'Sensitive Cookie Without ''HttpOnly'' Flag', 'The product uses a cookie to store sensitive information, but the cookie is not marked with the HttpOnly flag.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d8b53168-3f13-482a-93f3-472578f2118e', 'CWE-1007', 'Insufficient Visual Distinction of Homoglyphs Presented to User', 'The product displays information or identifiers to a user, but the display mechanism does not make it easy for the user to distinguish between visually similar or identical glyphs (homoglyphs), which may cause the user to misinterpret a glyph and perform an unintended, insecure action.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4d5f5227-73fd-444c-9a78-3f3f33b31a85', 'CWE-1021', 'Improper Restriction of Rendered UI Layers or Frames', 'The web application does not restrict or incorrectly restricts frame objects or UI layers that belong to another application or domain.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('644d30c8-3d27-4475-92fe-f675c2ca1f15', 'CWE-1022', 'Use of Web Link to Untrusted Target with window.opener Access', 'The web application produces links to untrusted external sites outside of its sphere of control, but it does not properly prevent the external site from modifying security-critical properties of the window.opener object, such as the location property.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('de80c54a-c00d-401c-94bb-6bf299f0b424', 'CWE-1023', 'Incomplete Comparison with Missing Factors', 'The product performs a comparison between entities that must consider multiple factors or characteristics of each entity, but the comparison does not include one or more of these factors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('85905d14-17f3-4fe2-9a81-47f166fca81d', 'CWE-1024', 'Comparison of Incompatible Types', 'The product performs a comparison between two entities, but the entities are of different, incompatible types that cannot be guaranteed to provide correct results when they are directly compared.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9675132e-7ca8-408e-8586-99d4bafede7b', 'CWE-1025', 'Comparison Using Wrong Factors', 'The code performs a comparison between two entities, but the comparison examines the wrong factors or characteristics of the entities, which can lead to incorrect results and resultant weaknesses.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('938be884-47a7-46bf-9082-0185af56973a', 'CWE-1037', 'Processor Optimization Removal or Modification of Security-critical Code', 'The developer builds a security-critical protection mechanism into the software, but the processor optimizes the execution of the program such that the mechanism is removed or modified.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c0acf5a6-31a9-4d1d-b912-46be97d4db27', 'CWE-1038', 'Insecure Automated Optimizations', 'The product uses a mechanism that automatically optimizes code, e.g. to improve a characteristic such as performance, but the optimizations can have an unintended side effect that might violate an intended security assumption.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a5fd2fe5-0c11-43c8-8568-0cd5001b4e23', 'CWE-1039', 'Inadequate Detection or Handling of Adversarial Input Perturbations in Automated Recognition Mechanism', 'The product uses an automated mechanism such as machine learning to recognize complex data inputs (e.g. image or audio) as a particular concept or category, but it does not properly detect or handle inputs that have been modified or constructed in a way that causes the mechanism to detect a different, incorrect concept.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('26fab4dc-b1bc-4d35-9135-d83f3f717ff5', 'CWE-1041', 'Use of Redundant Code', 'The product has multiple functions, methods, procedures, macros, etc. that contain the same code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c347defc-9d00-4370-b336-d0d88f74d050', 'CWE-1042', 'Static Member Data Element outside of a Singleton Class Element', 'The code contains a member element that is declared as static (but not final), in which its parent class element is not a singleton class - that is, a class element that can be used only once in the ''to'' association of a Create action.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b695b989-785d-49e0-aa5a-51db37d7517d', 'CWE-1043', 'Data Element Aggregating an Excessively Large Number of Non-Primitive Elements', 'The product uses a data element that has an excessively large number of sub-elements with non-primitive data types such as structures or aggregated objects.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4fc83c81-d7be-4de9-807b-f430d8296daf', 'CWE-1044', 'Architecture with Number of Horizontal Layers Outside of Expected Range', 'The product''s architecture contains too many - or too few - horizontal layers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('82912f59-9458-41b2-85eb-621628403657', 'CWE-1045', 'Parent Class with a Virtual Destructor and a Child Class without a Virtual Destructor', 'A parent class has a virtual destructor method, but the parent has a child class that does not have a virtual destructor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4b168153-f5bb-460d-960c-a88abf1f9bb9', 'CWE-1046', 'Creation of Immutable Text Using String Concatenation', 'The product creates an immutable text string using string concatenation operations.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('af5f1a3c-5506-4297-8795-7e55e4a9b43a', 'CWE-1047', 'Modules with Circular Dependencies', 'The product contains modules in which one module has references that cycle back to itself, i.e., there are circular dependencies.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c57b545a-2c6f-41d8-b85d-570ccaffbc7e', 'CWE-1048', 'Invokable Control Element with Large Number of Outward Calls', 'The code contains callable control elements that contain an excessively large number of references to other application objects external to the context of the callable, i.e. a Fan-Out value that is excessively large.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a6c09b57-b063-44c7-a8a8-19544afd49b2', 'CWE-1049', 'Excessive Data Query Operations in a Large Data Table', 'The product performs a data query with a large number of joins and sub-queries on a large data table.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('20c29555-a793-470b-9d27-945ee06bce3a', 'CWE-1050', 'Excessive Platform Resource Consumption within a Loop', 'The product has a loop body or loop condition that contains a control element that directly or indirectly consumes platform resources, e.g. messaging, sessions, locks, or file descriptors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('65b50e12-deb8-480e-97bd-79cd906e05a6', 'CWE-1051', 'Initialization with Hard-Coded Network Resource Configuration Data', 'The product initializes data using hard-coded values that act as network resource identifiers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('89e2cbe4-8a29-44fb-aa44-4875f20eae66', 'CWE-1052', 'Excessive Use of Hard-Coded Literals in Initialization', 'The product initializes a data element using a hard-coded literal that is not a simple integer or static constant element.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('beeefcf6-70b2-4252-8c73-1cf72f889d3a', 'CWE-1053', 'Missing Documentation for Design', 'The product does not have documentation that represents how it is designed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f9358036-6ff4-4755-8cf2-0a249598110e', 'CWE-1054', 'Invocation of a Control Element at an Unnecessarily Deep Horizontal Layer', 'The code at one architectural layer invokes code that resides at a deeper layer than the adjacent layer, i.e., the invocation skips at least one layer, and the invoked code is not part of a vertical utility layer that can be referenced from any horizontal layer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('91e60f2a-38c0-4e28-822d-6fb15fd5775e', 'CWE-1055', 'Multiple Inheritance from Concrete Classes', 'The product contains a class with inheritance from more than one concrete class.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ed948976-d70a-4433-94a8-3a09bf69d0f8', 'CWE-1056', 'Invokable Control Element with Variadic Parameters', 'A named-callable or method control element has a signature that supports a variable (variadic) number of parameters or arguments.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2ddfcb7c-3318-4fde-937c-b6a0b6aed919', 'CWE-1057', 'Data Access Operations Outside of Expected Data Manager Component', 'The product uses a dedicated, central data manager component as required by design, but it contains code that performs data-access operations that do not use this data manager.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('35465cbd-2ee3-4630-8dd3-f09e45ba0db5', 'CWE-1058', 'Invokable Control Element in Multi-Thread Context with non-Final Static Storable or Member Element', 'The code contains a function or method that operates in a multi-threaded environment but owns an unsafe non-final static storable or member data element.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2c4cd9e6-11df-4f93-9246-b1e2f6df64a0', 'CWE-1059', 'Insufficient Technical Documentation', 'The product does not contain sufficient technical or engineering documentation (whether on paper or in electronic form) that contains descriptions of all the relevant software/hardware elements of the product, such as its usage, structure, architectural components, interfaces, design, implementation, configuration, operation, etc.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('84080243-523d-4cbe-87ac-2d89d396bdfe', 'CWE-1060', 'Excessive Number of Inefficient Server-Side Data Accesses', 'The product performs too many data queries without using efficient data processing functionality such as stored procedures.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f3e41dbe-b3f7-43b2-aeb5-5ff013b62e24', 'CWE-1061', 'Insufficient Encapsulation', 'The product does not sufficiently hide the internal representation and implementation details of data or methods, which might allow external components or modules to modify data unexpectedly, invoke unexpected functionality, or introduce dependencies that the programmer did not intend.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9b1425f6-516e-4dbf-8f92-b8bcf6fec8e6', 'CWE-1062', 'Parent Class with References to Child Class', 'The code has a parent class that contains references to a child class, its methods, or its members.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d77ef3b6-bf77-454e-b339-17a0b8ee8b56', 'CWE-1063', 'Creation of Class Instance within a Static Code Block', 'A static code block creates an instance of a class.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5f653424-04a7-455a-8c38-b5aed84d3c00', 'CWE-1064', 'Invokable Control Element with Signature Containing an Excessive Number of Parameters', 'The product contains a function, subroutine, or method whose signature has an unnecessarily large number of parameters/arguments.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9b806bef-165a-40b3-976f-492e8772ce17', 'CWE-1065', 'Runtime Resource Management Control Element in a Component Built to Run on Application Servers', 'The product uses deployed components from application servers, but it also uses low-level functions/methods for management of resources, instead of the API provided by the application server.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('db6ff0cd-4f6c-4a36-88ee-d0b79c7934be', 'CWE-1066', 'Missing Serialization Control Element', 'The product contains a serializable data element that does not have an associated serialization method.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4e8921a1-1fdd-41cc-8ddc-e5deef04b416', 'CWE-1067', 'Excessive Execution of Sequential Searches of Data Resource', 'The product contains a data query against an SQL table or view that is configured in a way that does not utilize an index and may cause sequential searches to be performed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0c348017-17f3-470b-9a9c-9d757d885b4f', 'CWE-1068', 'Inconsistency Between Implementation and Documented Design', 'The implementation of the product is not consistent with the design as described within the relevant documentation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('eb712929-546d-4cf6-bc64-734213e3c6f2', 'CWE-1069', 'Empty Exception Block', 'An invokable code block contains an exception handling block that does not contain any code, i.e. is empty.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('49e5a854-03a4-4f3f-b9b9-fae1367f37c6', 'CWE-1070', 'Serializable Data Element Containing non-Serializable Item Elements', 'The product contains a serializable, storable data element such as a field or member, but the data element contains member elements that are not serializable.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('be6b6e0b-70a5-47c7-a67d-d8dd18d5fe51', 'CWE-1071', 'Empty Code Block', 'The source code contains a block that does not contain any code, i.e., the block is empty.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('53f77396-ecf6-493b-922a-0e6827831c2b', 'CWE-1072', 'Data Resource Access without Use of Connection Pooling', 'The product accesses a data resource through a database without using a connection pooling capability.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('09c1b226-c296-410f-bcf8-fe8a51293c15', 'CWE-1073', 'Non-SQL Invokable Control Element with Excessive Number of Data Resource Accesses', 'The product contains a client with a function or method that contains a large number of data accesses/queries that are sent through a data manager, i.e., does not use efficient database capabilities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d70b8753-0334-4ad1-8ba1-53a352cb1e01', 'CWE-1074', 'Class with Excessively Deep Inheritance', 'A class has an inheritance level that is too high, i.e., it has a large number of parent classes.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('912d573c-4bf0-4775-a9ca-7217c6bf5986', 'CWE-1075', 'Unconditional Control Flow Transfer outside of Switch Block', 'The product performs unconditional control transfer (such as a goto) in code outside of a branching structure such as a switch block.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a1162384-50da-404a-b085-2ccf919226bb', 'CWE-1076', 'Insufficient Adherence to Expected Conventions', 'The product''s architecture, source code, design, documentation, or other artifact does not follow required conventions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ae19ec55-c5cd-4026-92fe-71bbe7815ce3', 'CWE-1077', 'Floating Point Comparison with Incorrect Operator', 'The code performs a comparison such as an equality test between two float (floating point) values, but it uses comparison operators that do not account for the possibility of loss of precision.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('06db0cb1-bbca-4fe4-b81a-3399e1f43efe', 'CWE-1078', 'Inappropriate Source Code Style or Formatting', 'The source code does not follow desired style or formatting for indentation, white space, comments, etc.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('16740399-cd43-4d42-99f1-b316892b5cf5', 'CWE-1079', 'Parent Class without Virtual Destructor Method', 'A parent class contains one or more child classes, but the parent class does not have a virtual destructor method.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a1e9a228-1cb0-44f3-8be9-fbace28d34fc', 'CWE-1080', 'Source Code File with Excessive Number of Lines of Code', 'A source code file has too many lines of code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f48c9aca-d23f-458a-a19d-a2d654867d7f', 'CWE-1082', 'Class Instance Self Destruction Control Element', 'The code contains a class instance that calls the method or function to delete or destroy itself.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7f0cc087-ebf6-480b-ab22-3a2acd5eff04', 'CWE-1083', 'Data Access from Outside Expected Data Manager Component', 'The product is intended to manage data access through a particular data manager component such as a relational or non-SQL database, but it contains code that performs data access operations without using that component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('46771f6c-baa7-4681-acf1-609ad39189d2', 'CWE-1084', 'Invokable Control Element with Excessive File or Data Access Operations', 'A function or method contains too many operations that utilize a data manager or file resource.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5591789b-fcef-4e62-a1a1-ce2243143e3f', 'CWE-1085', 'Invokable Control Element with Excessive Volume of Commented-out Code', 'A function, method, procedure, etc. contains an excessive amount of code that has been commented out within its body.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('534419bc-3b73-4a87-b25c-45df79dfba54', 'CWE-1086', 'Class with Excessive Number of Child Classes', 'A class contains an unnecessarily large number of children.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f5dd399a-daac-426e-9ea1-2ba340d4731e', 'CWE-1087', 'Class with Virtual Method without a Virtual Destructor', 'A class contains a virtual method, but the method does not have an associated virtual destructor.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('69dbabc7-9bd8-4ff4-a404-e0274bfa3c86', 'CWE-1088', 'Synchronous Access of Remote Resource without Timeout', 'The code has a synchronous call to a remote resource, but there is no timeout for the call, or the timeout is set to infinite.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('551d0b65-ffbf-4a2e-9e71-c4dfa26d2304', 'CWE-1089', 'Large Data Table with Excessive Number of Indices', 'The product uses a large data table that contains an excessively large number of indices.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7bc456b1-1c6f-413d-8153-8068ac37f971', 'CWE-1090', 'Method Containing Access of a Member Element from Another Class', 'A method for a class performs an operation that directly accesses a member element from another class.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('16697224-84ff-469e-8097-cedb86dd7489', 'CWE-1091', 'Use of Object without Invoking Destructor Method', 'The product contains a method that accesses an object but does not later invoke the element''s associated finalize/destructor method.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c1d22453-667f-4a62-bfac-3299c921827d', 'CWE-1092', 'Use of Same Invokable Control Element in Multiple Architectural Layers', 'The product uses the same control element across multiple architectural layers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('70a413bb-e8c6-43a2-a1c7-286bc65eba6e', 'CWE-1093', 'Excessively Complex Data Representation', 'The product uses an unnecessarily complex internal representation for its data structures or interrelationships between those structures.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('410013ff-394b-4305-844e-69217680bd27', 'CWE-1094', 'Excessive Index Range Scan for a Data Resource', 'The product contains an index range scan for a large data table, but the scan can cover a large number of rows.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7ae8c10a-82af-46f5-a25b-411e6d7d21c5', 'CWE-1095', 'Loop Condition Value Update within the Loop', 'The product uses a loop with a control flow condition based on a value that is updated within the body of the loop.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5f7da0a3-1f99-4359-807d-7021840cc2df', 'CWE-1096', 'Singleton Class Instance Creation without Proper Locking or Synchronization', 'The product implements a Singleton design pattern but does not use appropriate locking or other synchronization mechanism to ensure that the singleton class is only instantiated once.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5268be97-960e-4213-a5d0-17888eb59941', 'CWE-1097', 'Persistent Storable Data Element without Associated Comparison Control Element', 'The product uses a storable data element that does not have all of the associated functions or methods that are necessary to support comparison.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('32d3bc19-ec64-4180-a9a2-2e502acf47ee', 'CWE-1098', 'Data Element containing Pointer Item without Proper Copy Control Element', 'The code contains a data element with a pointer that does not have an associated copy or constructor method.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2808571b-011e-4463-a7e2-331e6bafe908', 'CWE-1099', 'Inconsistent Naming Conventions for Identifiers', 'The product''s code, documentation, or other artifacts do not consistently use the same naming conventions for variables, callables, groups of related callables, I/O capabilities, data types, file names, or similar types of elements.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1b98d871-d161-4184-8870-8872da1f5c0f', 'CWE-1100', 'Insufficient Isolation of System-Dependent Functions', 'The product or code does not isolate system-dependent functionality into separate standalone modules.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('506a4f0b-9c9f-4077-b31a-341f3307065c', 'CWE-1101', 'Reliance on Runtime Component in Generated Code', 'The product uses automatically-generated code that cannot be executed without a specific runtime support component.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a5938f44-7827-4bac-9f10-f47e9153720e', 'CWE-1102', 'Reliance on Machine-Dependent Data Representation', 'The code uses a data representation that relies on low-level data representation or constructs that may vary across different processors, physical machines, OSes, or other physical components.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f2af88c0-afb3-4146-bb7c-55f5cd120234', 'CWE-1103', 'Use of Platform-Dependent Third Party Components', 'The product relies on third-party components that do not provide equivalent functionality across all desirable platforms.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ecf6570c-0121-4166-a918-ad1525d4bf45', 'CWE-1104', 'Use of Unmaintained Third Party Components', 'The product relies on third-party components that are not actively supported or maintained by the original developer or a trusted proxy for the original developer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7a5a5c3e-9392-4fa8-b855-f39782796a2c', 'CWE-1105', 'Insufficient Encapsulation of Machine-Dependent Functionality', 'The product or code uses machine-dependent functionality, but it does not sufficiently encapsulate or isolate this functionality from the rest of the code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dc27467e-cb74-45cd-98a3-e7f504beeed5', 'CWE-1106', 'Insufficient Use of Symbolic Constants', 'The source code uses literal constants that may need to change or evolve over time, instead of using symbolic constants.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('84752334-7f04-4658-bccb-38ea1990abb1', 'CWE-1107', 'Insufficient Isolation of Symbolic Constant Definitions', 'The source code uses symbolic constants, but it does not sufficiently place the definitions of these constants into a more centralized or isolated location.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a152ed93-590d-4572-b3e3-47db9ff7d6d3', 'CWE-1108', 'Excessive Reliance on Global Variables', 'The code is structured in a way that relies too much on using or setting global variables throughout various points in the code, instead of preserving the associated information in a narrower, more local context.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0e2fdb5e-5dbe-45f9-b550-6ff13de6a7a9', 'CWE-1109', 'Use of Same Variable for Multiple Purposes', 'The code contains a callable, block, or other code element in which the same variable is used to control more than one unique task or store more than one instance of data.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('17f8f575-1ede-4dc4-a4a5-cb15fe72ab3b', 'CWE-1110', 'Incomplete Design Documentation', 'The product''s design documentation does not adequately describe control flow, data flow, system initialization, relationships between tasks, components, rationales, or other important aspects of the design.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d41c7f0c-1f8c-4cc4-8eac-eb1a054df618', 'CWE-1111', 'Incomplete I/O Documentation', 'The product''s documentation does not adequately define inputs, outputs, or system/software interfaces.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cc6f5b84-aba8-4213-9f3c-1b05d4e537dc', 'CWE-1112', 'Incomplete Documentation of Program Execution', 'The document does not fully define all mechanisms that are used to control or influence how product-specific programs are executed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2861075a-6e1d-4236-91af-74d6fff2abc0', 'CWE-1113', 'Inappropriate Comment Style', 'The source code uses comment styles or formats that are inconsistent or do not follow expected standards for the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e6b03d9f-59cd-453b-90ac-95e6eb0c488e', 'CWE-1114', 'Inappropriate Whitespace Style', 'The source code contains whitespace that is inconsistent across the code or does not follow expected standards for the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dc51420f-e24e-4d30-971b-7fa4e4a7d927', 'CWE-1115', 'Source Code Element without Standard Prologue', 'The source code contains elements such as source files that do not consistently provide a prologue or header that has been standardized for the project.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('23e18749-8a20-4ee3-b5b1-c4945dd3191f', 'CWE-1116', 'Inaccurate Source Code Comments', 'The source code contains comments that do not accurately describe or explain aspects of the portion of the code with which the comment is associated.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3a0aa6e7-7109-4e51-ab21-d143efcbbe18', 'CWE-1117', 'Callable with Insufficient Behavioral Summary', 'The code contains a function or method whose signature and/or associated inline documentation does not sufficiently describe the callable''s inputs, outputs, side effects, assumptions, or return codes.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c5691406-38f8-4087-a1a4-71dec3899b35', 'CWE-1118', 'Insufficient Documentation of Error Handling Techniques', 'The documentation does not sufficiently describe the techniques that are used for error handling, exception processing, or similar mechanisms.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3a024cf2-feca-4eff-85e8-3457f4c07441', 'CWE-1119', 'Excessive Use of Unconditional Branching', 'The code uses too many unconditional branches (such as goto).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('70d64989-e381-4c63-b66d-6ae77c126696', 'CWE-1120', 'Excessive Code Complexity', 'The code is too complex, as calculated using a well-defined, quantitative measure.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e7c6cfd0-eda8-4e12-ba34-022098ddf323', 'CWE-1121', 'Excessive McCabe Cyclomatic Complexity', 'The code contains McCabe cyclomatic complexity that exceeds a desirable maximum.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('eaf350d5-ebfd-4ca2-9a2e-7213094bb123', 'CWE-1122', 'Excessive Halstead Complexity', 'The code is structured in a way that a Halstead complexity measure exceeds a desirable maximum.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('47fba842-6c1c-46a6-bca2-8fdd9171164e', 'CWE-1123', 'Excessive Use of Self-Modifying Code', 'The product uses too much self-modifying code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d0d5ae40-ed29-443b-9e69-3ef7ea21cc77', 'CWE-1124', 'Excessively Deep Nesting', 'The code contains a callable or other code grouping in which the nesting / branching is too deep.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('439ef9e7-8412-4d46-abc3-cd4b2d12f340', 'CWE-1125', 'Excessive Attack Surface', 'The product has an attack surface whose quantitative measurement exceeds a desirable maximum.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6b5ca985-66d0-432c-8d80-d55b010ba473', 'CWE-1126', 'Declaration of Variable with Unnecessarily Wide Scope', 'The source code declares a variable in one scope, but the variable is only used within a narrower scope.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7a55e184-e51b-4dfa-87f9-3cfab905aef1', 'CWE-1127', 'Compilation with Insufficient Warnings or Errors', 'The code is compiled without sufficient warnings enabled, which may prevent the detection of subtle bugs or quality issues.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1b509d2f-e84b-415b-bd6a-7d68030a5af3', 'CWE-1164', 'Irrelevant Code', 'The product contains code that is not essential for execution, i.e. makes no state changes and has no side effects that alter data or control flow, such that removal of the code would have no impact to functionality or correctness.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('874cd349-be7f-41e5-984b-5963929f3825', 'CWE-1173', 'Improper Use of Validation Framework', 'The product does not use, or incorrectly uses, an input validation framework that is provided by the source language or an independent library.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('198d0403-3de5-4531-988a-c256441bd20b', 'CWE-1174', 'ASP.NET Misconfiguration: Improper Model Validation', 'The ASP.NET application does not use, or incorrectly uses, the model validation framework.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b88ad1dc-b73c-4dca-aed3-61ffc64bf26b', 'CWE-1176', 'Inefficient CPU Computation', 'The product performs CPU computations using algorithms that are not as efficient as they could be for the needs of the developer, i.e., the computations can be optimized further.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5ef2609d-c1a9-4688-a322-5bcee31927ed', 'CWE-1177', 'Use of Prohibited Code', 'The product uses a function, library, or third party component that has been explicitly prohibited, whether by the developer or the customer.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('48a692b5-cd5d-4bd8-879e-01240899b99e', 'CWE-1188', 'Initialization of a Resource with an Insecure Default', 'The product initializes or sets a resource with a default that is intended to be changed by the product''s installer, administrator, or maintainer, but the default is not secure.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ae58d2f2-1da4-4830-8f5b-a16150a64258', 'CWE-1189', 'Improper Isolation of Shared Resources on System-on-a-Chip (SoC)', 'The System-On-a-Chip (SoC) does not properly isolate shared resources between trusted and untrusted agents.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('93c2003b-59e5-46e3-bc58-1e47182c0772', 'CWE-1190', 'DMA Device Enabled Too Early in Boot Phase', 'The product enables a Direct Memory Access (DMA) capable device before the security configuration settings are established, which allows an attacker to extract data from or gain privileges on the product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('11f5ab9b-9f87-486e-bd63-13c4cbb04ff7', 'CWE-1191', 'On-Chip Debug and Test Interface With Improper Access Control', 'The chip does not implement or does not correctly perform access control to check whether users are authorized to access internal registers and test modes through the physical debug/test interface.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e6ca05d7-b0a1-45ac-8f04-e1d4a1aea0a0', 'CWE-1192', 'Improper Identifier for IP Block used in System-On-Chip (SOC)', 'The System-on-Chip (SoC) does not have unique, immutable identifiers for each of its components.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('de15e077-a9c0-41bd-baa1-9f397d195b01', 'CWE-1193', 'Power-On of Untrusted Execution Core Before Enabling Fabric Access Control', 'The product enables components that contain untrusted firmware before memory and fabric access controls have been enabled.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e086d8af-e375-4121-93fe-626f0ff04671', 'CWE-1204', 'Generation of Weak Initialization Vector (IV)', 'The product uses a cryptographic primitive that uses an Initialization Vector (IV), but the product does not generate IVs that are sufficiently unpredictable or unique according to the expected cryptographic requirements for that primitive.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b8656851-a193-442a-b02d-80e44237b0c1', 'CWE-1209', 'Failure to Disable Reserved Bits', 'The reserved bits in a hardware design are not disabled prior to production. Typically, reserved bits are used for future capabilities and should not support any functional logic in the design. However, designers might covertly use these bits to debug or further develop new capabilities in production hardware. Adversaries with access to these bits will write to them in hopes of compromising hardware state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('38037faf-f916-46d9-a9c6-4f6754de4b9f', 'CWE-1220', 'Insufficient Granularity of Access Control', 'The product implements access controls via a policy or other feature with the intention to disable or restrict accesses (reads and/or writes) to assets in a system from untrusted agents. However, implemented access controls lack required granularity, which renders the control policy too broad because it allows accesses from unauthorized agents to the security-sensitive assets.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9e5104c6-e929-4000-bce3-afc94db843e6', 'CWE-1221', 'Incorrect Register Defaults or Module Parameters', 'Hardware description language code incorrectly defines register defaults or hardware Intellectual Property (IP) parameters to insecure values.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aeac05a6-371a-4f6c-ae10-9ea72f2a2788', 'CWE-1222', 'Insufficient Granularity of Address Regions Protected by Register Locks', 'The product defines a large address region protected from modification by the same register lock control bit. This results in a conflict between the functional requirement that some addresses need to be writable by software during operation and the security requirement that the system configuration lock bit must be set during the boot process.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('acbb4592-8c27-4fc7-8db0-0721e6b96b45', 'CWE-1223', 'Race Condition for Write-Once Attributes', 'A write-once register in hardware design is programmable by an untrusted software component earlier than the trusted software component, resulting in a race condition issue.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('134d0915-ed8b-4d12-a87a-97eff5b1658e', 'CWE-1224', 'Improper Restriction of Write-Once Bit Fields', 'The hardware design control register sticky bits or write-once bit fields are improperly implemented, such that they can be reprogrammed by software.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b6d797d0-efcf-4d67-9684-fc09d003e2b7', 'CWE-1229', 'Creation of Emergent Resource', 'The product manages resources or behaves in a way that indirectly creates a new, distinct resource that can be used by attackers in violation of the intended policy.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('04a56c25-895d-4021-a90a-07ba49999f8e', 'CWE-1230', 'Exposure of Sensitive Information Through Metadata', 'The product prevents direct access to a resource containing sensitive information, but it does not sufficiently limit access to metadata that is derived from the original, sensitive information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('741a3429-289a-4fe1-9f26-eb0e4790822f', 'CWE-1231', 'Improper Prevention of Lock Bit Modification', 'The product uses a trusted lock bit for restricting access to registers, address regions, or other resources, but the product does not prevent the value of the lock bit from being modified after it has been set.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('81c9aa6b-7ee0-418a-900f-f1783ffd01bf', 'CWE-1232', 'Improper Lock Behavior After Power State Transition', 'Register lock bit protection disables changes to system configuration once the bit is set. Some of the protected registers or lock bits become programmable after power state transitions (e.g., Entry and wake from low power sleep modes) causing the system configuration to be changeable.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('29c7cda0-bb7d-4bec-a043-5f965ebb3d9f', 'CWE-1233', 'Security-Sensitive Hardware Controls with Missing Lock Bit Protection', 'The product uses a register lock bit protection mechanism, but it does not ensure that the lock bit prevents modification of system registers or controls that perform changes to important hardware system configuration.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3c3fa1d6-5393-4037-9bc0-85970ea212b5', 'CWE-1234', 'Hardware Internal or Debug Modes Allow Override of Locks', 'System configuration protection may be bypassed during debug mode.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('124ea109-2ab6-4d29-b14e-cd018c3fa63d', 'CWE-1235', 'Incorrect Use of Autoboxing and Unboxing for Performance Critical Operations', 'The code uses boxed primitives, which may introduce inefficiencies into performance-critical operations.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('42e1f1f8-4ba6-414f-96e0-89c27c5aecf3', 'CWE-1236', 'Improper Neutralization of Formula Elements in a CSV File', 'The product saves user-provided information into a Comma-Separated Value (CSV) file, but it does not neutralize or incorrectly neutralizes special elements that could be interpreted as a command when the file is opened by a spreadsheet product.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3fc8681a-bd16-4c91-ac81-9c1958804841', 'CWE-1239', 'Improper Zeroization of Hardware Register', 'The hardware product does not properly clear sensitive information from built-in registers when the user of the hardware block changes.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aaf4b8f4-9b22-4159-8b00-e50adf6b8767', 'CWE-1240', 'Use of a Cryptographic Primitive with a Risky Implementation', 'To fulfill the need for a cryptographic primitive, the product implements a cryptographic algorithm using a non-standard, unproven, or disallowed/non-compliant cryptographic implementation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a0e9ca9e-289a-475d-b91c-63d0b82b48b9', 'CWE-1241', 'Use of Predictable Algorithm in Random Number Generator', 'The device uses an algorithm that is predictable and generates a pseudo-random number.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d505aac0-b0d6-452b-812c-4799ef9f18e6', 'CWE-1242', 'Inclusion of Undocumented Features or Chicken Bits', 'The device includes chicken bits or undocumented features that can create entry points for unauthorized actors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('db293a4c-2a56-4c62-bc39-7cd2e5c7ee6f', 'CWE-1243', 'Sensitive Non-Volatile Information Not Protected During Debug', 'Access to security-sensitive information stored in fuses is not limited during debug.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7ee22381-0a13-490b-b3aa-a8c4f55b96d5', 'CWE-1244', 'Internal Asset Exposed to Unsafe Debug Access Level or State', 'The product uses physical debug or test interfaces with support for multiple access levels, but it assigns the wrong debug access level to an internal asset, providing unintended access to the asset from untrusted debug agents.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0b16a79a-6e18-4728-ac5e-32dbbc56cc7e', 'CWE-1245', 'Improper Finite State Machines (FSMs) in Hardware Logic', 'Faulty finite state machines (FSMs) in the hardware logic allow an attacker to put the system in an undefined state, to cause a denial of service (DoS) or gain privileges on the victim''s system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e9e28984-c68f-4f93-9c0e-bdacf5579f94', 'CWE-1246', 'Improper Write Handling in Limited-write Non-Volatile Memories', 'The product does not implement or incorrectly implements wear leveling operations in limited-write non-volatile memories.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('45901221-4d7c-49c6-85f7-4cff0e51d70c', 'CWE-1247', 'Improper Protection Against Voltage and Clock Glitches', 'The device does not contain or contains incorrectly implemented circuitry or sensors to detect and mitigate voltage and clock glitches and protect sensitive information or software contained on the device.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a25a0369-4bf6-476a-bee1-be5221fa85ff', 'CWE-1248', 'Semiconductor Defects in Hardware Logic with Security-Sensitive Implications', 'The security-sensitive hardware module contains semiconductor defects.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9124f86b-639f-4ecf-be51-89d917a5bc4b', 'CWE-1249', 'Application-Level Admin Tool with Inconsistent View of Underlying Operating System', 'The product provides an application for administrators to manage parts of the underlying operating system, but the application does not accurately identify all of the relevant entities or resources that exist in the OS; that is, the application''s model of the OS''s state is inconsistent with the OS''s actual state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f298cf8f-1432-407a-ab68-47211e0a229c', 'CWE-1250', 'Improper Preservation of Consistency Between Independent Representations of Shared State', 'The product has or supports multiple distributed components or sub-systems that are each required to keep their own local copy of shared data - such as state or cache - but the product does not ensure that all local copies remain consistent with each other.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0daff4b4-e32a-4faf-b47c-e90c31146c3f', 'CWE-1251', 'Mirrored Regions with Different Values', 'The product''s architecture mirrors regions without ensuring that their contents always stay in sync.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ae3dace3-ebaf-4dab-ad65-0330f4d484a7', 'CWE-1252', 'CPU Hardware Not Configured to Support Exclusivity of Write and Execute Operations', 'The CPU is not configured to provide hardware support for exclusivity of write and execute operations on memory. This allows an attacker to execute data from all of memory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('6e27a502-f605-4922-b04d-83cd49b3253c', 'CWE-1253', 'Incorrect Selection of Fuse Values', 'The logic level used to set a system to a secure state relies on a fuse being unblown.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bfe8236a-3ec8-4ba2-99ec-7b2c41b02c98', 'CWE-1254', 'Incorrect Comparison Logic Granularity', 'The product''s comparison logic is performed over a series of steps rather than across the entire string in one operation. If there is a comparison logic failure on one of these steps, the operation may be vulnerable to a timing attack that can result in the interception of the process for nefarious purposes.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9d2210a1-c64e-461b-b7fc-bdbe5f13a9b9', 'CWE-1255', 'Comparison Logic is Vulnerable to Power Side-Channel Attacks', 'A device''s real time power consumption may be monitored during security token evaluation and the information gleaned may be used to determine the value of the reference token.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e9d7f47d-f1bd-42bb-97fc-833d99924cc7', 'CWE-1256', 'Improper Restriction of Software Interfaces to Hardware Features', 'The product provides software-controllable device functionality for capabilities such as power and clock management, but it does not properly limit functionality that can lead to modification of hardware memory or register bits, or the ability to observe physical side channels.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e5b1349a-2afa-426e-8e1b-c1cc4b1a2332', 'CWE-1257', 'Improper Access Control Applied to Mirrored or Aliased Memory Regions', 'Aliased or mirrored memory regions in hardware designs may have inconsistent read/write permissions enforced by the hardware. A possible result is that an untrusted agent is blocked from accessing a memory region but is not blocked from accessing the corresponding aliased memory region.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('64b329cf-b56c-47c0-a0b2-219e2d1cf5bb', 'CWE-1258', 'Exposure of Sensitive System Information Due to Uncleared Debug Information', 'The hardware does not fully clear security-sensitive values, such as keys and intermediate values in cryptographic operations, when debug mode is entered.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a6bf799a-ca3c-4477-8834-d4457641e9fb', 'CWE-1259', 'Improper Restriction of Security Token Assignment', 'The System-On-A-Chip (SoC) implements a Security Token mechanism to differentiate what actions are allowed or disallowed when a transaction originates from an entity. However, the Security Tokens are improperly protected.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a524fd56-26e2-45b2-bfa2-1f9e8c17af08', 'CWE-1260', 'Improper Handling of Overlap Between Protected Memory Ranges', 'The product allows address regions to overlap, which can result in the bypassing of intended memory protection.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('61e7ae2d-7a53-47f8-9005-7afc23952935', 'CWE-1261', 'Improper Handling of Single Event Upsets', 'The hardware logic does not effectively handle when single-event upsets (SEUs) occur.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3d1ad6dd-a189-4452-be45-08f3dd4e0f04', 'CWE-1262', 'Improper Access Control for Register Interface', 'The product uses memory-mapped I/O registers that act as an interface to hardware functionality from software, but there is improper access control to those registers.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7e7bd615-4376-4f80-87de-f55b2ed6a297', 'CWE-1263', 'Improper Physical Access Control', 'The product is designed with access restricted to certain information, but it does not sufficiently protect against an unauthorized actor with physical access to these areas.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3d6c2087-4e38-466e-80ab-6d28367096b9', 'CWE-1264', 'Hardware Logic with Insecure De-Synchronization between Control and Data Channels', 'The hardware logic for error handling and security checks can incorrectly forward data before the security check is complete.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fa5e9ebc-3353-40dc-bc74-ab04cce3ee1d', 'CWE-1265', 'Unintended Reentrant Invocation of Non-reentrant Code Via Nested Calls', 'The product invokes code that is believed to be reentrant, but the code performs a call that unintentionally produces a nested invocation of the non-reentrant code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4a7634f1-929c-416d-95de-c5ec7103ba5b', 'CWE-1266', 'Improper Scrubbing of Sensitive Data from Decommissioned Device', 'The product does not properly provide a capability for the product administrator to remove sensitive data at the time the product is decommissioned. A scrubbing capability could be missing, insufficient, or incorrect.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d96764c6-92ca-4f96-9d2f-fdd8c5ac0c1c', 'CWE-1267', 'Policy Uses Obsolete Encoding', 'The product uses an obsolete encoding mechanism to implement access controls.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dd3e5113-5791-4918-8f54-4358e988b0ed', 'CWE-1268', 'Policy Privileges are not Assigned Consistently Between Control and Data Agents', 'The product''s hardware-enforced access control for a particular resource improperly accounts for privilege discrepancies between control and write policies.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2ea73285-4150-4ce4-9538-8641cc796fce', 'CWE-1269', 'Product Released in Non-Release Configuration', 'The product released to market is released in pre-production or manufacturing configuration.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f070cb86-fff1-47a4-a614-847e61b66ee8', 'CWE-1270', 'Generation of Incorrect Security Tokens', 'The product implements a Security Token mechanism to differentiate what actions are allowed or disallowed when a transaction originates from an entity. However, the Security Tokens generated in the system are incorrect.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e74bf8c3-f2ee-4e47-9600-5affe38ea075', 'CWE-1271', 'Uninitialized Value on Reset for Registers Holding Security Settings', 'Security-critical logic is not set to a known value on reset.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('07bee7fc-0490-435d-b5c1-e1f67ef5aeaf', 'CWE-1272', 'Sensitive Information Uncleared Before Debug/Power State Transition', 'The product performs a power or debug state transition, but it does not clear sensitive information that should no longer be accessible due to changes to information access restrictions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('876cd857-0338-41fb-ad86-c2e1c1cf957d', 'CWE-1273', 'Device Unlock Credential Sharing', 'The credentials necessary for unlocking a device are shared across multiple parties and may expose sensitive information.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('53eda6c6-839f-4c73-b570-18712080bb0f', 'CWE-1274', 'Improper Access Control for Volatile Memory Containing Boot Code', 'The product conducts a secure-boot process that transfers bootloader code from Non-Volatile Memory (NVM) into Volatile Memory (VM), but it does not have sufficient access control or other protections for the Volatile Memory.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f3f37335-b927-4445-8f8e-0d7866101837', 'CWE-1275', 'Sensitive Cookie with Improper SameSite Attribute', 'The SameSite attribute for sensitive cookies is not set, or an insecure value is used.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f7d0fefa-bea6-4dc6-9cc0-855f54102879', 'CWE-1276', 'Hardware Child Block Incorrectly Connected to Parent System', 'Signals between a hardware IP and the parent system design are incorrectly connected causing security risks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d8ba676b-abb9-4638-b01f-722ff040c3dd', 'CWE-1277', 'Firmware Not Updateable', 'The product does not provide its users with the ability to update or patch its firmware to address any vulnerabilities or weaknesses that may be present.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('71ed3277-a01b-49db-ba62-376e60d87e11', 'CWE-1278', 'Missing Protection Against Hardware Reverse Engineering Using Integrated Circuit (IC) Imaging Techniques', 'Information stored in hardware may be recovered by an attacker with the capability to capture and analyze images of the integrated circuit using techniques such as scanning electron microscopy.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('32f7ee65-f8d6-4329-8c53-82ccf84c9193', 'CWE-1279', 'Cryptographic Operations are run Before Supporting Units are Ready', 'Performing cryptographic operations without ensuring that the supporting inputs are ready to supply valid data may compromise the cryptographic result.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('aece2722-7378-4144-8e38-a108dff3cdd4', 'CWE-1280', 'Access Control Check Implemented After Asset is Accessed', 'A product''s hardware-based access control check occurs after the asset has been accessed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('07d61973-3e29-4b66-876f-c15783c8bb9c', 'CWE-1281', 'Sequence of Processor Instructions Leads to Unexpected Behavior', 'Specific combinations of processor instructions lead to undesirable behavior such as locking the processor until a hard reset performed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8b396aa9-8f71-4c9e-8e75-41e657f50f8c', 'CWE-1282', 'Assumed-Immutable Data is Stored in Writable Memory', 'Immutable data, such as a first-stage bootloader, device identifiers, and write-once configuration settings are stored in writable memory that can be re-programmed or updated in the field.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a7054ccc-df84-4260-8bcf-d7bcf3064f40', 'CWE-1283', 'Mutable Attestation or Measurement Reporting Data', 'The register contents used for attestation or measurement reporting data to verify boot flow are modifiable by an adversary.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0edc0f34-3d93-4d37-bce6-644ce1e6ff9e', 'CWE-1284', 'Improper Validation of Specified Quantity in Input', 'The product receives input that is expected to specify a quantity (such as size or length), but it does not validate or incorrectly validates that the quantity has the required properties.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('06bb2e01-8d5a-44bb-a677-16887b0bff4a', 'CWE-1285', 'Improper Validation of Specified Index, Position, or Offset in Input', 'The product receives input that is expected to specify an index, position, or offset into an indexable resource such as a buffer or file, but it does not validate or incorrectly validates that the specified index/position/offset has the required properties.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('c7991794-9763-4b29-b580-edf8a7347ff4', 'CWE-1286', 'Improper Validation of Syntactic Correctness of Input', 'The product receives input that is expected to be well-formed - i.e., to comply with a certain syntax - but it does not validate or incorrectly validates that the input complies with the syntax.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f9e2d578-2a67-4bad-9cad-683cba4c435c', 'CWE-1287', 'Improper Validation of Specified Type of Input', 'The product receives input that is expected to be of a certain type, but it does not validate or incorrectly validates that the input is actually of the expected type.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('46b06ed5-0d88-4b59-91eb-19fc9d4d6ef6', 'CWE-1288', 'Improper Validation of Consistency within Input', 'The product receives a complex input with multiple elements or fields that must be consistent with each other, but it does not validate or incorrectly validates that the input is actually consistent.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('872f887b-60e9-4c78-a4d0-8d0c7989b0d9', 'CWE-1289', 'Improper Validation of Unsafe Equivalence in Input', 'The product receives an input value that is used as a resource identifier or other type of reference, but it does not validate or incorrectly validates that the input is equivalent to a potentially-unsafe value.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9f698f5a-59ab-4dfc-82f7-6219e2a7fe8c', 'CWE-1290', 'Incorrect Decoding of Security Identifiers', 'The product implements a decoding mechanism to decode certain bus-transaction signals to security identifiers. If the decoding is implemented incorrectly, then untrusted agents can now gain unauthorized access to the asset.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('665c8f1d-cc49-44e8-a66c-2f6d85c062b6', 'CWE-1291', 'Public Key Re-Use for Signing both Debug and Production Code', 'The same public key is used for signing both debug and production code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('67656d5b-d427-4cc8-8795-93a01d9dc5f7', 'CWE-1292', 'Incorrect Conversion of Security Identifiers', 'The product implements a conversion mechanism to map certain bus-transaction signals to security identifiers. However, if the conversion is incorrectly implemented, untrusted agents can gain unauthorized access to the asset.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('ca7d3baf-252a-40fa-95aa-07751f7123dd', 'CWE-1293', 'Missing Source Correlation of Multiple Independent Data', 'The product relies on one source of data, preventing the ability to detect if an adversary has compromised a data source.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e91b66b0-29cf-49ba-956a-105b1cf4689a', 'CWE-1294', 'Insecure Security Identifier Mechanism', 'The System-on-Chip (SoC) implements a Security Identifier mechanism to differentiate what actions are allowed or disallowed when a transaction originates from an entity. However, the Security Identifiers are not correctly implemented.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('4b4add65-5c69-44af-a33d-ec4e10cbdfdb', 'CWE-1295', 'Debug Messages Revealing Unnecessary Information', 'The product fails to adequately prevent the revealing of unnecessary and potentially sensitive system information within debugging messages.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('51d43438-ed2b-4c17-aa0b-450514afe453', 'CWE-1296', 'Incorrect Chaining or Granularity of Debug Components', 'The product''s debug components contain incorrect chaining or granularity of debug components.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3717e2eb-ed11-4418-82bd-47e9cd0b263d', 'CWE-1297', 'Unprotected Confidential Information on Device is Accessible by OSAT Vendors', 'The product does not adequately protect confidential information on the device from being accessed by Outsourced Semiconductor Assembly and Test (OSAT) vendors.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8757e49f-2096-4db7-a108-c7fd541d2392', 'CWE-1298', 'Hardware Logic Contains Race Conditions', 'A race condition in the hardware logic results in undermining security guarantees of the system.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('09791287-32f7-4eb5-acfc-15a3285f00e9', 'CWE-1299', 'Missing Protection Mechanism for Alternate Hardware Interface', 'The lack of protections on alternate paths to access control-protected assets (such as unprotected shadow registers and other external facing unguarded interfaces) allows an attacker to bypass existing protections to the asset that are only performed against the primary path.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('54f61160-bd0b-48cf-b087-cfe7403740ae', 'CWE-1300', 'Improper Protection of Physical Side Channels', 'The device does not contain sufficient protection mechanisms to prevent physical side channels from exposing sensitive information due to patterns in physically observable phenomena such as variations in power consumption, electromagnetic emissions (EME), or acoustic emissions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('265d2770-773e-4be2-b983-728439e21215', 'CWE-1301', 'Insufficient or Incomplete Data Removal within Hardware Component', 'The product''s data removal process does not completely delete all data and potentially sensitive information within hardware components.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b6e3f0a9-95b8-4b17-a031-53f5ab09b0b4', 'CWE-1302', 'Missing Source Identifier in Entity Transactions on a System-On-Chip (SOC)', 'The product implements a security identifier mechanism to differentiate what actions are allowed or disallowed when a transaction originates from an entity. A transaction is sent without a security identifier.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('08e384ad-ecdb-4b63-8b1d-761c6299842e', 'CWE-1303', 'Non-Transparent Sharing of Microarchitectural Resources', 'Hardware structures shared across execution contexts (e.g., caches and branch predictors) can violate the expected architecture isolation between contexts.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3530de34-e9c9-46d1-b7ca-db68a2b25627', 'CWE-1304', 'Improperly Preserved Integrity of Hardware Configuration State During a Power Save/Restore Operation', 'The product performs a power save/restore operation, but it does not ensure that the integrity of the configuration state is maintained and/or verified between the beginning and ending of the operation.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2d986609-a7e9-4774-bc31-df8637a57e3e', 'CWE-1310', 'Missing Ability to Patch ROM Code', 'Missing an ability to patch ROM code may leave a System or System-on-Chip (SoC) in a vulnerable state.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b1b1ab1c-6a16-4bea-a9c0-a23164e3fec8', 'CWE-1311', 'Improper Translation of Security Attributes by Fabric Bridge', 'The bridge incorrectly translates security attributes from either trusted to untrusted or from untrusted to trusted when converting from one fabric protocol to another.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fb21b972-d54f-4a57-a2ac-236e53a3deed', 'CWE-1312', 'Missing Protection for Mirrored Regions in On-Chip Fabric Firewall', 'The firewall in an on-chip fabric protects the main addressed region, but it does not protect any mirrored memory or memory-mapped-IO (MMIO) regions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7e066757-2da6-4fe9-9254-936e0ffcf3ab', 'CWE-1313', 'Hardware Allows Activation of Test or Debug Logic at Runtime', 'During runtime, the hardware allows for test or debug logic (feature) to be activated, which allows for changing the state of the hardware. This feature can alter the intended behavior of the system and allow for alteration and leakage of sensitive data by an adversary.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('48e7de1b-b08a-48d8-b337-43c724bcbb06', 'CWE-1314', 'Missing Write Protection for Parametric Data Values', 'The device does not write-protect the parametric data values for sensors that scale the sensor value, allowing untrusted software to manipulate the apparent result and potentially damage hardware or cause operational failure.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('11500db6-ff40-4a5c-bedf-96d61b3159f7', 'CWE-1315', 'Improper Setting of Bus Controlling Capability in Fabric End-point', 'The bus controller enables bits in the fabric end-point to allow responder devices to control transactions on the fabric.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8847feb9-c7d0-4883-b812-0da9f78165fc', 'CWE-1316', 'Fabric-Address Map Allows Programming of Unwarranted Overlaps of Protected and Unprotected Ranges', 'The address map of the on-chip fabric has protected and unprotected regions overlapping, allowing an attacker to bypass access control to the overlapping portion of the protected region.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d77bcef0-d37f-43aa-a661-565c3ef7a901', 'CWE-1317', 'Improper Access Control in Fabric Bridge', 'The product uses a fabric bridge for transactions between two Intellectual Property (IP) blocks, but the bridge does not properly perform the expected privilege, identity, or other access control checks between those IP blocks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fd321f9f-418e-44c0-b034-877b3fbabec8', 'CWE-1318', 'Missing Support for Security Features in On-chip Fabrics or Buses', 'On-chip fabrics or buses either do not support or are not configured to support privilege separation or other security features, such as access control.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cc200f00-b485-4d11-a56b-d6455e1b3937', 'CWE-1319', 'Improper Protection against Electromagnetic Fault Injection (EM-FI)', 'The device is susceptible to electromagnetic fault injection attacks, causing device internal information to be compromised or security mechanisms to be bypassed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('daf25047-8576-4f9e-8c9f-4706b02e7d42', 'CWE-1320', 'Improper Protection for Outbound Error Messages and Alert Signals', 'Untrusted agents can disable alerts about signal conditions exceeding limits or the response mechanism that handles such alerts.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('21e46435-0694-4195-ab84-3ec1159c08fd', 'CWE-1321', 'Improperly Controlled Modification of Object Prototype Attributes (''Prototype Pollution'')', 'The product receives input from an upstream component that specifies attributes that are to be initialized or updated in an object, but it does not properly control modifications of attributes of the object prototype.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('71446f9f-723a-4476-a193-641eeecf1ad4', 'CWE-1322', 'Use of Blocking Code in Single-threaded, Non-blocking Context', 'The product uses a non-blocking model that relies on a single threaded process for features such as scalability, but it contains code that can block when it is invoked.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('769bb8e7-0243-4a7b-b779-29d4b6a3341b', 'CWE-1323', 'Improper Management of Sensitive Trace Data', 'Trace data collected from several sources on the System-on-Chip (SoC) is stored in unprotected locations or transported to untrusted agents.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dd2d743f-d820-4002-9c00-0eb9fafd52b4', 'CWE-1325', 'Improperly Controlled Sequential Memory Allocation', 'The product manages a group of objects or resources and performs a separate memory allocation for each object, but it does not properly limit the total amount of memory that is consumed by all of the combined objects.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('422c6885-ee20-44f3-ad79-17ab16f83434', 'CWE-1326', 'Missing Immutable Root of Trust in Hardware', 'A missing immutable root of trust in the hardware results in the ability to bypass secure boot or execute untrusted or adversarial boot code.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5ae0af67-90db-4182-9361-fb38874b29a3', 'CWE-1327', 'Binding to an Unrestricted IP Address', 'The product assigns the address 0.0.0.0 for a database server, a cloud service/instance, or any computing resource that communicates remotely.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e3476fed-a244-4ec8-9dd4-0e1581342094', 'CWE-1328', 'Security Version Number Mutable to Older Versions', 'Security-version number in hardware is mutable, resulting in the ability to downgrade (roll-back) the boot firmware to vulnerable code versions.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('8f64a47e-2ac8-4f04-b775-16fbcdd18d3a', 'CWE-1329', 'Reliance on Component That is Not Updateable', 'The product contains a component that cannot be updated or patched in order to remove vulnerabilities or significant bugs.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('94218edc-529b-4915-9845-4cd37d64b54f', 'CWE-1330', 'Remanent Data Readable after Memory Erase', 'Confidential information stored in memory circuits is readable or recoverable after being cleared or erased.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('75595fd4-f3ff-40fc-90a7-71635f102aed', 'CWE-1331', 'Improper Isolation of Shared Resources in Network On Chip (NoC)', 'The Network On Chip (NoC) does not isolate or incorrectly isolates its on-chip-fabric and internal resources such that they are shared between trusted and untrusted agents, creating timing channels.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3c8d6db4-5b53-4855-8996-8afeb7de1aa6', 'CWE-1332', 'Improper Handling of Faults that Lead to Instruction Skips', 'The device is missing or incorrectly implements circuitry or sensors that detect and mitigate the skipping of security-critical CPU instructions when they occur.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cee04b3d-7d8d-45dc-9f3e-78d6b9745957', 'CWE-1333', 'Inefficient Regular Expression Complexity', 'The product uses a regular expression with a worst-case computational complexity that is inefficient and possibly exponential.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('400b873f-0d73-4792-a030-544c53e05943', 'CWE-1334', 'Unauthorized Error Injection Can Degrade Hardware Redundancy', 'An unauthorized agent can inject errors into a redundant block to deprive the system of redundancy or put the system in a degraded operating mode.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bd09ba72-9531-4e63-9e91-9dcc5ca83e31', 'CWE-1335', 'Incorrect Bitwise Shift of Integer', 'An integer value is specified to be shifted by a negative amount or an amount greater than or equal to the number of bits contained in the value causing an unexpected or indeterminate result.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('a0e979d5-7e50-43ad-9e94-11250c6628eb', 'CWE-1336', 'Improper Neutralization of Special Elements Used in a Template Engine', 'The product uses a template engine to insert or process externally-influenced input, but it does not neutralize or incorrectly neutralizes special elements or syntax that can be interpreted as template expressions or other code directives when processed by the engine.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f798ea4b-44c7-4e73-a074-603309f6700b', 'CWE-1338', 'Improper Protections Against Hardware Overheating', 'A hardware device is missing or has inadequate protection features to prevent overheating.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('17b62442-5172-442f-82e7-9c8f00fbc8f5', 'CWE-1339', 'Insufficient Precision or Accuracy of a Real Number', 'The product processes a real number with an implementation in which the number''s representation does not preserve required accuracy and precision in its fractional part, causing an incorrect result.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('2d6057a1-644e-46aa-8e88-b9fcf19e6c0c', 'CWE-1341', 'Multiple Releases of Same Resource or Handle', 'The product attempts to close or release a resource or handle more than once, without any successful open between the close operations.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('d2f8bbb2-d8cf-4205-95b3-840c9f064026', 'CWE-1342', 'Information Exposure through Microarchitectural State after Transient Execution', 'The processor does not properly clear microarchitectural state after incorrect microcode assists or speculative execution, resulting in transient execution.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('1d4d0a1d-1250-4d9f-8477-9ea3d0b3f11c', 'CWE-1351', 'Improper Handling of Hardware Behavior in Exceptionally Cold Environments', 'A hardware device, or the firmware running on it, is missing or has incorrect protection features to maintain goals of security primitives when the device is cooled below standard operating temperatures.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('3d1c415f-e715-4c04-918d-3e7aacf028cf', 'CWE-1357', 'Reliance on Insufficiently Trustworthy Component', 'The product is built from multiple separate components, but it uses a component that is not sufficiently trusted to meet expectations for security, reliability, updateability, and maintainability.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('b56fdddc-a163-4f49-bb8c-825749df23d0', 'CWE-1384', 'Improper Handling of Physical or Environmental Conditions', 'The product does not properly handle unexpected physical or environmental conditions that occur naturally or are artificially induced.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('fbd8d842-a5b1-4154-841d-6cb208d4b8f9', 'CWE-1385', 'Missing Origin Validation in WebSockets', 'The product uses a WebSocket, but it does not properly verify that the source of data or communication is valid.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('0ecc1299-1823-4d48-870a-105a0c42727b', 'CWE-1386', 'Insecure Operation on Windows Junction / Mount Point', 'The product opens a file or directory, but it does not properly prevent the name from being associated with a junction or mount point to a destination that is outside of the intended control sphere.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7fefd255-5652-4980-8d98-1607a51f7be4', 'CWE-1389', 'Incorrect Parsing of Numbers with Different Radices', 'The product parses numeric input assuming base 10 (decimal) values, but it does not account for inputs that use a different base number (radix).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9e1382f2-f74c-4799-9c14-677f59b46b8a', 'CWE-1390', 'Weak Authentication', 'The product uses an authentication mechanism to restrict access to specific users or identities, but the mechanism does not sufficiently prove that the claimed identity is correct.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('80ed401d-f47c-4e04-acf0-ebcfd91aa94f', 'CWE-1391', 'Use of Weak Credentials', 'The product uses weak credentials (such as a default key or hard-coded password) that can be calculated, derived, reused, or guessed by an attacker.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7c0cd426-6f58-43e6-9fda-33784082e4af', 'CWE-1392', 'Use of Default Credentials', 'The product uses default credentials (such as passwords or cryptographic keys) for potentially critical functionality.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('bd3e7fe2-c142-49d3-8b66-ca3b57a34acf', 'CWE-1393', 'Use of Default Password', 'The product uses default passwords for potentially critical functionality.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('7cf7cf10-e215-4662-9d25-eccc31fd01a8', 'CWE-1394', 'Use of Default Cryptographic Key', 'The product uses a default cryptographic key for potentially critical functionality.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('cf49a419-1d36-4704-b76d-d2d0dd58b8c6', 'CWE-1395', 'Dependency on Vulnerable Third-Party Component', 'The product has a dependency on a third-party component that contains one or more known vulnerabilities.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('75d7d644-e6af-4556-bdd6-23fdfeb18bd7', 'CWE-1419', 'Incorrect Initialization of Resource', 'The product attempts to initialize a resource but does not correctly do so, which might leave the resource in an unexpected, incorrect, or insecure state when it is accessed.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('650aab70-702d-4fed-a707-f22975f3083d', 'CWE-1420', 'Exposure of Sensitive Information during Transient Execution', 'A processor event or prediction may allow incorrect operations (or correct operations with incorrect data) to execute transiently, potentially exposing data over a covert channel.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f58f8640-dc17-4312-b755-01bf55c76d42', 'CWE-1421', 'Exposure of Sensitive Information in Shared Microarchitectural Structures during Transient Execution', 'A processor event may allow transient operations to access architecturally restricted data (for example, in another address space) in a shared microarchitectural structure (for example, a CPU cache), potentially exposing the data over a covert channel.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('da827f2d-b26b-412d-8634-90246d530ca9', 'CWE-1422', 'Exposure of Sensitive Information caused by Incorrect Data Forwarding during Transient Execution', 'A processor event or prediction may allow incorrect or stale data to be forwarded to transient operations, potentially exposing data over a covert channel.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('071aaf14-c186-48da-84f2-4236de7821ef', 'CWE-1423', 'Exposure of Sensitive Information caused by Shared Microarchitectural Predictor State that Influences Transient Execution', 'Shared microarchitectural predictor state may allow code to influence transient execution across a hardware boundary, potentially exposing data that is accessible beyond the boundary over a covert channel.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('76cdec29-f93b-431c-a823-4f9613d2bc50', 'CWE-1426', 'Improper Validation of Generative AI Output', 'The product invokes a generative AI/ML component whose behaviors and outputs cannot be directly controlled, but the product does not validate or insufficiently validates the outputs to ensure that they align with the intended security, content, or privacy policy.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('dd2ec8b9-9e46-4a41-aa73-e52da693983c', 'CWE-1427', 'Improper Neutralization of Input Used for LLM Prompting', 'The product uses externally-provided data to build prompts provided to large language models (LLMs), but the way these prompts are constructed causes the LLM to fail to distinguish between user-supplied inputs and developer provided system directives.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('e90a0393-78bb-4121-b06a-4d90aa6b516e', 'CWE-1428', 'Reliance on HTTP instead of HTTPS', 'The product provides or relies on use of HTTP communications when HTTPS is available.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('f09defe3-bc10-435b-9020-6c805b386698', 'CWE-1429', 'Missing Security-Relevant Feedback for Unexecuted Operations in Hardware Interface', 'The product has a hardware interface that silently discards operations in situations for which feedback would be security-relevant, such as the timely detection of failures or attacks.', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('5e543ae5-2994-484e-bc3d-0b9ca7e03398', 'CWE-1431', 'Driving Intermediate Cryptographic State/Results to Hardware Module Outputs', 'The product uses a hardware module implementing a cryptographic algorithm that writes sensitive information about the intermediate state or results of its cryptographic operations via one of its output wires (typically the output port containing the final result).', 'mitre', 'enriched', NOW());
INSERT INTO cwes (id, cwe_id, name, description, source, enrichment_status, fetched_at) VALUES ('9ff10c1c-da85-49c3-83a3-efa28714a9e2', 'CWE-1434', 'Insecure Setting of Generative AI/ML Model Inference Parameters', 'The product has a component that relies on a generative AI/ML model configured with inference parameters that produce an unacceptably high rate of erroneous or unexpected outputs.', 'mitre', 'enriched', NOW());
